/* ХЛБ app bundle v1.97 — modules, off-critical */

/* ===== module: core-ext ===== */
const SIGNATURE_B64 = '';
const SEAL_B64 = '';
/* ================= CORE-EXT: ядро супер-приложения =================
   Кошелёк (лицевой счёт), i18n, попапы, печать/подпись, verified, admin-auth.
   Все модули опираются на эти API. */

/* ---------- КОШЕЛЁК / ЛИЦЕВОЙ СЧЁТ ---------- */
const WALLET = (()=>{ try{ return JSON.parse(localStorage.getItem('oko-wallet'))||null; }catch(e){ return null; } })() || {
  acc: 'ХЛБ-' + String(Math.floor(1e7 + Math.random()*9e7)),
  balance: 2500,            // стартовый бонус прототипа
  hold: 0,
  ledger: [ {t:'+', sum:2500, why:'Приветственный бонус ХЛБ', at: Date.now()} ]
};
function walletSave(){ try{ localStorage.setItem('oko-wallet', JSON.stringify(WALLET)); }catch(e){} }
function fmtMoney(n){ return (Math.round(n*100)/100).toLocaleString('ru-RU').replace(/,/g,' ') + ' ₽'; }
function walletAdd(sum, why){
  WALLET.balance += sum;
  WALLET.ledger.unshift({t:'+', sum, why, at: Date.now()});
  walletSave(); walletNotifyRender();
}
function walletCharge(sum, why){
  if(WALLET.balance < sum){
    toast('Недостаточно средств — пополни кошелёк');
    if(typeof showTab==='function' && document.getElementById('screen-wallet')) showTab('wallet');
    return false;
  }
  WALLET.balance -= sum;
  WALLET.ledger.unshift({t:'-', sum, why, at: Date.now()});
  walletSave(); walletNotifyRender();
  return true;
}
function walletNotifyRender(){ if(typeof renderWallet==='function' && document.getElementById('screen-wallet') && document.getElementById('screen-wallet').classList.contains('active')) renderWallet(); }

/* Доход ХЛБ (комиссии/маржа) — видит только владелец в админке */
const ХЛБ_REVENUE = (()=>{ try{ return JSON.parse(localStorage.getItem('oko-revenue'))||[]; }catch(e){ return []; } })();
function hlbEarn(sum, src){
  ХЛБ_REVENUE.unshift({sum: Math.round(sum*100)/100, src, at: Date.now()});
  if(ХЛБ_REVENUE.length > 400) ХЛБ_REVENUE.length = 400;
  try{ localStorage.setItem('oko-revenue', JSON.stringify(ХЛБ_REVENUE)); }catch(e){}
}
function okoRevenueTotal(){ return ХЛБ_REVENUE.reduce((s,r)=>s+r.sum,0); }

/* ---------- i18n ЯДРО ---------- */
let LANG = (()=>{ try{ return localStorage.getItem('oko-lang')||'ru'; }catch(e){ return 'ru'; } })();
const I18N = {};
function regT(dict){ for(const k in dict) I18N[k] = dict[k]; }
function t(k){ const e = I18N[k]; return e ? (e[LANG] || e.ru || k) : k; }
const LANG_HOOKS = [];
function onLangChange(fn){ LANG_HOOKS.push(fn); }
function setLang(l){
  LANG = l; try{ localStorage.setItem('oko-lang', l); }catch(e){}
  document.documentElement.lang = l;
  LANG_HOOKS.forEach(fn=>{ try{ fn(l); }catch(e){} });
  toast(l==='ru' ? 'Язык: русский' : 'Language: English');
}

/* ---------- ВЕРИФИКАЦИЯ (синяя галочка) ---------- */
(function addVerifiedSymbol(){
  const defs = document.querySelector('svg defs');
  if(!defs) return;
  const s = document.createElementNS('http://www.w3.org/2000/svg','symbol');
  s.setAttribute('id','i-verified'); s.setAttribute('viewBox','0 0 100 100');
  s.innerHTML = '<path d="M50 6l11 9 14-2 5 13 13 5-2 14 9 11-9 11 2 14-13 5-5 13-14-2-11 9-11-9-14 2-5-13-13-5 2-14-9-11 9-11-2-14 13-5 5-13 14 2z" fill="#9AFF00" stroke="none"/><path d="M32 52l12 12 24-28" fill="none" stroke="#0a0a0a" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/>';
  defs.appendChild(s);
})();
const VERIFIED = new Set(['Артём Бриус','ХЛБ','Команда ХЛБ','Поддержка ХЛБ']);
function vBadge(name, size){
  return VERIFIED.has(name) ? `<svg class="i fill" style="width:${size||'0.95em'};height:${size||'0.95em'};vertical-align:-0.12em;margin-left:3px"><use href="#i-verified"/></svg>` : '';
}

/* ---------- АДМИН-АУТЕНТИФИКАЦИЯ (владелец) ---------- */
const ADMIN_EMAIL = 'hlbapp.ru@gmail.com';
const ADMIN_HASH = 'ccf4cf77b15f3d07726458af3713a4f2ea1ec60ff55d2589e9706e63a6ab3077'; // sha-256, пароль не хранится
async function sha256hex(str){
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(str));
  return [...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('');
}
function isOwner(){ return PROFILE.role === 'owner'; }
async function adminLogin(email, pass){
  if((email||'').trim().toLowerCase() !== ADMIN_EMAIL) return false;
  if(await sha256hex(pass||'') !== ADMIN_HASH) return false;
  PROFILE.role = 'owner'; PROFILE.tier = 'PRO';
  PROFILE.ceo = true; VERIFIED.add(PROFILE.name);
  try{ localStorage.setItem('oko-owner','1'); }catch(e){}
  return true;
}
(function restoreOwner(){ try{ if(localStorage.getItem('hlb-owner')==='1'){ PROFILE.role='owner'; PROFILE.ceo=true; VERIFIED.add(PROFILE.name); } }catch(e){} })();

/* ---------- ПЕЧАТЬ ОРГАНИЗАЦИИ (официальный вид, синяя) ---------- */
