/* ---- вычисляем плоский AC_COURSE, метаданные курсов AC_COURSES и границы блоков AC_BLOCKS ---- */
const AC_COURSE = [];
const AC_COURSES = [];
const AC_BLOCKS = [];
AC_DIRS.forEach(d=>{
  const from = AC_COURSE.length;
  d.blocks.forEach(b=>{
    const lessons = (b.seed||[]).concat(acPack(b.id));
    const bf = AC_COURSE.length;
    lessons.forEach(L=>AC_COURSE.push(L));
    AC_BLOCKS.push({dir:d.id, id:b.id, title:b.title, from:bf, count:lessons.length});
  });
  const count = AC_COURSE.length - from;
  const nb = d.blocks.length;
  AC_COURSES.push({
    id:d.id, title:d.title, tag:d.tag, free:d.free, minTier:d.minTier, price:d.price,
    author:d.author, outcomes:d.outcomes, c1:d.c1, c2:d.c2, from, count,
    blocks:d.blocks.map(b=>b.id),
    sub:`${nb} ${acPlural(nb,['блок','блока','блоков'])} · ${count} ${acPlural(count,['урок','урока','уроков'])} · сертификат за направление`,
  });
});
/* блоки конкретного курса */
function acCourseBlocks(ci){ const id=AC_COURSES[ci].id; return AC_BLOCKS.filter(b=>b.dir===id); }
const AC_FEE = 0.10;   // комиссия платформы ХЛБ с продажи курса (как в каналах)

/* индекс курса по глобальному номеру урока */
function acCourseOf(i){
  for(let c=0;c<AC_COURSES.length;c++){
    const m=AC_COURSES[c];
    if(i>=m.from && i<m.from+m.count) return c;
  }
  return 0;
}
function acLocalNo(i){ return i - AC_COURSES[acCourseOf(i)].from + 1; }        // номер урока внутри курса (с 1)
function acCourseLen(ci){ return AC_COURSES[ci].count; }
function acCourseFirst(ci){ return AC_COURSES[ci].from; }
function acCourseIdx(ci){ const m=AC_COURSES[ci], a=[]; for(let i=0;i<m.count;i++) a.push(m.from+i); return a; }
/* доступ к курсу: бесплатный / куплен / открыт подпиской */
function acOwnsCourse(ci){ try{ return !!(acS.owned && acS.owned[AC_COURSES[ci].id]); }catch(e){ return false; } }
function acCourseAccessible(ci){
  const m=AC_COURSES[ci];
  if(m.free) return true;
  if(acOwnsCourse(ci)) return true;
  return (typeof okoHasSub==='function') ? okoHasSub(m.minTier) : false;
}
function acCoursePctOf(ci){
  const idx=acCourseIdx(ci); if(!idx.length) return 0;
  let s=0; idx.forEach(i=>s+=acLessonPct(i));
  return Math.round(s/idx.length);
}
function acCourseDone(ci){ return acCourseIdx(ci).every(i=>acLessonDone(i)); }
function acCourseCertCount(ci){ return acDirCert(ci) ? 1 : 0; }

/* агрегаты по курсу: сколько всего слайдов, вопросов, игр, видео, минут */
function acCourseStats(ci){
  const idx = acCourseIdx(ci);
  let slides=0, quiz=0, games=0, vids=0, mins=0;
  idx.forEach(i=>{
    const L = AC_COURSE[i];
    slides += L.slides.length;
    quiz   += L.quiz.length;
    if(L.pairs && L.pairs.length) games++;
    if(L.videoUrl) vids++;
    const m = /^(\d+):(\d+)$/.exec(L.dur||'');
    if(m) mins += (+m[1]) + (+m[2])/60;
  });
  return {lessons:idx.length, slides, quiz, games, vids, mins:Math.max(1,Math.round(mins))};
}

/* ---------- состояние (localStorage oko-academy, per-урок) ---------- */
function acNewLS(){
  return {video:false, slides:false, test:false, testScore:0, task:false, taskText:'',
          game:false, gameWrong:null, slideMax:0, cert:null};
}
function acLoadState(){
  let s = null;
  try{ s = JSON.parse(localStorage.getItem('oko-academy')); }catch(e){}
  if(!s) return {lessons:{}, certs:[]};
  if(s.lessons){ if(!Array.isArray(s.certs)) s.certs = []; return s; }
  /* миграция старого одноурочного формата → урок 0 */
  const l0 = Object.assign(acNewLS(), {
    video:!!s.video, slides:!!s.slides, test:!!s.test, testScore:s.testScore||0,
    task:!!s.task, taskText:s.taskText||'', game:!!s.game,
    gameWrong:(s.gameWrong===undefined?null:s.gameWrong), slideMax:s.slideMax||0,
    cert:s.cert||null
  });
  const fix = c => c ? Object.assign({lesson:0, lessonTitle:AC_COURSE[0].title}, c) : c;
  l0.cert = fix(l0.cert);
  const certs = (s.certs||[]).map(fix);
  return {lessons:{0:l0}, certs};
}
const acS = acLoadState();
function acSave(){ try{ localStorage.setItem('oko-academy', JSON.stringify(acS)); }catch(e){} }
acSave(); // сразу персистим мигрированный формат
/* бэкфилл «освоено»: уже стопроцентные уроки не празднуем задним числом (иначе вау-оверлей
   всплыл бы при повторном прохождении теста/игры на давно пройденном уроке) */
try{ Object.keys(acS.lessons).forEach(k=>{ const ls=acS.lessons[k]; if(ls && !ls.mastered && acItems(+k).every(x=>x[1])) ls.mastered=true; }); acSave(); }catch(e){}

/* ---------- стрик: дни подряд в учёбе ---------- */
function acDayStr(d){
  const x = d || new Date();
  return x.getFullYear() + '-' + String(x.getMonth()+1).padStart(2,'0') + '-' + String(x.getDate()).padStart(2,'0');
}
function acStreak(){
  if(!acS.streak) acS.streak = {last:'', days:0, best:0};
  return acS.streak;
}
function acStreakTouch(){
  const st = acStreak(), today = acDayStr();
  if(st.last === today) return st.days;
  const y = new Date(); y.setDate(y.getDate()-1);
  st.days = (st.last === acDayStr(y)) ? st.days + 1 : 1;
  st.last = today;
  if(st.days > (st.best||0)) st.best = st.days;
  acSave();
  return st.days;
}

/* ---------- следующий урок (первый открытый и не завершённый) ---------- */
function acNextLesson(){
  for(let i=0; i<AC_COURSE.length; i++)
    if(acUnlocked(i) && !acLessonDone(i)) return i;
  return -1;
}
/* глобальный счётчик пройденных уроков — для бейджей уровня */
function acLessonsDoneCount(){
  let n = 0;
  for(let i=0; i<AC_COURSE.length; i++) if(acLessonDone(i)) n++;
  return n;
}
/* последний открытый урок — «Продолжи с этого» на главной */
function acResumeLesson(){
  const last = acS.lastLesson;
  if(typeof last === 'number' && last >= 0 && last < AC_COURSE.length
     && acUnlocked(last) && !acLessonDone(last)) return last;
  return acNextLesson();
}
/* рекомендация следующего курса после текущего */
function acRecommendNext(ci){
  for(let j=ci+1; j<AC_COURSES.length; j++) if(!acCourseDone(j)) return j;
  for(let j=0; j<ci; j++) if(!acCourseDone(j)) return j;
  return -1;
}

let acView = 'home';            // 'home' (каталог) | 'course' (уроки курса) | 'lesson'
let acL = 0;                    // глобальный индекс текущего урока
let acCourse = 0;               // индекс текущего курса (для страницы курса)
let acQuiz = null;              // сессия теста (не персистится)
let acG = null;                 // сессия мини-игры
let acTaskChecking = false;     // «Проверяется куратором»
let acCertUrl = null;           // кэш PNG сертификата
let acCertShownNo = null;
let acBadgeNewIds = [];         // бейджи, открытые в этом ре-рендере (для pop-анимации)

function acCur(){ return AC_COURSE[acL]; }
function acLS(i){
  const k = (i===undefined ? acL : i);
  if(!acS.lessons[k]) acS.lessons[k] = acNewLS();
  return acS.lessons[k];
}

/* ---------- прогресс ---------- */
/* Видео-уроки временно отключены (делаем позже) — уроки текстовые: слайды/конспект/тест/практика/игра.
   videoUrl в данных сохранён, вернём включением AC_VIDEO_ON. */
const AC_VIDEO_ON = false;
function acHasVideo(L){ return AC_VIDEO_ON && L && !!L.videoUrl; }
/* Подпись урока: sub из данных, но при выключенном видео чистим упоминания видео
   и гарантируем «слайды + тест + игра» — от того, что реально есть в уроке. */
function acLessonSub(L){
  if(AC_VIDEO_ON) return String((L && L.sub) || '');
  const parts = [];
  const nS = (L && L.slides || []).length;
  const nQ = (L && L.quiz   || []).length;
  const nP = (L && L.pairs  || []).length;
  if(nS) parts.push(nS + ' ' + acPlural(nS, ['слайд','слайда','слайдов']));
  if(nQ) parts.push('тест из ' + nQ);
  if(nP || nS>=3 || nQ>=3) parts.push('мини-игра');
  return parts.join(' · ');
}
function acItems(i){
  const k = (i===undefined?acL:i);
  const ls = acS.lessons[k] || {};
  const L = AC_COURSE[k] || {};
  const items = [];
  if(acHasVideo(L)) items.push(['Видео просмотрено', !!ls.video]);
  items.push(['Слайды пролистаны', !!ls.slides]);
  items.push(['Тест сдан на '+AC_PASS+'%+', !!ls.test]);
  items.push(['Практика зачтена', !!ls.task]);
  items.push(['Мини-игра пройдена', !!ls.game]);
  return items;
}
function acLessonPct(i){ const it = acItems(i); return it.length ? Math.round(it.filter(x=>x[1]).length / it.length * 100) : 0; }
function acCoursePct(){
  let sum = 0;
  for(let i=0; i<AC_COURSE.length; i++) sum += acLessonPct(i);
  return Math.round(sum / AC_COURSE.length);
}
function acLessonDone(i){ return acLessonPct(i) === 100; }
function acUnlocked(i){
  const ci = acCourseOf(i);
  return acCourseAccessible(ci);   // уроки ПРОПУСКАЕМЫЕ — внутри доступного направления открыты все, без жёстких ограничений
}
/* Сертификат — ЗА ВСЁ НАПРАВЛЕНИЕ (не за урок). Один именной диплом на направление. */
function acDirCert(ci){ try{ const id=AC_COURSES[ci].id; return (acS.certs||[]).find(c=>c && c.dir===id) || null; }catch(e){ return null; } }
function acCertEligible(){ const ci=acCourseOf(acL); return acCourseDone(ci) && !acDirCert(ci); }

/* ================= ДОСТУП К ПРЕМИУМ-КУРСУ (подписка / покупка) ================= */
function acFmtPrice(n){ return (typeof fmtRub==='function') ? fmtRub(n) : (n.toLocaleString('ru-RU')+' ₽'); }
/* открыть курс: если доступен — на страницу курса, иначе гейт */
function acOpenCourse(ci){
  if(!acCourseAccessible(ci)){ acCourseGate(ci); return; }
  acCourse = ci; acView = 'course'; acQuiz = null; acG = null; acTaskChecking = false;
  acRender();
  const m = document.querySelector('main'); if(m) m.scrollTop = 0;
}
/* продающий гейт премиум-курса: подписка ИЛИ разовая покупка */
function acCourseGate(ci){
  const c = AC_COURSES[ci];
  if(acCourseAccessible(ci)){ acOpenCourse(ci); return; }
  if(typeof showPopup !== 'function'){ toast('Курс «'+c.title+'» доступен по подписке '+c.minTier); return; }
  const fee = Math.round(c.price*AC_FEE), net = c.price - fee;
  showPopup({ico:'star', title:'Курс «'+c.title+'»',
    body:'Премиум-курс Академии ХЛБ: <b>'+c.count+' '+acPlural(c.count,['урок','урока','уроков'])+'</b>, тесты, практика и именной сертификат за всё направление. Доступ навсегда.<br><br>Входит в подписку <b style="color:var(--accent)">'+c.minTier+'</b> и выше — либо разовая покупка за <b style="color:var(--accent)">'+acFmtPrice(c.price)+'</b>.<br><span style="font-size:11.5px;color:var(--dim);line-height:1.5">Автор курса получает '+acFmtPrice(net)+', комиссия платформы ХЛБ — 10% ('+acFmtPrice(fee)+').</span>',
    actions:[
      {label:'Открыть по подписке '+c.minTier, onclick:()=>{
        if(typeof okoRequireSub === 'function'){
          okoRequireSub(c.minTier, 'Курс «'+c.title+'» входит в подписку '+c.minTier+'. Оформи её — и получишь этот курс и десятки других возможностей.', ()=>acOpenCourse(ci));
        } else { toast('Подписка временно недоступна'); }
      }},
      {label:'Купить за '+acFmtPrice(c.price), onclick:()=>acBuyCourse(ci)},
      {label:'Позже', ghost:true}
    ]});
}
/* разовая покупка курса за баланс (комиссия — доход владельца) */
function acBuyCourse(ci){
  const c = AC_COURSES[ci];
  if(acCourseAccessible(ci)){ acOpenCourse(ci); return; }
  if(typeof walletCharge !== 'function'){ toast('Кошелёк недоступен'); return; }
  if(walletCharge(c.price, 'Академия · курс «'+c.title+'»')){
    acS.owned = acS.owned || {};
    acS.owned[c.id] = true; acSave();
    const fee = Math.round(c.price*AC_FEE), net = c.price - fee;
    if(typeof hlbEarn === 'function') hlbEarn(c.price, 'Академия · продажа курса «'+c.title+'»');
    acBadgeSync();
    if(typeof showPopup === 'function'){
      showPopup({ico:'check2', title:'Курс открыт',
        body:'Курс «'+esc(c.title)+'» теперь твой навсегда. Списано <b>'+acFmtPrice(c.price)+'</b>: автору начислено '+acFmtPrice(net)+', комиссия платформы ХЛБ 10% — '+acFmtPrice(fee)+'.',
        actions:[{label:'Начать курс', onclick:()=>acOpenCourse(ci)}]});
    } else { toast('Курс открыт: «'+c.title+'»'); acOpenCourse(ci); }
  } else {
    toast('Недостаточно средств — пополни счёт');
  }
}

/* ================= БЕЙДЖИ ДОСТИЖЕНИЙ ================= */
function acAnyLessonTest100(){ for(const k in acS.lessons){ if((acS.lessons[k].testScore||0) >= 100) return true; } return false; }
function acTasksDone(){ let n=0; for(const k in acS.lessons){ if(acS.lessons[k].task) n++; } return n; }
function acBadgeDefs(){
  const st = acStreak();
  const done = acLessonsDoneCount();
  return [
    {id:'first',  ic:'bolt',     t:'Первый шаг',     d:'Пройти первый урок',                on: AC_COURSE.some((_,i)=>acLessonPct(i)>=100) || acS.certs.length>0},
    {id:'l3',     ic:'circle-play',t:'Разгон',       d:'Пройти 3 урока',                    on: done >= 3},
    {id:'l10',    ic:'flag',     t:'Ученик',         d:'Пройти 10 уроков',                  on: done >= 10},
    {id:'l25',    ic:'poll',     t:'Знаток',         d:'Пройти 25 уроков',                  on: done >= 25},
    {id:'l50',    ic:'rocket',   t:'Профи',          d:'Пройти 50 уроков',                  on: done >= 50},
    {id:'l100',   ic:'crown',    t:'Магистр',        d:'Пройти 100 уроков',                 on: done >= 100},
    {id:'cert1',  ic:'star',     t:'Сертификат',     d:'Получить первый сертификат',        on: acS.certs.length >= 1},
    {id:'ace',    ic:'poll',     t:'Отличник',       d:'Сдать тест на 100%',                on: acAnyLessonTest100()},
    {id:'prac',   ic:'edit',     t:'Практик',        d:'Зачесть 3 практики',                on: acTasksDone() >= 3},
    {id:'streak3',ic:'fire',     t:'В огне',         d:'3 дня подряд в учёбе',              on: (st.best||0) >= 3},
    {id:'media',  ic:'rocket',   t:'Медийщик ХЛБ',   d:'Завершить направление «Медийность»', on: acCourseDone(0)},
    {id:'invest', ic:'money',    t:'Инвестор в себя',d:'Открыть премиум-направление',       on: (typeof okoHasSub==='function'&&okoHasSub('PRO')) || (acS.owned && Object.keys(acS.owned).length>0)},
    {id:'mkt',    ic:'briefcase',t:'Маркетолог ХЛБ', d:'Завершить направление «Маркетинг»',  on: AC_COURSES.length>1 && acCourseDone(1)},
    {id:'ai',     ic:'crown',    t:'Нейро-мастер ХЛБ',d:'Завершить направление «Нейросети»', on: AC_COURSES.length>2 && acCourseDone(2)},
    {id:'coll',   ic:'verified', t:'Коллекционер',   d:'Собрать 5 сертификатов',            on: acS.certs.length >= 5},
  ];
}
/* при первом заходе — «засчитать» уже заслуженные молча, чтобы не спамить тостами */
function acBadgeSync(){
  const defs = acBadgeDefs();
  if(!Array.isArray(acS.badgeSeen)){
    acS.badgeSeen = defs.filter(b=>b.on).map(b=>b.id);
    acBadgeNewIds = []; acSave(); return;
  }
  const fresh = defs.filter(b=>b.on && acS.badgeSeen.indexOf(b.id) < 0);
  acBadgeNewIds = fresh.map(b=>b.id);
  if(fresh.length){
    fresh.forEach(b=>acS.badgeSeen.push(b.id));
    acSave();
    fresh.forEach((b,k)=>setTimeout(()=>toast('Награда открыта: «'+b.t+'»'), 260*(k+1)));
  }
}
function acBadgesGridHtml(){
  const defs = acBadgeDefs();
  const earned = defs.filter(b=>b.on).length;
  return `
    <div class="ac-badges-head">
      <span class="ico">${I('verified')}</span>
      <div class="meta"><b>Достижения</b><span>Открыто ${earned} из ${defs.length} — учись и собирай награды</span></div>
    </div>
    <div class="ac-badges">${defs.map((b,i)=>`
      <div class="ac-badge ${b.on?'on':''} ${acBadgeNewIds.indexOf(b.id)>=0?'new':''}" style="animation-delay:${(i*0.045).toFixed(2)}s" title="${b.d}">
        <span class="ic">${I(b.ic)}</span>
        <span class="t">${b.t}</span>
        <span class="d">${b.on?'получено':b.d}</span>
      </div>`).join('')}</div>`;
}

/* ================= РЕНДЕР ================= */
function acRender(){
  const root = document.getElementById('acRoot');
  if(!root) return;
  acBadgeSync();  // до построения HTML — чтобы pop-анимация новых наград попала в разметку
  root.innerHTML = acView === 'lesson' ? acLessonHtml() : acView === 'course' ? acCourseHtml() : acHomeHtml();
  root.classList.remove('fade-in'); void root.offsetWidth; root.classList.add('fade-in');
  if(acView === 'lesson'){
    acRenderVideoBox(); acBindSlides(); acRenderTestBox();
    acRenderTaskBox(); acRenderGameBox(); acRenderProgressBox(); acRenderCertBox();
  } else {
    acAnimRings();
  }
}
/* сведение колец прогресса из «пустого» в цель — эффектный sweep при входе */
function acAnimRings(){
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
    document.querySelectorAll('#acRoot .ac-ring .val, #acRoot .ac-mini-ring .val').forEach(c=>{
      const off = c.getAttribute('data-off');
      if(off !== null) c.style.strokeDashoffset = off;
    });
  }));
}

/* обложка курса (inline-SVG, самодостаточная, тёмная арт-панель в обеих темах).
   hero=true → без крупного текста (его дублирует заголовок-капшн под обложкой). */
function acCourseCover(ci, hero){
  const c = AC_COURSES[ci];
  const c2Len = (c.c2||'').length;
  const c2Size = c2Len > 8 ? Math.max(22, 36 - (c2Len-8)*2) : 36;
  const c2Space = c2Len > 8 ? 1 : 2;
  const bigText = hero ? '' : `
    <text x="26" y="118" font-family="'Bebas Neue',Impact,sans-serif" font-size="26" fill="#fff" letter-spacing="1">${esc(c.c1)}</text>
    <text x="26" y="152" font-family="'Bebas Neue',Impact,sans-serif" font-size="${c2Size}" fill="#9AFF00" letter-spacing="${c2Space}">${esc(c.c2)}</text>
    <text x="26" y="176" font-family="Montserrat,sans-serif" font-size="9" font-weight="600" fill="rgba(255,255,255,.5)" letter-spacing="3">АКАДЕМИЯ ХЛБ</text>`;
  return `<svg class="ac-cover-svg" viewBox="0 0 320 190" preserveAspectRatio="xMidYMid slice" aria-hidden="true">
    <rect width="320" height="190" fill="#070a04"/>
    <g stroke="rgba(154,255,0,.10)" stroke-width="1">
      ${[40,80,120,160,200,240,280].map(x=>`<line x1="${x}" y1="0" x2="${x}" y2="190"/>`).join('')}
      ${[38,76,114,152].map(y=>`<line x1="0" y1="${y}" x2="320" y2="${y}"/>`).join('')}
    </g>
    <circle cx="266" cy="44" r="70" fill="rgba(154,255,0,.09)"/>
    <use href="#i-logo" x="238" y="16" width="64" height="64"/>${bigText}
  </svg>`;
}

/* карточка курса в каталоге */
function acCourseCardHtml(ci){
  const c = AC_COURSES[ci];
  const acc = acCourseAccessible(ci);
  const pct = acCoursePctOf(ci);
  const done = acCourseDone(ci);
  const CR = 2*Math.PI*15;
  const badge = c.free
    ? `<span class="ac-cc-tag free">${I('bolt')} Бесплатно</span>`
    : acc
      ? `<span class="ac-cc-tag open">${I('check2')} Открыт</span>`
      : `<span class="ac-cc-tag lock">${I('lock')} ${c.minTier}</span>`;
  const ring = acc
    ? `<span class="ac-mini-ring lg" title="Курс пройден на ${pct}%">
        <svg viewBox="0 0 36 36"><circle class="bg" cx="18" cy="18" r="15"/>
        <circle class="val" cx="18" cy="18" r="15" stroke-dasharray="${CR.toFixed(1)}" stroke-dashoffset="${CR.toFixed(1)}" data-off="${(CR*(1-pct/100)).toFixed(1)}"/></svg>
        <b>${done?I('check2'):pct}</b></span>`
    : `<span class="ac-cc-price">${acFmtPrice(c.price)}</span>`;
  const cta = acc
    ? (done ? `Открыть курс` : (pct>0 ? `Продолжить · ${pct}%` : `Начать курс`))
    : `Открыть доступ`;
  return `
    <div class="card ac-cc ${acc?'':'locked'}" style="animation-delay:${(ci*0.06).toFixed(2)}s" onclick="acCourseCardClick(${ci})">
      <div class="ac-cc-cover">${acCourseCover(ci)}${acc?'':`<span class="ac-cc-veil">${I('lock')}</span>`}</div>
      <div class="ac-cc-body">
        <div class="ac-cc-top">${badge}<span class="ac-cc-meta">${c.count} ${acPlural(c.count,['урок','урока','уроков'])}</span></div>
        <h3>${esc(c.title)}</h3>
        <p>${esc(c.sub)}</p>
        <div class="ac-cc-foot">${ring}<button class="btn sm ${acc?'':'ghost'} ac-cc-go" onclick="event.stopPropagation();acCourseCardClick(${ci})">${cta}</button></div>
      </div>
    </div>`;
}
function acCourseCardClick(ci){ acOpenCourse(ci); }

/* ---------- ГЛАВНАЯ АКАДЕМИИ: КАТАЛОГ КУРСОВ ---------- */
/* большая карточка «Продолжи с этого» — берёт последний открытый урок из localStorage,
   иначе первый доступный. Показывает превью урока и его прогресс. */
function acContinueCardHtml(){
  const last = acResumeLesson();
  if(last < 0){
    return `<div class="ac-next-row done">${I('check2')}<span>Доступные уроки пройдены, открой премиум-курс</span></div>`;
  }
  const L = AC_COURSE[last];
  const ci = acCourseOf(last);
  const c = AC_COURSES[ci];
  const p = acLessonPct(last);
  const started = p > 0;
  const label = started ? 'Продолжи с этого' : 'Начни отсюда';
  const cta = started ? 'Продолжить урок' : 'Открыть урок';
  return `
    <div class="card ac-continue" onclick="acOpenLesson(${last})">
      <div class="ac-continue-head">
        <span class="ac-continue-tag">${I('circle-play')} ${label}</span>
        <span class="ac-continue-meta">${esc(c.title)} · урок ${acLocalNo(last)}/${c.count}</span>
      </div>
      <h3 class="ac-continue-title">${esc(L.title)}</h3>
      <p class="ac-continue-sub">${esc(acLessonSub(L))}</p>
      <div class="ac-continue-bar" title="Прогресс урока ${p}%"><i style="width:${p}%"></i></div>
      <div class="ac-continue-foot">
        <span class="ac-continue-pct">${p}% пройдено</span>
        <button class="btn sm ac-continue-cta" onclick="event.stopPropagation();acOpenLesson(${last})">${cta}</button>
      </div>
    </div>`;
}
function acHomeHtml(){
  const st = acStreak();
  const hot = st.days >= 3;
  const streak = `
    <div class="card ac-streak ${hot?'hot':''}">
      <span class="ac-flame">${I('fire')}</span>
      <div class="meta"><b>Дней подряд в учёбе: ${st.days||0}</b>
        <span>${hot ? 'Серия в огне — так держать!' : 'Заходи каждый день, чтобы разжечь серию'}${st.best>1?` · рекорд: ${st.best}`:''}</span></div>
      ${hot?`<span class="ac-hot-chip">${I('fire')} ${st.days}</span>`:''}
    </div>`;
  const nextRow = acContinueCardHtml();
  const courses = AC_COURSES.map((_,ci)=>acCourseCardHtml(ci)).join('');
  const certs = acS.certs.length ? acS.certs.map((c,i)=>`
    <div class="ac-cert-item" style="animation-delay:${i*.05}s">
      <span class="ico"><svg class="i"><use href="#i-file"/></svg></span>
      <span class="meta"><span class="t">${esc(acCertLabel(c))}</span><span class="s" style="display:block">${esc(c.no)} · ${esc(c.date)} · тест ${c.score}%</span></span>
      <button class="btn sm ghost ac-ico-btn" onclick="acCertShare(${i})" title="Поделиться" aria-label="Поделиться">${I('share')}</button>
      <button class="btn sm ghost" onclick="acCertShow(${i})">Показать</button>
    </div>`).join('')
    : `<p class="dim" style="font-size:12.5px;line-height:1.55">Пройди направление целиком — получи официальный сертификат ХЛБ с печатью и подписью. Он появится здесь.</p>`;
  return `
    <div class="ac-hero"><h2>Академия ХЛБ</h2><p>Курсы полного формата · официальные сертификаты</p></div>
    ${streak}
    ${nextRow}
    <h2 class="section-h" style="margin:20px 0 10px;font-size:21px">Каталог курсов</h2>
    <div class="ac-catalog">${courses}</div>

    <h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Достижения</h2>
    <div class="card ac-badges-card">${acBadgesGridHtml()}</div>

    <h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Мои сертификаты</h2>
    <div class="card" style="padding:6px 14px">${certs}</div>
    <div style="height:14px"></div>`;
}

/* подпись сертификата: «Курс · Урок N · Название» */
function acCertLabel(c){
  return 'Направление «' + (c.courseTitle || 'Академия ХЛБ') + '» · сертификат';
}

/* ---------- «ЧТО ВНУТРИ КУРСА»: состав + чему научишься ---------- */
function acCourseInsideHtml(ci){
  const c = AC_COURSES[ci], st = acCourseStats(ci);
  const feats = [
    ['file', st.lessons + ' ' + acPlural(st.lessons,['урок','урока','уроков']) + ' полного формата', 'анимированные слайды + конспект'],
    ['file',  st.slides + ' ' + acPlural(st.slides,['слайд','слайда','слайдов']), 'наглядно и по делу'],
    ['poll',  'Тесты · ' + st.quiz + ' ' + acPlural(st.quiz,['вопрос','вопроса','вопросов']), 'порог зачёта ' + AC_PASS + '%'],
    ['edit',  'Практика', 'проверка куратором'],
    ['bolt',  st.games + ' мини-' + acPlural(st.games,['игра','игры','игр']), 'закрепление на связках'],
    ['star',  'Сертификат', 'именной — за всё направление'],
  ];
  const outcomes = (c.outcomes||[]).map(o=>`<li>${I('check2')}<span>${esc(o)}</span></li>`).join('');
  return `
  <div class="card ac-inside" id="acWhatsIn">
    <div class="ac-inside-head">
      <span class="ico">${I('bolt')}</span>
      <div class="meta"><b>Что внутри курса</b><span>${c.author?('Автор — '+esc(c.author)+' · '):''}${st.lessons} ${acPlural(st.lessons,['урок','урока','уроков'])} полного формата</span></div>
    </div>
    <div class="ac-inside-grid">${feats.map(f=>`
      <div class="ac-inside-cell"><span class="ic">${I(f[0])}</span><b>${f[1]}</b><span>${f[2]}</span></div>`).join('')}</div>
    ${outcomes?`<div class="ac-inside-out"><div class="h">${I('flag')} Чему научишься</div><ul>${outcomes}</ul></div>`:''}
  </div>`;
}

/* ---------- СТРАНИЦА КУРСА (список уроков) ---------- */
function acCourseHtml(){
  const ci = acCourse, c = AC_COURSES[ci];
  const pct = acCoursePctOf(ci), C = 2*Math.PI*33, CR = 2*Math.PI*15;
  const idx = acCourseIdx(ci);
  const done = acCourseDone(ci);
  const doneCnt = idx.filter(i=>acLessonDone(i)).length;  // «34/45 уроков»
  /* строка урока (номер — сквозной внутри направления) */
  const lessonRow = (i,k)=>{
    const local = acLocalNo(i);
    if(!acUnlocked(i)) return `<button class="ac-lesson-row locked ac-rise" style="animation-delay:${(k*0.04).toFixed(2)}s" onclick="acCourseGate(${ci})">
      <span class="ac-num">${local}</span>
      <span class="meta"><span class="t">${esc(AC_COURSE[i].title)}</span><span class="s" style="display:block">${esc(acLessonSub(AC_COURSE[i]))}</span></span>
      <svg class="i"><use href="#i-lock"/></svg></button>`;
    const p = acLessonPct(i);
    const stg = (p > 0 ? `<span class="ac-mini-ring" title="Урок пройден на ${p}%">
          <svg viewBox="0 0 36 36"><circle class="bg" cx="18" cy="18" r="15"/>
          <circle class="val" cx="18" cy="18" r="15" stroke-dasharray="${CR.toFixed(1)}" stroke-dashoffset="${CR.toFixed(1)}" data-off="${(CR*(1-p/100)).toFixed(1)}"/></svg>
          <b>${p}</b></span>` : '');
    return `<button class="ac-lesson-row ac-rise" style="animation-delay:${(k*0.04).toFixed(2)}s" onclick="acOpenLesson(${i})">
      <span class="ac-num">${local}</span>
      <span class="meta"><span class="t">${esc(AC_COURSE[i].title)}</span><span class="s" style="display:block">${esc(acLessonSub(AC_COURSE[i]))}</span></span>
      ${stg}
      <svg class="i go"><use href="#i-chev"/></svg></button>`;
  };
  /* группировка по блокам направления */
  const blocks = acCourseBlocks(ci);
  let rk = 0;
  const rows = blocks.map((b, bi)=>{
    const bIdx = []; for(let i=b.from;i<b.from+b.count;i++) bIdx.push(i);
    const bDone = b.count>0 && bIdx.every(i=>acLessonDone(i));
    const bPct = b.count>0 ? Math.round(bIdx.reduce((s,i)=>s+acLessonPct(i),0)/b.count) : 0;
    const head = `<div class="ac-block-head${bDone?' done':''}">
        <span class="ac-block-n">Блок ${bi+1}</span>
        <span class="ac-block-t">${esc(b.title)}</span>
        <span class="ac-block-meta">${b.count>0 ? (b.count+' '+acPlural(b.count,['урок','урока','уроков'])+(bPct>0?' · '+bPct+'%':'')) : 'готовится'}</span>
        ${bDone?`<span class="ac-block-done">${I('check2')}</span>`:''}
      </div>`;
    const body = b.count>0
      ? bIdx.map(i=>lessonRow(i, rk++)).join('')
      : `<div class="ac-block-soon">${I('clock')}<span>Уроки блока в производстве — скоро откроются</span></div>`;
    return `<div class="ac-block">${head}${body}</div>`;
  }).join('');
  let nx = idx.find(i=>acUnlocked(i) && !acLessonDone(i));
  if(nx===undefined && !done) nx = idx[0];   // защита: если курс не пройден, всегда есть куда вести
  const nextRow = (nx!==undefined)
    ? `<button class="ac-next-row" onclick="acOpenLesson(${nx})">${I('circle-play')}<span>${acLessonPct(nx)>0?'Продолжить':'Начать'}: <b>урок ${acLocalNo(nx)} — ${esc(AC_COURSE[nx].title)}</b></span><svg class="i go"><use href="#i-chev"/></svg></button>`
    : `<div class="ac-next-row done">${I('check2')}<span>Направление пройдено — именной сертификат у тебя</span></div>`;
  const certN = acCourseCertCount(ci);
  const finale = done
    ? `<div class="card ac-course-finale"><span class="ico">${I('crown')}</span>
        <div><h3>Курс завершён</h3><p>Ты прошёл все ${c.count} ${acPlural(c.count,['урок','урока','уроков'])} и получил ${certN} ${acPlural(certN,['сертификат','сертификата','сертификатов'])}. Так держать!</p></div></div>`
    : '';
  return `
    <button class="btn ghost sm ac-back" onclick="acBackHome()"><svg class="i"><use href="#i-back"/></svg> Каталог</button>
    <div class="ac-course-hero">
      <div class="ac-course-hero-cover">${acCourseCover(ci, true)}</div>
      <div class="ac-course-hero-cap">
        <span class="chip">${c.free?'Базовый курс':'Премиум · открыт'}</span>
        <h2>${esc(c.title)}</h2>
        <p>${esc(c.sub)}</p>
      </div>
    </div>
    ${acCourseInsideHtml(ci)}
    <div class="card">
      <div class="ac-course-top">
        <span class="ac-ring">
          <svg viewBox="0 0 80 80"><circle class="bg" cx="40" cy="40" r="33"/>
          <circle class="val" cx="40" cy="40" r="33" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${C.toFixed(1)}" data-off="${(C*(1-pct/100)).toFixed(1)}"/></svg>
          <b>${pct}%</b>
        </span>
        <div>
          <h3>Прогресс курса</h3>
          <p class="dim"><b style="color:var(--accent)">${doneCnt}</b>/${c.count} ${acPlural(c.count,['урок','урока','уроков'])} · ${certN} ${acPlural(certN,['сертификат','сертификата','сертификатов'])}</p>
        </div>
      </div>
      <div class="ac-course-progress" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100" title="Прогресс курса ${pct}%">
        <i style="width:${pct}%"></i>
        <span class="ac-course-progress-lbl">${doneCnt}/${c.count} · ${pct}%</span>
      </div>
      ${nextRow}
      <div>${rows}</div>
    </div>
    ${finale}
    ${acRecCourseHtml(ci)}
    <div style="height:16px"></div>`;
}
/* плитка «Следующий рекомендуемый курс» под текущим курсом.
   Показываем только если у пользователя есть куда идти дальше внутри Академии. */
function acRecCourseHtml(ci){
  const rec = acRecommendNext(ci);
  if(rec < 0) return '';
  const c = AC_COURSES[rec];
  const acc = acCourseAccessible(rec);
  const pct = acCoursePctOf(rec);
  const started = pct > 0;
  const cta = acc ? (started ? 'Продолжить курс' : 'Начать курс') : 'Открыть доступ';
  const meta = acc
    ? (started ? ('Начат · пройдено ' + pct + '%') : (c.count + ' ' + acPlural(c.count,['урок','урока','уроков']) + ' · доступ открыт'))
    : (c.count + ' ' + acPlural(c.count,['урок','урока','уроков']) + ' · ' + acFmtPrice(c.price) + ' или подписка ' + c.minTier);
  return `
    <div class="card ac-rec" onclick="acCourseCardClick(${rec})">
      <div class="ac-rec-head">
        <span class="ac-rec-tag">${I('rocket')} Следующий шаг</span>
        <span class="ac-rec-meta">${esc(meta)}</span>
      </div>
      <div class="ac-rec-body">
        <div class="ac-rec-cover">${acCourseCover(rec, true)}${acc?'':`<span class="ac-cc-veil">${I('lock')}</span>`}</div>
        <div class="ac-rec-cap">
          <h3>${esc(c.title)}</h3>
          <p>${esc(c.sub)}</p>
          <button class="btn sm ac-rec-cta" onclick="event.stopPropagation();acCourseCardClick(${rec})">${cta}</button>
        </div>
      </div>
    </div>`;
}

/* ---------- СТРАНИЦА УРОКА ---------- */
function acOpenLesson(i){
  const k = (typeof i === 'number') ? i : 0;
  const ci = acCourseOf(k);
  if(!acCourseAccessible(ci)){ acCourseGate(ci); return; }
  if(!acUnlocked(k)){ toast('Урок '+acLocalNo(k)+' откроется после предыдущего'); return; }
  acL = k; acCourse = ci;
  acS.lastLesson = k; acSave();   // «Продолжи с этого» помнит последний открытый урок
  if(typeof acSpeedStop==='function') acSpeedStop();
  acView = 'lesson'; acQuiz = null; acG = null; acTaskChecking = false;
  acRender();
  const m = document.querySelector('main'); if(m) m.scrollTop = 0;
}
/* назад: из урока → на страницу курса, со страницы курса → в каталог */
function acBackHome(){
  if(typeof acSpeedStop==='function') acSpeedStop();
  if(acView === 'lesson'){ acView = 'course'; acCourse = acCourseOf(acL); }
  else acView = 'home';
  acRender();
  const m = document.querySelector('main'); if(m) m.scrollTop = 0;
}

function acLessonHtml(){
  const L = acCur();
  const ci = acCourseOf(acL);
  const vid = acHasVideo(L);
  return `
    <button class="btn ghost sm ac-back" onclick="acBackHome()"><svg class="i"><use href="#i-back"/></svg> ${esc(AC_COURSES[ci].title)}</button>
    <div class="ac-lesson-head">
      <span class="chip">Урок ${acLocalNo(acL)} из ${AC_COURSES[ci].count}</span>
      <h2>${L.title}</h2>
      <div class="m">${vid?`<span>${I('clock')} ${L.dur} видео</span><span>·</span>`:''}<span>${I('file')} ${L.slides.length} слайдов</span><span>·</span><span>тест из ${L.quiz.length} вопросов</span><span>·</span><span>мини-игра</span></div>
      ${acEnrichIntroHtml()}
    </div>

    ${vid ? '<div id="acVideoBox"></div>' : ''}

    <h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Слайды урока</h2>
    <div id="acSlidesBox">
      <div class="ac-slides" id="acSlides">${L.slides.map((s,i)=>`
        <div class="ac-slide ${i===0?'cur':''}" data-i="${i}">
          <span class="n">Слайд ${i+1} / ${L.slides.length}</span>
          <h3>${s.t}</h3>
          <div class="pic">${s.svg}</div>
          <ul>${s.pts.map(p=>`<li>${p}</li>`).join('')}</ul>
        </div>`).join('')}
      </div>
      <div class="ac-slides-nav">
        <button class="ac-arrow" onclick="acSlideGo(-1)"><svg class="i"><use href="#i-back"/></svg></button>
        <span class="ac-dots" id="acDots">${L.slides.map((_,i)=>`<i class="${i===0?'on':''}"></i>`).join('')}</span>
        <button class="ac-arrow next" onclick="acSlideGo(1)"><svg class="i"><use href="#i-back"/></svg></button>
      </div>
    </div>

    ${acEnrichDeepHtml()}

    <h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Конспект</h2>
    ${acNotesHtml()}

    ${acEnrichLinksHtml()}
    ${acToolsHtml(L)}

    <h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Тест по материалу</h2>
    <div class="card" id="acTestBox"></div>

    <h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Практика</h2>
    <div class="card" id="acTaskBox"></div>

    <h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Мини-игра</h2>
    <div class="card" id="acGameBox"></div>

    <h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Прогресс урока</h2>
    <div class="card" style="padding:8px 16px 14px" id="acProgressBox"></div>

    <div style="height:14px"></div>
    <div id="acCertBox"></div>
    <div style="height:16px"></div>`;
}

/* ================= ОБОГАЩЕНИЕ УРОКА (intro / глубокий разбор / лайфхак / ссылки) ================= */
function acEnrich(){ try{ return (window.AC_ENRICH||{})[acL] || null; }catch(e){ return null; } }
function acEnrichIntroHtml(){
  const e = acEnrich();
  if(!e || !e.intro) return '';
  return `<p class="ac-intro-hook">${esc(e.intro)}</p>`;
}
function acEnrichDeepHtml(){
  const e = acEnrich();
  if(!e) return '';
  let out = '';
  if(Array.isArray(e.notes) && e.notes.length){
    out += `<h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Глубокий разбор</h2>
      <div class="ac-deep">${e.notes.map((n,i)=>`
        <div class="ac-deep-sec" style="--d:${(i*0.06).toFixed(2)}s">
          <span class="n">${String(i+1).padStart(2,'0')}</span>
          <div class="bd"><h4>${esc(n.h||'')}</h4><p>${esc(n.body||'')}</p></div>
        </div>`).join('')}</div>`;
  }
  if(e.lifehack){
    out += `<div class="ac-lifehack">
      <div class="ic">${I('bolt')}</div>
      <div><span class="lbl">Лайфхак</span><p>${esc(e.lifehack)}</p></div>
    </div>`;
  }
  return out;
}
function acEnrichLinksHtml(){
  const e = acEnrich();
  if(!e || !Array.isArray(e.links) || !e.links.length) return '';
  const items = e.links.map(l=>{
    const url = String(l.url||'').trim();
    const safe = /^https?:\/\//i.test(url) ? url : ('https://' + url.replace(/^\/+/,''));
    let host = ''; try{ host = new URL(safe).hostname.replace(/^www\./,''); }catch(_){ host = safe; }
    return `<a class="ac-link-btn" href="${esc(safe)}" target="_blank" rel="noopener noreferrer">
      <span class="ic">${I('compass')}</span>
      <span class="tx"><b>${esc(l.label||host)}</b><span>${esc(l.note||host)}</span></span>
      <span class="host">${esc(host)}</span>
      <svg class="i go"><use href="#i-forward"/></svg></a>`;
  }).join('');
  return `<h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Инструменты урока</h2>
    <div class="ac-links">${items}</div>`;
}

/* ---------- а) ВИДЕО ---------- */
/* Бренд-обложка урока (SVG) — общий макет постера и заглушки «скоро» */
function acVpCover(L){
  return `
      <svg class="ac-cover" viewBox="0 0 640 360" preserveAspectRatio="xMidYMid slice">
        <defs>
          <linearGradient id="acPosterScrim" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#04060a" stop-opacity="0"/>
            <stop offset=".5" stop-color="#04060a" stop-opacity="0"/>
            <stop offset="1" stop-color="#000" stop-opacity=".84"/>
          </linearGradient>
        </defs>
        <rect width="640" height="360" fill="#070a04"/>
        <g stroke="rgba(154,255,0,.09)" stroke-width="1">
          ${[80,160,240,320,400,480,560].map(x=>`<line x1="${x}" y1="0" x2="${x}" y2="360"/>`).join('')}
          ${[72,144,216,288].map(y=>`<line x1="0" y1="${y}" x2="640" y2="${y}"/>`).join('')}
        </g>
        <circle cx="530" cy="80" r="120" fill="rgba(154,255,0,.07)"/>
        <use href="#i-logo" x="472" y="34" width="120" height="120"/>
        <!-- нижний скрим: держит центр постера чистым под кнопку play, а заголовок внизу — читаемым в обеих темах -->
        <rect x="0" y="150" width="640" height="210" fill="url(#acPosterScrim)"/>
        <!-- заголовок вынесен в НИЖНЮЮ треть постера: не пересекается с центральной кнопкой play (она в чистом поле выше) -->
        <text x="48" y="272" font-family="'Bebas Neue',Impact,sans-serif" font-weight="700" font-size="40" fill="#fff" letter-spacing="1" textLength="${(L.c1||'').length>8?520:''}" lengthAdjust="spacingAndGlyphs">${L.c1}</text>
        <text x="48" y="320" font-family="'Bebas Neue',Impact,sans-serif" font-weight="700" font-size="52" fill="#9AFF00" letter-spacing="${(L.c2||'').length>8?2:4}" textLength="${(L.c2||'').length>9?540:''}" lengthAdjust="spacingAndGlyphs">${L.c2}</text>
        <text x="48" y="346" font-family="Montserrat,sans-serif" font-size="14" font-weight="600" fill="rgba(255,255,255,.6)" letter-spacing="3">АКАДЕМИЯ ХЛБ · УРОК ${acLocalNo(acL)}</text>
      </svg>`;
}
function acRenderVideoBox(){
  const box = document.getElementById('acVideoBox');
  if(!box) return;
  const L = acCur(), ls = acLS();
  // Заглушка «видео в производстве» (у урока пока нет ролика)
  const cover = `
    <div class="ac-player" onclick="acPlay()" id="acPlayer">
      ${acVpCover(L)}
      <div class="ac-play-btn"><svg class="i"><use href="#i-play"/></svg></div>
      <span class="dur">${L.dur || 'скоро'}</span>
    </div>`;
  // Кастомный бренд-плеер (без нативного <video controls>) — свой чёрно-лаймовый хром
  const player = L.videoUrl ? `
    <div class="ac-player ac-vp" id="acPlayer">
      <video class="ac-vp-video" id="acVpVideo" playsinline webkit-playsinline preload="metadata" controlsList="nodownload noremoteplayback noplaybackrate" disablePictureInPicture disableRemotePlayback oncontextmenu="return false" src="${L.videoUrl}" onclick="acVpTapArea(event)"></video>
      <div class="ac-vp-poster" id="acVpPoster" onclick="acVpBig(event)">
        ${acVpCover(L)}
        <button class="ac-vp-big" type="button" onclick="acVpBig(event)" aria-label="Смотреть урок">${I('play')}</button>
        <span class="dur">${L.dur || 'видео'}</span>
      </div>
      <button class="ac-vp-center" id="acVpCenter" type="button" onclick="acVpToggle(event)" aria-label="Пауза/пуск">${I('pause')}</button>
      <div class="ac-vp-bar" id="acVpBar" onclick="acVpBarStop(event)">
        <button class="ac-vp-btn" id="acVpPlay" type="button" onclick="acVpToggle(event)" aria-label="Пауза/пуск">${I('play')}</button>
        <div class="ac-vp-scrub" id="acVpScrub" onclick="acVpSeek(event)" role="slider" aria-label="Перемотка"><span class="trk"><i class="ac-vp-fill" id="acVpFill"></i></span></div>
        <span class="ac-vp-time" id="acVpTime">0:00 / ${L.dur || '0:00'}</span>
        <button class="ac-vp-btn" id="acVpMute" type="button" onclick="acVpMute(event)" aria-label="Звук">${I('megaphone')}</button>
        <button class="ac-vp-btn" type="button" onclick="acVpFull(event)" aria-label="На весь экран">${I('device')}</button>
      </div>
    </div>` : cover;
  box.innerHTML = player + `
    <div class="ac-video-actions">${ls.video
      ? `<span class="ac-done-chip">${I('check2')} Видео просмотрено</span>`
      : `<button class="btn" onclick="acMarkVideo()">${I('check2')} Отметить просмотренным</button>`}
    </div>`;
  if(L.videoUrl) acVpInit();
}
function acPlay(){
  if(acCur().videoUrl) return;
  showPopup({ico:'circle-play', title:'Видео урока в производстве',
    body:'Ролик урока «'+acCur().title+'» сейчас монтируется: озвучка, анимации и караоке-субтитры по стандарту Академии. Совсем скоро он появится прямо здесь. Пока изучи слайды ниже — в них весь материал урока.',
    actions:[{label:'Понятно'}]});
}

/* ---------- бренд-плеер: кастомный хром (без нативных controls) ---------- */
let acVpTimer = null;                       // таймер авто-скрытия панели
function acVpEl(){ return document.getElementById('acPlayer'); }
function acVpVid(){ return document.getElementById('acVpVideo'); }
function acVpFmt(s){                          // секунды -> m:ss
  if(!isFinite(s) || s < 0) s = 0;
  const m = Math.floor(s/60), z = Math.floor(s%60);
  return m + ':' + (z<10?'0':'') + z;
}
/* Привязка событий к видео после рендера. Всё в try/catch — оффлайн-источник не должен ломать хром */
function acVpInit(){
  try{
    const v = acVpVid(), p = acVpEl();
    if(!v || !p) return;
    v.addEventListener('loadedmetadata', acVpSync);
    v.addEventListener('durationchange', acVpSync);
    v.addEventListener('timeupdate', acVpSync);           // дёшево (~4/сек), без перерасчёта layout
    v.addEventListener('play',  ()=>{ p.classList.add('started','playing'); acVpSyncIcons(); acVpShow(false); });
    v.addEventListener('pause', ()=>{ p.classList.remove('playing'); acVpSyncIcons(); acVpShow(true); });
    v.addEventListener('ended', ()=>{ p.classList.remove('playing','started'); acVpSyncIcons(); acVpShow(true); });
    v.addEventListener('error', ()=>{ p.classList.remove('started','playing'); }); // источник не доступен — постер остаётся
    acVpSyncIcons();
  }catch(_){}
}
/* Показать панель управления; при проигрывании прячем сама через пару секунд */
function acVpShow(sticky){
  const p = acVpEl(); if(!p) return;
  p.classList.add('controls-on');
  clearTimeout(acVpTimer);
  if(!sticky && p.classList.contains('playing')){
    acVpTimer = setTimeout(()=>{ const q=acVpEl(); if(q) q.classList.remove('controls-on'); }, 2500);
  }
}
function acVpHide(){ const p=acVpEl(); if(p) p.classList.remove('controls-on'); clearTimeout(acVpTimer); }
/* Тап по области видео во время проигрывания — показать/скрыть управление */
function acVpTapArea(e){
  if(e) e.stopPropagation();
  const p = acVpEl(); if(!p || !p.classList.contains('started')) return;
  if(p.classList.contains('controls-on')) acVpHide(); else acVpShow(false);
}
function acVpBarStop(e){ if(e) e.stopPropagation(); acVpShow(false); } // клики по панели не сворачивают её
/* Большая лаймовая кнопка на постере — старт */
function acVpBig(e){
  if(e) e.stopPropagation();
  const v = acVpVid(); if(!v) return;
  try{ const pr = v.play(); if(pr && pr.catch) pr.catch(()=>{}); }catch(_){} // оффлайн: play отклонится — постер остаётся
}
/* Пуск/пауза (центр + нижняя панель) */
function acVpToggle(e){
  if(e) e.stopPropagation();
  const v = acVpVid(); if(!v) return;
  try{
    if(v.paused){ const pr = v.play(); if(pr && pr.catch) pr.catch(()=>{}); }
    else v.pause();
  }catch(_){}
  acVpShow(false);
}
/* Перемотка по клику на слим-скраббер */
function acVpSeek(e){
  if(e) e.stopPropagation();
  const v = acVpVid(), s = document.getElementById('acVpScrub');
  if(!v || !s) return;
  try{
    const r = s.getBoundingClientRect();
    const x = (e.clientX != null) ? e.clientX : (e.touches && e.touches[0] ? e.touches[0].clientX : r.left);
    let p = (x - r.left) / r.width; p = Math.max(0, Math.min(1, p));
    if(isFinite(v.duration) && v.duration > 0){ v.currentTime = p * v.duration; acVpSync(); }
  }catch(_){}
  acVpShow(false);
}
/* Тумблер звука */
function acVpMute(e){
  if(e) e.stopPropagation();
  const v = acVpVid(), b = document.getElementById('acVpMute');
  if(!v) return;
  try{ v.muted = !v.muted; if(b) b.classList.toggle('off', v.muted); }catch(_){}
  acVpShow(false);
}
/* На весь экран (fullscreen контейнера, iOS — самого видео) */
function acVpFull(e){
  if(e) e.stopPropagation();
  const p = acVpEl(), v = acVpVid();
  try{
    if(document.fullscreenElement){ if(document.exitFullscreen) document.exitFullscreen(); return; }
    if(p && p.requestFullscreen) p.requestFullscreen();
    else if(p && p.webkitRequestFullscreen) p.webkitRequestFullscreen();
    else if(v && v.webkitEnterFullscreen) v.webkitEnterFullscreen();
  }catch(_){}
  acVpShow(false);
}
/* Обновление скраббера и таймкода (transform:scaleX — без layout-thrash) */
function acVpSync(){
  const v = acVpVid(); if(!v) return;
  const fill = document.getElementById('acVpFill'), t = document.getElementById('acVpTime');
  const dur = (isFinite(v.duration) && v.duration > 0) ? v.duration : 0;
  const p = dur ? Math.max(0, Math.min(1, v.currentTime / dur)) : 0;
  if(fill) fill.style.transform = 'scaleX(' + p.toFixed(4) + ')';
  if(t){ let d; try{ d = acCur().dur; }catch(_){ d = ''; } t.textContent = acVpFmt(v.currentTime) + ' / ' + (dur ? acVpFmt(dur) : (d || '0:00')); }
}
/* Синхронизация иконок play/pause по состоянию видео */
function acVpSyncIcons(){
  const v = acVpVid(); if(!v) return;
  const ico = v.paused ? I('play') : I('pause');
  const b = document.getElementById('acVpPlay'), c = document.getElementById('acVpCenter');
  if(b) b.innerHTML = ico;
  if(c) c.innerHTML = ico;
}
function acMarkVideo(){
  acLS().video = true; acSave();
  toast('Видео засчитано · +20% к уроку');
  acRenderVideoBox(); acRenderProgressBox(); acRenderCertBox(); acAfterCheckpoint();
}

/* ---------- б) СЛАЙДЫ ---------- */
let acSlideIdx = 0;
function acBindSlides(){
  const el = document.getElementById('acSlides');
  if(!el) return;
  acSlideIdx = 0;
  let raf = null;
  el.addEventListener('scroll', ()=>{
    if(raf) return;
    raf = requestAnimationFrame(()=>{
      raf = null;
      const kids = el.children;
      if(!kids.length) return;
      const step = kids[0].offsetWidth + 12;
      const i = Math.max(0, Math.min(acCur().slides.length-1, Math.round(el.scrollLeft / step)));
      if(i !== acSlideIdx){ acSlideIdx = i; acSlideSync(); }
    });
  }, {passive:true});
}
function acSlideSync(){
  const dots = document.querySelectorAll('#acDots i');
  dots.forEach((d,i)=>d.classList.toggle('on', i===acSlideIdx));
  document.querySelectorAll('#acSlides .ac-slide').forEach((s,i)=>s.classList.toggle('cur', i===acSlideIdx));
  const ls = acLS();
  if(acSlideIdx > ls.slideMax){ ls.slideMax = acSlideIdx; acSave(); }
  if(ls.slideMax >= acCur().slides.length-1 && !ls.slides){
    ls.slides = true; acSave();
    toast('Слайды пройдены · +20% к уроку');
    acRenderProgressBox(); acRenderCertBox(); acAfterCheckpoint();
  }
}
function acSlideGo(d){
  const el = document.getElementById('acSlides');
  if(!el || !el.children.length) return;
  const step = el.children[0].offsetWidth + 12;
  const i = Math.max(0, Math.min(acCur().slides.length-1, acSlideIdx + d));
  el.scrollTo({left: i*step, behavior:'smooth'});
  acSlideIdx = i; acSlideSync();
}

/* ---------- в) ТЕСТ ---------- */
function acRenderTestBox(){
  const box = document.getElementById('acTestBox');
  if(!box) return;
  const quiz = acCur().quiz, ls = acLS();
  if(!acQuiz){
    box.innerHTML = ls.test
      ? `<div class="ac-score" style="font-size:52px">${ls.testScore}%</div>
         <div class="ac-score-sub">Тест сдан. Лучший результат — <b>${ls.testScore}%</b> при пороге ${AC_PASS}%.</div>
         <button class="btn ghost" onclick="acQuizStart()">Пройти заново</button>`
      : `<p style="font-size:13.5px;line-height:1.55">${quiz.length} вопросов по материалу урока. По одному на экран, порог зачёта — <b style="color:var(--accent)">${AC_PASS}%</b>.${ls.testScore?` Прошлая попытка: ${ls.testScore}%.`:''}</p>
         <div style="height:12px"></div>
         <button class="btn" onclick="acQuizStart()">${I('bolt')} ${ls.testScore?'Попробовать ещё раз':'Начать тест'}</button>`;
    return;
  }
  if(acQuiz.done){
    const score = acQuiz.score, pass = score >= AC_PASS;
    const misses = acQuiz.misses || [];
    const review = misses.length
      ? `<div class="ac-review">
          <div class="ac-review-h">${I('poll')} Разбор ошибок · ${misses.length} ${acPlural(misses.length,['вопрос','вопроса','вопросов'])}</div>
          ${misses.map(m=>{ const qq=quiz[m.q]; return `
            <div class="ac-review-item">
              <div class="rq"><span class="rn">${m.q+1}</span><span>${qq.q}</span></div>
              <div class="ra bad"><span class="lb">${'АБВГ'[m.chosen]}</span><span>${qq.o[m.chosen]}</span></div>
              <div class="ra ok"><span class="lb">${'АБВГ'[qq.a]}</span><span>${qq.o[qq.a]}</span></div>
            </div>`; }).join('')}
        </div>`
      : `<div class="ac-review perfect">${I('star')} Идеально — ни одной ошибки${acQuiz.best>=3?` · лучшая серия ×${acQuiz.best}`:''}</div>`;
    box.innerHTML = `
      <div class="ac-score" id="acScoreNum" ${pass?'':'style="color:var(--danger);text-shadow:none"'}>0%</div>
      <div class="ac-score-sub">${pass
        ? `Порог ${AC_PASS}% пройден — <b>тест зачтён</b>. Верных ответов: ${acQuiz.hits} из ${quiz.length}.`
        : `<span class="fail">Не хватило до порога ${AC_PASS}%.</span> Верных: ${acQuiz.hits} из ${quiz.length}. Пролистай слайды и попробуй снова.`}</div>
      <button class="btn ${pass?'ghost':''}" onclick="acQuizStart()">Пройти заново</button>
      ${review}`;
    const el = document.getElementById('acScoreNum');
    acCountUp(el, score, '%');
    return;
  }
  const q = quiz[acQuiz.i];
  box.innerHTML = `
    <div class="ac-quiz-top"><span>Вопрос <b>${acQuiz.i+1}</b> из ${quiz.length}</span><span>${acQuiz.combo>=2?`<span class="ac-combo-live">${I('fire')} ×${acQuiz.combo}</span> · `:''}верных: <b>${acQuiz.hits}</b></span></div>
    <div class="progress" style="margin:0 0 4px"><i style="width:${(acQuiz.i/quiz.length*100)}%"></i></div>
    <div class="ac-q">${q.q}</div>
    ${q.o.map((o,i)=>`<button class="ac-opt" id="acOpt${i}" onclick="acAnswer(${i})"><span class="lb">${'АБВГ'[i]}</span><span>${o}</span></button>`).join('')}`;
}
function acQuizStart(){
  acQuiz = {i:0, hits:0, lock:false, done:false, score:0, misses:[], combo:0, best:0};
  acRenderTestBox();
}
/* всплывающий индикатор серии верных ответов (гейм-фидбек, не мешает потоку теста) */
function acComboPop(n){
  try{
    const box = document.getElementById('acTestBox'); if(!box) return;
    const el = document.createElement('div'); el.className = 'ac-combo-pop';
    el.innerHTML = I('fire') + '<span>серия ×' + n + '</span>';
    box.appendChild(el);
    requestAnimationFrame(()=>el.classList.add('go'));
    setTimeout(()=>{ try{ el.remove(); }catch(e){} }, 900);
  }catch(e){}
}
function acAnswer(i){
  if(!acQuiz || acQuiz.lock || acQuiz.done) return;
  acQuiz.lock = true;
  const quiz = acCur().quiz;
  const q = quiz[acQuiz.i];
  const right = i === q.a;
  if(right){ acQuiz.hits++; acQuiz.combo++; if(acQuiz.combo > acQuiz.best) acQuiz.best = acQuiz.combo; }
  else { acQuiz.combo = 0; acQuiz.misses.push({q:acQuiz.i, chosen:i}); }
  const ok = document.getElementById('acOpt'+q.a);
  if(ok) ok.classList.add('ok');
  if(!right){ const bad = document.getElementById('acOpt'+i); if(bad) bad.classList.add('bad'); }
  if(right && acQuiz.combo >= 3) acComboPop(acQuiz.combo);
  setTimeout(()=>{
    acQuiz.lock = false;
    acQuiz.i++;
    if(acQuiz.i >= quiz.length){
      acQuiz.done = true;
      acQuiz.score = Math.round(acQuiz.hits / quiz.length * 100);
      const ls = acLS();
      if(acQuiz.score > ls.testScore) ls.testScore = acQuiz.score;
      if(acQuiz.score >= AC_PASS && !ls.test){
        ls.test = true;
        toast('Тест сдан · +20% к уроку');
      }
      acSave();
      acRenderProgressBox(); acRenderCertBox(); acBadgeSync(); acAfterCheckpoint();
    }
    acRenderTestBox();
  }, right ? 700 : 1100);
}
function acCountUp(el, to, suffix){
  if(!el) return;
  const t0 = performance.now(), dur = 950;
  (function step(t){
    const k = Math.min(1, (t-t0)/dur), e = 1 - Math.pow(1-k, 3);
    el.textContent = Math.round(to*e) + (suffix||'');
    if(k < 1) requestAnimationFrame(step);
  })(t0);
}

/* ---------- г) ПРАКТИКА ---------- */
function acRenderTaskBox(){
  const box = document.getElementById('acTaskBox');
  if(!box) return;
  const T = acCur().task, ls = acLS();
  if(acTaskChecking){
    box.innerHTML = `<div class="ac-checking"><span class="ac-spin"></span>
      <div><p>Проверяется куратором<small>Сверяю ответ с материалом урока…</small></p></div></div>`;
    return;
  }
  if(ls.task){
    box.innerHTML = `
      <div class="ac-verdict">
        <div class="h">${I('check2')} Зачтено</div>
        <p>${T.verdict}</p>
      </div>
      <div style="height:10px"></div>
      <p class="dim" style="font-size:12px;line-height:1.5">Твой ответ: «${esc(ls.taskText.slice(0,140))}${ls.taskText.length>140?'…':''}»</p>`;
    return;
  }
  box.innerHTML = `
    <p style="font-size:13.5px;line-height:1.55">${T.intro}</p>
    <div class="ac-task-formula">${T.chips.map((c,i)=>(i? I('chev'):'')+`<span>${c}</span>`).join('')}</div>
    <textarea class="ac-task-ta" id="acTaskTa" placeholder="${esc(T.ph)}">${esc(ls.taskText)}</textarea>
    <div style="height:10px"></div>
    <button class="btn" onclick="acTaskSend()">${I('send')} Отправить на проверку</button>`;
}
function acTaskSend(){
  const ta = document.getElementById('acTaskTa');
  const v = (ta && ta.value || '').trim();
  if(v.length < 40){ toast('Раскрой подробнее — минимум 40 символов'); return; }
  const ls = acLS();
  ls.taskText = v; acSave();
  acTaskChecking = true;
  acRenderTaskBox();
  setTimeout(()=>{
    acTaskChecking = false;
    ls.task = true; acSave();
    toast('Практика зачтена · +20% к уроку');
    acRenderTaskBox(); acRenderProgressBox(); acRenderCertBox(); acBadgeSync(); acAfterCheckpoint();
  }, 4000);
}

/* ---------- д) МИНИ-ИГРА ---------- */
function acShuffle(a){ a=a.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; } return a; }
/* Тип мини-игры на урок (анти-повтор: чередуется по индексу урока).
   Движки берут данные из уже готового контента урока (pairs / slides). */
/* Реестр движков (9). Порядок = порядок анти-повтора по индексу урока.
   Каждый движок берёт данные из уже готового контента урока. */
const AC_GAMES = ['pairs','order','truefalse','memory','flash','quizspeed','gap','bucket','oddquiz'];
/* Достаточно ли данных урока для движка t. */
function acGamePlayable(t, L){
  const nS = (L.slides||[]).length, nQ = (L.quiz||[]).length, nP = (L.pairs||[]).length;
  switch(t){
    case 'pairs':    return nP >= 3;
    case 'memory':   return nP >= 3 && nP <= 8;      // сетка карточек
    case 'flash':    return nP >= 3;
    case 'order':    return nS >= 3;
    case 'gap':      return nS >= 3;
    case 'truefalse':return nQ >= 3;
    case 'quizspeed':return nQ >= 3;
    case 'bucket':   return nQ >= 3;
    case 'oddquiz':  return nQ >= 3 && (L.quiz||[]).every(q=>(q.o||[]).length>=3);
    default:         return false;
  }
}
/* Тип мини-игры урока: анти-повтор по индексу + фолбэк по доступности данных. */
function acGameType(){
  const L = acCur();
  const start = acL % AC_GAMES.length;
  for(let k=0;k<AC_GAMES.length;k++){
    const t = AC_GAMES[(start + k) % AC_GAMES.length];
    if(acGamePlayable(t, L)) return t;
  }
  // предельный фолбэк
  if((L.pairs||[]).length) return 'pairs';
  if((L.slides||[]).length>=3) return 'order';
  return 'truefalse';
}
/* Заголовки-подписи под каждый движок (интро + «пройдено»). */
const AC_GAME_META = {
  pairs:    {done:'Все пары собраны',              intro:'<b>Сопоставь пары.</b> Тапни элемент слева, затем его пару справа. Верная пара улетает, неверная — трясётся.'},
  order:    {done:'Порядок шагов восстановлен',    intro:'<b>Расставь шаги по порядку.</b> Тапай карточки в правильной последовательности урока — верный шаг встаёт на место, неверный трясётся.'},
  truefalse:{done:'Все утверждения разобраны',     intro:'<b>Правда или ложь.</b> Для каждого утверждения реши, верный это ответ или нет. Ошибся — покажем, как на самом деле.'},
  memory:   {done:'Все карточки открыты',          intro:'<b>Мемори.</b> Открывай по две карточки и находи пары «понятие ↔ значение». Запоминай, где что лежит.'},
  flash:    {done:'Карточки повторены',            intro:'<b>Флеш-карточки.</b> Смотри понятие, вспомни значение и переверни карточку. Отметь честно: знал или нет.'},
  quizspeed:{done:'Блиц пройден',                  intro:'<b>Блиц на скорость.</b> На каждый вопрос — несколько секунд. Отвечай быстро и верно, пока идёт таймер.'},
  gap:      {done:'Пропуски заполнены',            intro:'<b>Заполни пропуск.</b> В тезисе урока пропущено ключевое слово — выбери верное из вариантов.'},
  bucket:   {done:'Всё разложено по полкам',       intro:'<b>Правда / Ложь по полкам.</b> Разложи все утверждения в две колонки, затем проверь себя разом.'},
  oddquiz:  {done:'Лишнее убрано',                 intro:'<b>Убери неверное.</b> В каждом вопросе вычёркивай неверные варианты — пока не останется единственный правильный.'}
};
function acGameFinish(wrong){
  const ls = acLS(); ls.gameWrong = wrong;
  if(!ls.game){ ls.game = true; toast('Мини-игра пройдена · +20% к уроку'); }
  acG = null; acSave();
  acRenderGameBox(); acRenderProgressBox(); acRenderCertBox(); acBadgeSync(); acAfterCheckpoint();
}
function acRenderGameBox(){
  const box = document.getElementById('acGameBox');
  if(!box) return;
  const t = acGameType(), ls = acLS();
  const meta = AC_GAME_META[t] || AC_GAME_META.pairs;
  if(!acG){
    if(ls.game){
      box.innerHTML = `<div class="ac-game-done"><div class="big">${I('check2')}</div>
         <p>${meta.done}${ls.gameWrong!==null&&ls.gameWrong!==undefined?` · ошибок: ${ls.gameWrong}`:''}. Материал урока — в связке.</p>
         <button class="btn ghost" onclick="acGameStart()">Сыграть ещё раз</button></div>`;
    } else {
      box.innerHTML = `<p style="font-size:13.5px;line-height:1.55">${meta.intro}</p><div style="height:12px"></div>
         <button class="btn" onclick="acGameStart()">${I('play')} Играть</button>`;
    }
    return;
  }
  switch(acG.type){
    case 'order':     return acRenderOrder(box);
    case 'truefalse': return acRenderTF(box);
    case 'memory':    return acRenderMemory(box);
    case 'flash':     return acRenderFlash(box);
    case 'quizspeed': return acRenderSpeed(box);
    case 'gap':       return acRenderGap(box);
    case 'bucket':    return acRenderBucket(box);
    case 'oddquiz':   return acRenderOdd(box);
    default:          return acRenderPairs(box);
  }
}
function acRenderPairs(box){
  const pairs = acCur().pairs;
  const left = acG.left.map(i=>`<button class="ac-tile ${acG.sel===i?'sel':''}" id="acGL${i}" onclick="acGPick(${i})">${pairs[i][0]}</button>`).join('');
  const right = acG.right.map(i=>`<button class="ac-tile" id="acGR${i}" onclick="acGMatch(${i})">${pairs[i][1]}</button>`).join('');
  box.innerHTML = `
    <div class="ac-game-score"><span>Собрано пар: <b>${acG.hits} / ${pairs.length}</b></span><span>ошибок: <b>${acG.wrong}</b></span></div>
    <div class="ac-game-cols">
      <div class="ac-game-col"><div class="h">Понятие</div>${left}</div>
      <div class="ac-game-col"><div class="h">Пара</div>${right}</div>
    </div>`;
}
function acRenderOrder(box){
  const S = acCur().slides;
  let placed = '';
  for(let k=0;k<acG.next;k++) placed += `<div class="ac-ord-step done"><span class="n">${k+1}</span><span>${esc(S[k].t)}</span></div>`;
  if(acG.next < S.length) placed += `<div class="ac-ord-step now"><span class="n">${acG.next+1}</span><span class="dim">Выбери следующий шаг…</span></div>`;
  const pool = acG.pool.filter(i=>i>=acG.next)
    .map(i=>`<button class="ac-ord-tile" id="acOrd${i}" onclick="acOrderPick(${i})">${esc(S[i].t)}</button>`).join('');
  box.innerHTML = `
    <div class="ac-game-score"><span>Шаг: <b>${acG.next} / ${S.length}</b></span><span>ошибок: <b>${acG.wrong}</b></span></div>
    <div class="ac-ord-seq">${placed}</div>
    <div class="ac-ord-pool">${pool}</div>`;
}
function acOrderPick(i){
  if(!acG || acG.lock) return;
  const S = acCur().slides;
  if(i === acG.next){
    acG.next++;
    if(acG.next >= S.length){ acGameFinish(acG.wrong); return; }
    acRenderOrder(document.getElementById('acGameBox'));
  } else {
    acG.wrong++;
    const el = document.getElementById('acOrd'+i);
    if(el){ el.classList.add('shake'); acG.lock = true; setTimeout(()=>{ el.classList.remove('shake'); acG.lock=false; acRenderOrder(document.getElementById('acGameBox')); }, 420); }
    else acRenderOrder(document.getElementById('acGameBox'));
  }
}
function acStripTags(s){ return String(s).replace(/<[^>]+>/g,'').replace(/\s+/g,' ').trim(); }
function acGameStart(){
  acSpeedStop();                                // на всякий случай гасим прошлый таймер блица
  const L = acCur(), t = acGameType();
  if(t === 'order'){
    const idx = L.slides.map((_,i)=>i);
    acG = {type:'order', pool:acShuffle(idx), next:0, wrong:0, lock:false};
  } else if(t === 'truefalse'){
    const items = L.quiz.map(it=>{
      const showTrue = Math.random() < 0.5;
      if(showTrue) return {text:it.q, opt:it.o[it.a], isTrue:true};
      const wrongs = it.o.map((o,k)=>k).filter(k=>k!==it.a);
      const wk = wrongs[Math.floor(Math.random()*wrongs.length)];
      return {text:it.q, opt:it.o[wk], isTrue:false};
    });
    const order = acShuffle(items.map((_,i)=>i));
    acG = {type:'truefalse', items:order.map(i=>items[i]), cur:0, wrong:0, lock:false};
  } else if(t === 'memory'){
    // карточки: по 2 на пару (понятие + значение), общий id пары
    const cards = [];
    L.pairs.forEach((p,pid)=>{ cards.push({pid,txt:acStripTags(p[0])}); cards.push({pid,txt:acStripTags(p[1])}); });
    acG = {type:'memory', cards:acShuffle(cards), open:[], matched:{}, hits:0, wrong:0, lock:false};
  } else if(t === 'flash'){
    const order = acShuffle(L.pairs.map((_,i)=>i));
    acG = {type:'flash', order, cur:0, flip:false, wrong:0};
  } else if(t === 'quizspeed'){
    const order = acShuffle(L.quiz.map((_,i)=>i));
    acG = {type:'quizspeed', order:order.map(i=>L.quiz[i]), cur:0, wrong:0, lock:false, tl:0, per:12};
  } else if(t === 'gap'){
    acG = {type:'gap', items:acBuildGap(L), cur:0, wrong:0, lock:false};
  } else if(t === 'bucket'){
    const items = L.quiz.map(it=>{
      const showTrue = Math.random() < 0.5;
      const opt = showTrue ? it.o[it.a] : it.o[it.o.map((_,k)=>k).filter(k=>k!==it.a)[Math.floor(Math.random()*(it.o.length-1))]];
      return {text:acStripTags(it.q), opt:acStripTags(opt), isTrue:showTrue, placed:null};
    });
    acG = {type:'bucket', items:acShuffle(items), wrong:0, done:false};
  } else if(t === 'oddquiz'){
    const order = acShuffle(L.quiz.map((_,i)=>i));
    acG = {type:'oddquiz', q:order.map(i=>L.quiz[i]), cur:0, wrong:0, lock:false, dead:{}};
  } else {
    const idx = L.pairs.map((_,i)=>i);
    acG = {type:'pairs', left:idx.slice(), right:acShuffle(idx), sel:null, hits:0, wrong:0, lock:false};
  }
  acRenderGameBox();
  if(acG.type === 'quizspeed') acSpeedTick(true);
}
/* Построение заданий «заполни пропуск» из тезисов слайдов + дистракторов из теста. */
function acBuildGap(L){
  const STOP = new Set(['этого','который','которые','которых','чтобы','более','менее','также','когда','только','нужно','можно','будет','через','между','каждый','любой','очень','просто','сразу','потом','затем','около']);
  const distractPool = [];
  (L.quiz||[]).forEach(q=>(q.o||[]).forEach(o=>{ const w=acStripTags(o).split(/\s+/).filter(x=>x.length>4&&/^[А-Яа-яA-Za-z]+$/.test(x)); distractPool.push(...w); }));
  const items = [];
  (L.slides||[]).forEach(s=>{
    (s.pts||[]).forEach(pt=>{
      const clean = acStripTags(pt);
      const words = clean.split(/\s+/);
      const cand = words.map((w,idx)=>({w:w.replace(/[.,:;!?«»()"]/g,''),idx})).filter(o=>o.w.length>5 && /^[А-Яа-яA-Za-z-]+$/.test(o.w) && !STOP.has(o.w.toLowerCase()));
      if(!cand.length || words.length < 6) return;
      const pick = cand[Math.floor(Math.random()*cand.length)];
      const answer = pick.w;
      const distr = acShuffle(distractPool.filter(d=>d.toLowerCase()!==answer.toLowerCase()));
      const opts = [answer];
      for(const d of distr){ if(opts.length>=4) break; if(!opts.some(o=>o.toLowerCase()===d.toLowerCase())) opts.push(d); }
      // подстрахуемся: если дистракторов мало — берём слова из этого же тезиса
      for(const o of cand){ if(opts.length>=3) break; if(o.w.toLowerCase()!==answer.toLowerCase() && !opts.some(x=>x.toLowerCase()===o.w.toLowerCase())) opts.push(o.w); }
      if(opts.length < 3) return;
      const shown = words.map((w,idx)=> idx===pick.idx ? '<span class="gap-blank">•••</span>' : w).join(' ');
      items.push({html:shown, answer, opts:acShuffle(opts)});
    });
  });
  return acShuffle(items).slice(0, 6);   // до 6 пропусков
}
function acRenderTF(box){
  const it = acG.items[acG.cur];
  if(!it){ acGameFinish(acG.wrong); return; }
  box.innerHTML = `
    <div class="ac-game-score"><span>Утверждение: <b>${acG.cur+1} / ${acG.items.length}</b></span><span>ошибок: <b>${acG.wrong}</b></span></div>
    <div class="ac-tf-card" id="acTFCard">
      <div class="q">${esc(it.text)}</div>
      <div class="opt">${esc(it.opt)}</div>
      <div class="ask">Это верный ответ?</div>
    </div>
    <div class="ac-tf-btns">
      <button class="ac-tf-btn no" onclick="acTFAnswer(false)">Ложь</button>
      <button class="ac-tf-btn yes" onclick="acTFAnswer(true)">Правда</button>
    </div>`;
}
function acTFAnswer(ans){
  if(!acG || acG.lock) return;
  const it = acG.items[acG.cur];
  const nextCard = ()=>{ acG.cur++; if(acG.cur>=acG.items.length){ acGameFinish(acG.wrong); return; } acRenderTF(document.getElementById('acGameBox')); };
  if(ans === it.isTrue){ nextCard(); }
  else {
    acG.wrong++; acG.lock = true;
    const c = document.getElementById('acTFCard'); if(c) c.classList.add('shake');
    toast(it.isTrue ? 'На самом деле это верный ответ' : 'На самом деле ответ неверный');
    setTimeout(()=>{ acG.lock = false; nextCard(); }, 780);
  }
}
function acGPick(i){
  if(!acG || acG.lock) return;
  acG.sel = acG.sel === i ? null : i;
  acG.left.forEach(k=>{
    const el = document.getElementById('acGL'+k);
    if(el) el.classList.toggle('sel', acG.sel===k);
  });
}
function acGMatch(i){
  if(!acG || acG.lock) return;
  if(acG.sel === null){ toast('Сначала выбери элемент слева'); return; }
  const L = document.getElementById('acGL'+acG.sel), R = document.getElementById('acGR'+i);
  if(acG.sel === i){
    acG.lock = true;
    if(L) L.classList.add('hit');
    if(R) R.classList.add('hit');
    setTimeout(()=>{
      acG.left = acG.left.filter(k=>k!==i);
      acG.right = acG.right.filter(k=>k!==i);
      acG.hits++; acG.sel = null; acG.lock = false;
      if(!acG.left.length){
        const wrong = acG.wrong;
        acG = null;
        const ls = acLS();
        ls.gameWrong = wrong;
        if(!ls.game){ ls.game = true; toast('Мини-игра пройдена · +20% к уроку'); }
        acSave();
        acRenderGameBox(); acRenderProgressBox(); acRenderCertBox(); acBadgeSync(); acAfterCheckpoint();
      } else acRenderGameBox();
    }, 560);
  } else {
    acG.wrong++;
    if(L) L.classList.add('shake');
    if(R) R.classList.add('shake');
    acG.lock = true;
    setTimeout(()=>{
      acG.lock = false; acG.sel = null;
      acRenderGameBox();
    }, 460);
  }
}

/* ---------- МЕМОРИ: открывай пары карточек ---------- */
function acRenderMemory(box){
  const cards = acG.cards.map((c,i)=>{
    const open = acG.open.includes(i), done = acG.matched[i];
    const cls = done ? 'done' : open ? 'open' : '';
    return `<button class="ac-mem-card ${cls}" id="acMem${i}" onclick="acMemFlip(${i})">
      <span class="face back"><svg class="i"><use href="#i-logo"/></svg></span>
      <span class="face front">${esc(c.txt)}</span></button>`;
  }).join('');
  box.innerHTML = `
    <div class="ac-game-score"><span>Пары: <b>${acG.hits} / ${acG.cards.length/2}</b></span><span>ошибок: <b>${acG.wrong}</b></span></div>
    <div class="ac-mem-grid">${cards}</div>`;
}
function acMemFlip(i){
  if(!acG || acG.lock || acG.matched[i] || acG.open.includes(i)) return;
  acG.open.push(i);
  acRenderMemory(document.getElementById('acGameBox'));
  if(acG.open.length < 2) return;
  const [a,b] = acG.open;
  acG.lock = true;
  if(acG.cards[a].pid === acG.cards[b].pid && a !== b){
    setTimeout(()=>{
      acG.matched[a] = acG.matched[b] = true; acG.open = []; acG.hits++; acG.lock = false;
      if(acG.hits >= acG.cards.length/2){ acGameFinish(acG.wrong); return; }
      acRenderMemory(document.getElementById('acGameBox'));
    }, 460);
  } else {
    acG.wrong++;
    const ea=document.getElementById('acMem'+a), eb=document.getElementById('acMem'+b);
    if(ea) ea.classList.add('miss'); if(eb) eb.classList.add('miss');
    setTimeout(()=>{ acG.open = []; acG.lock = false; acRenderMemory(document.getElementById('acGameBox')); }, 720);
  }
}
/* ---------- ФЛЕШ-КАРТОЧКИ: понятие → значение, самооценка ---------- */
function acRenderFlash(box){
  const p = acCur().pairs[acG.order[acG.cur]];
  box.innerHTML = `
    <div class="ac-game-score"><span>Карточка: <b>${acG.cur+1} / ${acG.order.length}</b></span><span>не вспомнил: <b>${acG.wrong}</b></span></div>
    <div class="ac-flash ${acG.flip?'flip':''}" id="acFlash" onclick="acFlashFlip()">
      <div class="ac-flash-in">
        <div class="ac-flash-face front"><span class="tag">Понятие</span><div class="t">${esc(acStripTags(p[0]))}</div><span class="hint">Вспомни значение и переверни</span></div>
        <div class="ac-flash-face back"><span class="tag">Значение</span><div class="t">${esc(acStripTags(p[1]))}</div></div>
      </div>
    </div>
    ${acG.flip ? `<div class="ac-flash-btns">
      <button class="ac-tf-btn no" onclick="acFlashMark(false)">Не вспомнил</button>
      <button class="ac-tf-btn yes" onclick="acFlashMark(true)">Знал</button>
    </div>` : `<div style="height:6px"></div><p class="dim" style="text-align:center;font-size:12px">Тапни карточку, чтобы перевернуть</p>`}`;
}
function acFlashFlip(){ if(!acG) return; acG.flip = !acG.flip; acRenderFlash(document.getElementById('acGameBox')); }
function acFlashMark(known){
  if(!acG) return;
  if(!known) acG.wrong++;
  acG.cur++; acG.flip = false;
  if(acG.cur >= acG.order.length){ acGameFinish(acG.wrong); return; }
  acRenderFlash(document.getElementById('acGameBox'));
}
/* ---------- БЛИЦ: тест на скорость с таймером ---------- */
let acSpeedTimer = null;
function acSpeedStop(){ if(acSpeedTimer){ clearInterval(acSpeedTimer); acSpeedTimer = null; } }
function acSpeedTick(reset){
  if(!acG || acG.type!=='quizspeed') { acSpeedStop(); return; }
  if(reset){ acG.tl = acG.per; }
  acSpeedStop();
  acSpeedTimer = setInterval(()=>{
    if(!acG || acG.type!=='quizspeed'){ acSpeedStop(); return; }
    acG.tl -= 0.1;
    const fill = document.getElementById('acSpeedFill');
    if(fill) fill.style.width = Math.max(0, acG.tl/acG.per*100) + '%';
    const tm = document.getElementById('acSpeedTime');
    if(tm) tm.textContent = Math.max(0, Math.ceil(acG.tl)) + 'с';
    if(acG.tl <= 0){ acSpeedStop(); acSpeedAnswer(-1); }
  }, 100);
}
function acRenderSpeed(box){
  const it = acG.order[acG.cur];
  if(!it){ acGameFinish(acG.wrong); return; }
  const opts = it.o.map((o,k)=>`<button class="ac-speed-opt" id="acSp${k}" onclick="acSpeedAnswer(${k})">${esc(acStripTags(o))}</button>`).join('');
  box.innerHTML = `
    <div class="ac-game-score"><span>Вопрос: <b>${acG.cur+1} / ${acG.order.length}</b></span><span>ошибок: <b>${acG.wrong}</b> · <b id="acSpeedTime">${acG.per}с</b></span></div>
    <div class="ac-speed-bar"><i id="acSpeedFill" style="width:${Math.max(0,acG.tl/acG.per*100)}%"></i></div>
    <div class="ac-speed-q">${esc(acStripTags(it.q))}</div>
    <div class="ac-speed-opts">${opts}</div>`;
}
function acSpeedAnswer(k){
  if(!acG || acG.lock) return;
  acSpeedStop(); acG.lock = true;
  const it = acG.order[acG.cur], correct = it.a;
  const ce = document.getElementById('acSp'+correct); if(ce) ce.classList.add('ok');
  if(k !== correct){ acG.wrong++; const we = document.getElementById('acSp'+k); if(we) we.classList.add('bad'); }
  setTimeout(()=>{
    acG.cur++; acG.lock = false;
    if(acG.cur >= acG.order.length){ acGameFinish(acG.wrong); return; }
    acG.tl = acG.per; acRenderSpeed(document.getElementById('acGameBox')); acSpeedTick(true);
  }, k===correct ? 420 : 900);
}
/* ---------- ЗАПОЛНИ ПРОПУСК ---------- */
function acRenderGap(box){
  const it = acG.items[acG.cur];
  if(!it){ acGameFinish(acG.wrong); return; }
  const opts = it.opts.map((o,k)=>`<button class="ac-gap-opt" id="acGap${k}" onclick="acGapPick(${k})">${esc(o)}</button>`).join('');
  box.innerHTML = `
    <div class="ac-game-score"><span>Пропуск: <b>${acG.cur+1} / ${acG.items.length}</b></span><span>ошибок: <b>${acG.wrong}</b></span></div>
    <div class="ac-gap-sent">${it.html}</div>
    <div class="ac-gap-opts">${opts}</div>`;
}
function acGapPick(k){
  if(!acG || acG.lock) return;
  const it = acG.items[acG.cur], chosen = it.opts[k];
  acG.lock = true;
  const el = document.getElementById('acGap'+k);
  if(chosen.toLowerCase() === it.answer.toLowerCase()){
    if(el) el.classList.add('ok');
    const blank = document.querySelector('#acGameBox .gap-blank'); if(blank){ blank.textContent = it.answer; blank.classList.add('filled'); }
    setTimeout(()=>{ acG.cur++; acG.lock=false; if(acG.cur>=acG.items.length){ acGameFinish(acG.wrong); return; } acRenderGap(document.getElementById('acGameBox')); }, 620);
  } else {
    acG.wrong++;
    if(el) el.classList.add('bad');
    setTimeout(()=>{ if(el) el.classList.remove('bad'); acG.lock=false; }, 480);
  }
}
/* ---------- ПРАВДА/ЛОЖЬ ПО ПОЛКАМ ---------- */
function acRenderBucket(box){
  const chips = acG.items.map((it,i)=> it.placed===null
    ? `<button class="ac-bkt-chip" id="acBkt${i}" onclick="acBucketPick(${i})">${esc(it.text)}: <b>${esc(it.opt)}</b></button>` : '').join('');
  const col = (val)=> acG.items.map((it,i)=> it.placed===val
    ? `<button class="ac-bkt-item ${acG.done?(it.isTrue===(val==='t')?'ok':'bad'):''}" onclick="${acG.done?'':`acBucketUnplace(${i})`}">${esc(it.text)}: <b>${esc(it.opt)}</b></button>` : '').join('');
  const remaining = acG.items.some(it=>it.placed===null);
  box.innerHTML = `
    <div class="ac-game-score"><span>Разложи все утверждения</span><span>ошибок: <b>${acG.wrong}</b></span></div>
    <div class="ac-bkt-pool">${chips || '<span class="dim" style="font-size:12px">Все разложены — проверь себя</span>'}</div>
    <div class="ac-bkt-cols">
      <div class="ac-bkt-col t"><div class="h">${I('check2')} Правда</div>${col('t')||'<span class="ph">выбери сюда</span>'}</div>
      <div class="ac-bkt-col f"><div class="h">${I('flag')} Ложь</div>${col('f')||'<span class="ph">выбери сюда</span>'}</div>
    </div>
    ${!acG.done ? `<div style="height:10px"></div><button class="btn" ${remaining?'disabled style="opacity:.5"':''} onclick="acBucketCheck()">Проверить</button>` : `<div style="height:8px"></div><button class="btn ghost" onclick="acGameStart()">Сыграть ещё раз</button>`}`;
}
let acBktSel = null;
function acBucketPick(i){
  // тап-модель: тап по чипу выбирает, затем тап по колонке кладёт
  acBktSel = i;
  const chip = document.getElementById('acBkt'+i);
  document.querySelectorAll('#acGameBox .ac-bkt-chip').forEach(c=>c.classList.remove('sel'));
  if(chip){ chip.classList.add('sel');
    // показать подсказку выбора колонок прямо через быстрые кнопки
  }
  // авто-раскладка через две кнопки-колонки: навесим обработчик на клик по колонкам
  const cols = document.querySelectorAll('#acGameBox .ac-bkt-col');
  cols.forEach(c=>{ c.onclick = ()=>{ if(acBktSel===null) return; acG.items[acBktSel].placed = c.classList.contains('t')?'t':'f'; acBktSel=null; acRenderBucket(document.getElementById('acGameBox')); }; });
}
function acBucketUnplace(i){ if(acG.done) return; acG.items[i].placed = null; acRenderBucket(document.getElementById('acGameBox')); }
function acBucketCheck(){
  if(acG.items.some(it=>it.placed===null)) return;
  acG.wrong = acG.items.filter(it=> (it.placed==='t') !== it.isTrue).length;
  acG.done = true;
  acRenderBucket(document.getElementById('acGameBox'));
  try{ window.okoTrack && okoTrack('lesson_complete', {group:(typeof acG!=='undefined'&&acG.k)||'', wrong:(typeof acG!=='undefined'?acG.wrong:null)}); }catch(e){}
  const ls = acLS(); ls.gameWrong = acG.wrong;
  if(!ls.game){ ls.game = true; toast('Мини-игра пройдена · +20% к уроку'); }
  acSave(); acRenderProgressBox(); acRenderCertBox(); acBadgeSync(); acAfterCheckpoint();
}
/* ---------- УБЕРИ НЕВЕРНОЕ ---------- */
function acRenderOdd(box){
  const it = acG.q[acG.cur];
  if(!it){ acGameFinish(acG.wrong); return; }
  const dead = acG.dead[acG.cur] || {};
  const alive = it.o.map((_,k)=>k).filter(k=>!dead[k]);
  const opts = it.o.map((o,k)=>{
    if(dead[k]) return `<button class="ac-odd-opt dead" disabled>${esc(acStripTags(o))}</button>`;
    const last = alive.length===1;
    return `<button class="ac-odd-opt ${last&&k===it.a?'ok':''}" onclick="acOddPick(${k})">${esc(acStripTags(o))}</button>`;
  }).join('');
  box.innerHTML = `
    <div class="ac-game-score"><span>Вопрос: <b>${acG.cur+1} / ${acG.q.length}</b></span><span>ошибок: <b>${acG.wrong}</b></span></div>
    <div class="ac-odd-q">${esc(acStripTags(it.q))}</div>
    <p class="dim" style="font-size:12px;margin:2px 0 8px">Вычёркивай неверные варианты</p>
    <div class="ac-odd-opts">${opts}</div>`;
}
function acOddPick(k){
  if(!acG || acG.lock) return;
  const it = acG.q[acG.cur];
  if(!acG.dead[acG.cur]) acG.dead[acG.cur] = {};
  if(k === it.a){
    // попытались убрать правильный — ошибка, трясём
    acG.wrong++; acG.lock = true;
    const el = document.querySelectorAll('#acGameBox .ac-odd-opt')[k]; if(el) el.classList.add('shake');
    toast('Это верный ответ — его убирать нельзя');
    setTimeout(()=>{ if(el) el.classList.remove('shake'); acG.lock=false; }, 480);
    return;
  }
  acG.dead[acG.cur][k] = true;
  const alive = it.o.map((_,i)=>i).filter(i=>!acG.dead[acG.cur][i]);
  if(alive.length === 1){
    // остался правильный — следующий вопрос
    acG.lock = true;
    acRenderOdd(document.getElementById('acGameBox'));
    setTimeout(()=>{ acG.cur++; acG.lock=false; if(acG.cur>=acG.q.length){ acGameFinish(acG.wrong); return; } acRenderOdd(document.getElementById('acGameBox')); }, 640);
  } else {
    acRenderOdd(document.getElementById('acGameBox'));
  }
}

/* ---------- прогресс: чек-лист 5 пунктов ---------- */
function acRenderProgressBox(){
  const box = document.getElementById('acProgressBox');
  if(!box) return;
  const pct = acLessonPct(acL);
  const ci = acCourseOf(acL);
  const lastInCourse = (acL === acCourseFirst(ci) + AC_COURSES[ci].count - 1);
  const next = (!lastInCourse && acLessonDone(acL))
    ? `<p class="dim" style="font-size:12px;text-align:center;margin-top:4px">Урок ${acLocalNo(acL)+1} «${esc(AC_COURSE[acL+1].title)}» открыт</p>` : '';
  box.innerHTML = acItems(acL).map(([label,done])=>`
    <div class="ac-check-row ${done?'done':''}">
      <span class="ac-check-ic"><svg class="i"><use href="#i-check2"/></svg></span>
      <span>${label}</span><span class="pct">${done?'+20%':'—'}</span>
    </div>`).join('') + `
    <div class="progress" style="margin:12px 0 6px"><i style="width:${pct}%"></i></div>
    <p class="dim" style="font-size:12px;text-align:center">Урок пройден на <b style="color:var(--accent)">${pct}%</b></p>` + next;
}

/* ================= КОНСПЕКТ УРОКА (лонгрид из слайдов) ================= */
function acNotesStrip(h){ return String(h).replace(/<[^>]+>/g,''); }
function acNotesWords(){
  return acCur().slides.reduce((n,s)=>n + acNotesStrip(s.t + ' ' + s.pts.join(' ')).split(/\s+/).length, 0);
}
function acNotesHtml(){
  const L = acCur();
  const mins = Math.max(2, Math.round(acNotesWords() / 150));
  const secs = L.slides.map((s,i)=>{
    const p = s.pts.map(t=>t.trim().replace(/[.!…]+\s*$/,'')).join('. ') + '.';
    return `<div class="ac-note-sec"><span class="n">${String(i+1).padStart(2,'0')}</span><h4>${s.t}</h4><p>${p}</p></div>`;
  }).join('');
  return `
  <div class="card ac-notes" id="acNotes">
    <button class="ac-notes-head" onclick="acNotesToggle()">
      <span class="ico">${I('file')}</span>
      <span class="meta"><b>Текстовая версия урока</b><span>${L.slides.length} разделов · ~${mins} мин чтения · весь материал без видео</span></span>
      <svg class="i chev"><use href="#i-chev"/></svg>
    </button>
    <div class="ac-notes-body">
      <p class="ac-notes-intro">Полный конспект урока «${L.title}» — все тезисы слайдов, собранные в один читабельный текст. Удобно повторить перед тестом или сохранить себе.</p>
      ${secs}
      <div style="height:14px"></div>
      <button class="btn ghost" style="width:100%" onclick="acNotesDownload()">${I('file')} Скачать .txt</button>
    </div>
  </div>`;
}
function acNotesToggle(){
  const el = document.getElementById('acNotes');
  if(el) el.classList.toggle('open');
}
function acNotesTxt(){
  const L = acCur();
  let out = 'АКАДЕМИЯ ХЛБ · КУРС «НЕЙРОСЕТИ 2026»\r\n'
          + 'КОНСПЕКТ · УРОК ' + (acL+1) + ' — ' + L.title.toUpperCase() + '\r\n'
          + '='.repeat(46) + '\r\n\r\n';
  L.slides.forEach((s,i)=>{
    out += (i+1) + '. ' + acNotesStrip(s.t).toUpperCase() + '\r\n';
    s.pts.forEach(p=>{ out += '   — ' + acNotesStrip(p) + '\r\n'; });
    out += '\r\n';
  });
  out += '-'.repeat(46) + '\r\nПройди тест и получи официальный сертификат ХЛБ:\r\nhttps://true-journey-418.higgsfield.app\r\n';
  return out;
}
function acNotesDownload(){
  try{
    const blob = new Blob(['\ufeff' + acNotesTxt()], {type:'text/plain;charset=utf-8'});
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'ХЛБ-урок-' + (acL+1) + '-конспект.txt';
    document.body.appendChild(a); a.click();
    setTimeout(()=>{ try{ URL.revokeObjectURL(a.href); }catch(e){} a.remove(); }, 800);
    toast('Конспект сохранён: урок ' + (acL+1) + '.txt');
  }catch(e){
    acCopyText(acNotesTxt(), 'Скачивание недоступно — конспект скопирован в буфер');
  }
}

/* ================= НАПОМИНАНИЕ (раз в сутки при входе) =================
   Показываем только при входе в приложение/Академию, раз в сутки, и НИКОГДА
   поверх активного действия: открытый sheet, игра, мини-апп, попап или
   полноэкранная вьюха → откладываем и пробуем позже. */
function acRemindBusy(){
  if(document.getElementById('okoPopup')) return true;         // уже показан попап
  if(document.querySelector('.sheet.open')) return true;       // открыт bottom-sheet
  /* открыта полноэкранная вьюха (звонок / регистрация / канал / профиль и т.п.) */
  if(document.querySelector('#callScreen.open, #regView.open, .ma-view.open')) return true;
  /* открыт мини-апп внутри хаба «Мини-аппы» (сетка спрятана — значит внутри вьюхи) */
  const mg = document.getElementById('maGrid');
  if(mg && mg.style.display === 'none') return true;
  /* пользователь в разделе Игры / Мини-аппы — не мешаем активному занятию */
  const act = document.querySelector('.screen.active');
  if(act && /^screen-(games|mini)$/.test(act.id)) return true;
  return false;
}
function acRemindCheck(){
  try{
    if(!localStorage.getItem('oko-auth')) return;            // ещё не в приложении
    /* контекст-осознанность: не чаще одного раза за сессию — постоянный флаг */
    try{ if(sessionStorage.getItem('oko-ac-nudge-shown')) return; }catch(e){}
    const scr = document.getElementById('screen-academy');
    if(scr && scr.classList.contains('active')) return;      // уже в академии — напоминать незачем
    /* показываем ТОЛЬКО на Ленте (или в Академии) — НИКОГДА поверх Кошелька / TON /
       Чатов / Рекламы / Игр / Настроек, чтобы не прерывать денежные и чат-задачи.
       Если пользователь на другом экране — тихо ждём перехода на Ленту, ничего не показывая. */
    const act = document.querySelector('.screen.active');
    if(!act || !/^screen-(feed|academy)$/.test(act.id)){ setTimeout(acRemindCheck, 15000); return; }
    const today = acDayStr();
    if(acS.remindDay === today) return;                      // раз в сутки
    const nx = acNextLesson();
    if(nx < 0) return;                                       // всё пройдено — не беспокоим
    if(acRemindBusy()){ setTimeout(acRemindCheck, 20000); return; }  // занят — отложить
    const pct = acLessonPct(nx), title = esc(AC_COURSE[nx].title), lno = acLocalNo(nx);
    let body, label;
    if(pct <= 0){
      body = 'Начни урок ' + lno + ' «' + title + '» — тебя ждёт разбор темы, слайды, тест и практика.';
      label = 'Начать урок';
    } else {
      body = 'Продолжи урок ' + lno + ' «' + title + '» — пройдено '
           + '<b style="color:var(--accent)">' + pct + '%</b>, осталось ' + (100 - pct) + '%.';
      label = 'Продолжить урок';
    }
    acS.remindDay = today; acSave();
    try{ sessionStorage.setItem('oko-ac-nudge-shown','1'); }catch(e){}  // максимум один раз за сессию
    showPopup({ico:'star', title:'Академия ХЛБ', body:body,
      actions:[
        {label:label, onclick:()=>{ showTab('academy'); acOpenLesson(nx); }},
        {label:'Позже', ghost:true}
      ]});
  }catch(e){}
}

/* ================= ПОДЕЛИТЬСЯ СЕРТИФИКАТОМ ================= */
function acCopyText(t, okMsg){
  const done = ()=>toast(okMsg || 'Скопировано в буфер');
  const fallback = ()=>{
    try{
      const ta = document.createElement('textarea');
      ta.value = t; ta.style.cssText = 'position:fixed;top:-200px;opacity:0';
      document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); ta.remove(); done();
    }catch(e){ toast('Не удалось скопировать'); }
  };
  if(navigator.clipboard && navigator.clipboard.writeText)
    navigator.clipboard.writeText(t).then(done).catch(fallback);
  else fallback();
}
function acCertShare(i){
  const c = (typeof i === 'number') ? acS.certs[i] : acCertRec();
  if(!c){ toast('Сертификат ещё не выдан'); return; }
  const text = 'Официальный сертификат Академии ХЛБ ' + c.no
    + ' — ' + acCertLabel(c)
    + ' пройден, тест ' + c.score + '%. Учись со мной в ХЛБ: https://true-journey-418.higgsfield.app';
  if(navigator.share){
    navigator.share({title:'Сертификат Академии ХЛБ', text:text}).catch(()=>{});
  } else {
    acCopyText(text, 'Текст сертификата скопирован — вставь в любой чат');
  }
}

/* ================= СЕРТИФИКАТ ================= */
function acRenderCertBox(){
  const box = document.getElementById('acCertBox');
  if(!box) return;
  const ci = acCourseOf(acL);
  const dir = AC_COURSES[ci];
  const cert = acDirCert(ci);
  const idx = acCourseIdx(ci);
  const doneCnt = idx.filter(i=>acLessonDone(i)).length;
  const left = dir.count - doneCnt;
  if(cert){
    box.innerHTML = `
      <div class="card ac-cert-card ready">
        <div class="ac-cert-head">
          <span class="ico"><svg class="i"><use href="#i-star"/></svg></span>
          <div><h3>Сертификат направления получен</h3><p>Официальный диплом «${esc(dir.title)}» с печатью и подписью Академии ХЛБ</p></div>
        </div>
        <span class="ac-cert-no">${esc(cert.no)} · ${esc(cert.date)} · тест ${cert.score}%</span>
        <div class="ac-cert-actions">
          <button class="btn" onclick="acCertDownload()">${I('file')} Скачать PNG</button>
          <button class="btn ghost" onclick="acCertShow()">${I('eye')} Показать</button>
          <button class="btn ghost ac-ico-btn" onclick="acCertShare()" title="Поделиться" aria-label="Поделиться">${I('share')}</button>
        </div>
      </div>`;
    return;
  }
  if(acCertEligible()){
    box.innerHTML = `
      <div class="card ac-cert-card ready">
        <div class="ac-cert-head">
          <span class="ico"><svg class="i"><use href="#i-star"/></svg></span>
          <div><h3>Сертификат направления готов</h3><p>Все ${dir.count} уроков «${esc(dir.title)}» пройдены — забирай именной диплом</p></div>
        </div>
        <button class="btn" onclick="acIssueCert()">${I('star')} Получить сертификат</button>
      </div>`;
    return;
  }
  box.innerHTML = `
    <div class="card ac-cert-card">
      <div class="ac-cert-head">
        <span class="ico" style="background:var(--raised);color:var(--dim)"><svg class="i"><use href="#i-lock"/></svg></span>
        <div><h3>Сертификат за направление «${esc(dir.title)}»</h3><p>Именной документ с печатью и подписью — за прохождение ВСЕГО направления</p></div>
      </div>
      <div class="ac-cert-req">
        <div class="${doneCnt>0?'ok':''}">${I(doneCnt>0?'check2':'circle-play')} Пройдено уроков: ${doneCnt} из ${dir.count}</div>
        <div>${I('poll')} Осталось ${left} ${acPlural(left,['урок','урока','уроков'])} — уроки можно проходить в любом порядке</div>
      </div>
    </div>`;
}

function acIssueCert(){
  const ci = acCourseOf(acL);
  if(acDirCert(ci) || !acCourseDone(ci)) return;          // диплом один на направление, и только когда всё пройдено
  const idx = acCourseIdx(ci);
  const avg = Math.round(idx.reduce((sum,i)=>sum + ((acS.lessons[i]&&acS.lessons[i].testScore)||0), 0) / idx.length);
  const cert = {
    no: 'ХЛБ-CERT-' + String(Math.floor(1e5 + Math.random()*9e5)),
    date: new Date().toLocaleDateString('ru-RU'),
    score: avg,
    name: (typeof PROFILE!=='undefined' && PROFILE.name) ? PROFILE.name : 'Слушатель Академии',
    dir: AC_COURSES[ci].id,
    courseTitle: AC_COURSES[ci].title
  };
  acS.certs.unshift(cert);
  acSave();
  acCertUrl = null;
  toast('Сертификат направления «' + AC_COURSES[ci].title + '» выдан: ' + cert.no);
  acBadgeSync();
  acRenderCertBox(); acRenderProgressBox();
  acCertCelebrate(()=>acCertShow());
}

/* эффект выдачи сертификата: вспышка лаймовых лучей + печать, затем показ */
function acCertCelebrate(cb){
  try{
    const old = document.getElementById('acBurst'); if(old) old.remove();
    const el = document.createElement('div');
    el.id = 'acBurst'; el.className = 'ac-burst';
    let rays = '';
    for(let i=0;i<14;i++) rays += `<i style="--a:${(i*360/14)}deg;--d:${(i%3)*0.04}s"></i>`;
    let conf = '';
    for(let i=0;i<22;i++){
      const x = (Math.random()*100).toFixed(1), dl = (Math.random()*0.35).toFixed(2),
            rot = (Math.random()*360).toFixed(0), sx = (Math.random()*0.7+0.6).toFixed(2);
      conf += `<b style="left:${x}%;--dl:${dl}s;--rot:${rot}deg;--sx:${sx}"></b>`;
    }
    el.innerHTML = `<div class="ac-burst-core">
        <span class="ac-burst-rays">${rays}</span>
        <span class="ac-burst-seal">${I('star')}</span>
      </div>
      <div class="ac-burst-txt">Сертификат выдан</div>
      <div class="ac-burst-conf">${conf}</div>`;
    document.body.appendChild(el);
    requestAnimationFrame(()=>el.classList.add('go'));
    setTimeout(()=>{ try{ el.remove(); }catch(e){} if(typeof cb==='function') cb(); }, 1250);
  }catch(e){ if(typeof cb==='function') cb(); }
}

/* ================= ВАУ-МОМЕНТ: УРОК ОСВОЁН (все 5 этапов на 100%) =================
   Отдельный праздничный оверлей — срабатывает ровно один раз, когда закрыт ПОСЛЕДНИЙ
   из пяти чек-пойнтов урока. Не путать с выдачей сертификата (там свой burst-эффект). */
function acAfterCheckpoint(){
  try{
    const ls = acLS();
    if(acLessonPct(acL) === 100 && !ls.mastered){
      ls.mastered = true; acSave();
      acLessonMaster();
    }
  }catch(e){}
}
function acMasterClose(){
  const el = document.getElementById('acMaster'); if(!el) return;
  el.classList.remove('go');
  setTimeout(()=>{ try{ el.remove(); }catch(e){} }, 260);
}
function acMasterAct(kind, idx){
  acMasterClose();
  setTimeout(()=>{
    if(kind === 'cert') acIssueCert();
    else if(kind === 'next') acOpenLesson(idx);
  }, 180);
}
function acLessonMaster(){
  try{
    const old = document.getElementById('acMaster'); if(old) old.remove();
    const L = acCur(), ls = acLS(), ci = acCourseOf(acL);
    const lastInCourse = (acL === acCourseFirst(ci) + AC_COURSES[ci].count - 1);
    const nextIdx = acL + 1;
    /* умный CTA: сначала — забрать сертификат, иначе — следующий урок, иначе просто закрыть */
    let cta = '';
    if(acCertEligible())
      cta = `<button class="btn ac-master-cta" onclick="acMasterAct('cert')">${I('star')} Получить сертификат</button>`;
    else if(!lastInCourse && acUnlocked(nextIdx))
      cta = `<button class="btn ac-master-cta" onclick="acMasterAct('next',${nextIdx})">${I('circle-play')} Следующий урок</button>`;
    const pills = ['Видео','Слайды','Тест','Практика','Игра']
      .map((t,i)=>`<span class="ac-master-pill" style="--pd:${(i*0.06).toFixed(2)}s">${I('check2')}${t}</span>`).join('');
    let rays = ''; for(let i=0;i<12;i++) rays += `<i style="--a:${(i*360/12)}deg;--d:${(i%3)*0.05}s"></i>`;
    let conf = '';
    for(let i=0;i<20;i++){
      const x=(Math.random()*100).toFixed(1), dl=(Math.random()*0.4).toFixed(2),
            rot=(Math.random()*360).toFixed(0), sx=(Math.random()*0.7+0.6).toFixed(2);
      conf += `<b style="left:${x}%;--dl:${dl}s;--rot:${rot}deg;--sx:${sx}"></b>`;
    }
    const el = document.createElement('div');
    el.id = 'acMaster'; el.className = 'ac-master';
    el.innerHTML = `
      <div class="ac-master-conf">${conf}</div>
      <div class="ac-master-card" onclick="event.stopPropagation()">
        <div class="ac-master-badge">
          <span class="ac-master-rays">${rays}</span>
          <span class="ac-master-seal">${I('crown')}</span>
        </div>
        <div class="ac-master-kick">Урок пройден на 100%</div>
        <h3 class="ac-master-title">Урок освоен</h3>
        <p class="ac-master-sub">«${esc(L.title)}» — все пять этапов закрыты</p>
        <div class="ac-master-pills">${pills}</div>
        <div class="ac-master-stat">${I('poll')} Тест — <b>${ls.testScore||0}%</b></div>
        <div class="ac-master-actions">
          ${cta}
          <button class="btn ${cta?'ghost':''} ac-master-dismiss" onclick="acMasterClose()">${cta?'Позже':'Отлично'}</button>
        </div>
      </div>`;
    el.addEventListener('click', acMasterClose);   // тап по фону — закрыть
    document.body.appendChild(el);
    requestAnimationFrame(()=>el.classList.add('go'));
  }catch(e){}
}

/* --- отрисовка canvas 1600×1131 --- */
function acSigImage(cb){
  if(typeof SIGNATURE_B64 === 'undefined'){ cb(null); return; }
  const img = new Image();
  img.onload = ()=>{
    try{
      const c = document.createElement('canvas');
      c.width = img.width; c.height = img.height;
      const x = c.getContext('2d');
      x.drawImage(img, 0, 0);
      const d = x.getImageData(0, 0, c.width, c.height), p = d.data;
      for(let i=0; i<p.length; i+=4){
        const lum = (p[i]+p[i+1]+p[i+2]) / 3;
        p[i+3] = Math.round(p[i+3] * (1 - lum/255)); // тёмный штрих → непрозрачный
        p[i]=232; p[i+1]=240; p[i+2]=255;            // перекрас в светлый (для тёмного фона)
      }
      x.putImageData(d, 0, 0);
      cb(c);
    }catch(e){ cb(img); }
  };
  img.onerror = ()=>cb(null);
  img.src = 'data:image/png;base64,' + SIGNATURE_B64;
}
function acRingText(ctx, cx, cy, r, text, font){
  ctx.save();
  ctx.font = font;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  const step = (Math.PI*2) / text.length;
  for(let i=0; i<text.length; i++){
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(i*step);
    ctx.translate(0, -r);
    ctx.fillText(text[i], 0, 0);
    ctx.restore();
  }
  ctx.restore();
}
function acDrawSeal(ctx, cx, cy, r){
  const blue = '#2b4fd8';
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(-0.12);
  ctx.translate(-cx, -cy);
  // лёгкая подложка, чтобы синяя печать читалась на тёмном
  ctx.beginPath(); ctx.arc(cx, cy, r+6, 0, 7);
  ctx.fillStyle = 'rgba(255,255,255,.07)'; ctx.fill();
  ctx.strokeStyle = blue; ctx.fillStyle = blue; ctx.globalAlpha = .96;
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, 7); ctx.lineWidth = 4; ctx.stroke();
  ctx.beginPath(); ctx.arc(cx, cy, r-7, 0, 7); ctx.lineWidth = 1.5; ctx.stroke();
  ctx.beginPath(); ctx.arc(cx, cy, r*0.6, 0, 7); ctx.lineWidth = 2; ctx.stroke();
  acRingText(ctx, cx, cy, r-24, SEAL_REQ.fio + ' · ' + SEAL_REQ.inn + ' · ', '700 14px Montserrat, Arial');
  acRingText(ctx, cx, cy, r*0.6 - 15, SEAL_REQ.geo + ' · ОФИЦИАЛЬНЫЙ ДОКУМЕНТ · ', '600 9px Montserrat, Arial');
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.font = '800 21px Montserrat, Arial';
  ctx.fillText(SEAL_REQ.brand, cx, cy-6);
  ctx.font = '600 11px Montserrat, Arial';
  ctx.fillText('АКАДЕМИЯ', cx, cy+16);
  ctx.restore();
}
function acMakeCert(cert, cb){
  const ready = (document.fonts && document.fonts.load)
    ? Promise.all([
        document.fonts.load('100px "Bebas Neue"'),
        document.fonts.load('700 30px Montserrat'),
      ]).catch(()=>{})
    : Promise.resolve();
  ready.then(()=>acSigImage(sig=>{
    const W = 1600, H = 1131;
    const cv = document.createElement('canvas');
    cv.width = W; cv.height = H;
    const ctx = cv.getContext('2d');
    const lime = '#9AFF00';
    // фон + тонкая сетка
    ctx.fillStyle = '#0a0a0a'; ctx.fillRect(0, 0, W, H);
    ctx.strokeStyle = 'rgba(154,255,0,.05)'; ctx.lineWidth = 1;
    for(let x=0; x<=W; x+=64){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
    for(let y=0; y<=H; y+=64){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
    // мягкое свечение в углу
    const g = ctx.createRadialGradient(W-220, 180, 40, W-220, 180, 560);
    g.addColorStop(0, 'rgba(154,255,0,.10)'); g.addColorStop(1, 'rgba(154,255,0,0)');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    // двойная лаймовая рамка
    ctx.strokeStyle = lime; ctx.lineWidth = 5; ctx.strokeRect(38, 38, W-76, H-76);
    ctx.lineWidth = 1.5; ctx.globalAlpha = .65; ctx.strokeRect(58, 58, W-116, H-116); ctx.globalAlpha = 1;
    // уголки
    ctx.lineWidth = 5;
    [[38,38,1,1],[W-38,38,-1,1],[38,H-38,1,-1],[W-38,H-38,-1,-1]].forEach(([x,y,dx,dy])=>{
      ctx.beginPath(); ctx.moveTo(x+dx*44, y); ctx.lineTo(x, y); ctx.lineTo(x, y+dy*44); ctx.stroke();
    });
    try{ ctx.letterSpacing = '6px'; }catch(e){}
    ctx.textAlign = 'center';
    // шапка
    ctx.fillStyle = 'rgba(255,255,255,.55)';
    ctx.font = '42px "Bebas Neue", Impact, sans-serif';
    ctx.fillText('А К А Д Е М И Я   O K O', W/2, 148);
    // заголовок
    ctx.fillStyle = lime;
    ctx.shadowColor = 'rgba(154,255,0,.45)'; ctx.shadowBlur = 34;
    ctx.font = '150px "Bebas Neue", Impact, sans-serif';
    ctx.fillText('СЕРТИФИКАТ', W/2, 300);
    ctx.shadowBlur = 0;
    try{ ctx.letterSpacing = '2px'; }catch(e){}
    ctx.fillStyle = 'rgba(255,255,255,.6)';
    ctx.font = '500 27px Montserrat, Arial';
    ctx.fillText('подтверждает, что', W/2, 372);
    // имя
    ctx.fillStyle = '#fff';
    ctx.font = '96px "Bebas Neue", Impact, sans-serif';
    ctx.fillText(cert.name.toUpperCase(), W/2, 486);
    ctx.strokeStyle = 'rgba(154,255,0,.5)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(W/2-260, 512); ctx.lineTo(W/2+260, 512); ctx.stroke();
    // курс / урок
    const gi = (typeof cert.lesson === 'number' ? cert.lesson : 0);
    const lessonNo = cert.localNo || (acLocalNo ? acLocalNo(gi) : gi+1);
    const courseTitle = cert.courseTitle || AC_COURSES[acCourseOf(gi)].title;
    const lessonTitle = '«' + (cert.lessonTitle || AC_COURSE[0].title).toUpperCase() + '»';
    ctx.fillStyle = 'rgba(255,255,255,.6)';
    ctx.font = '500 26px Montserrat, Arial';
    ctx.fillText('успешно прошёл урок ' + lessonNo, W/2, 566);
    ctx.fillStyle = lime;
    let fs = 64;
    ctx.font = fs + 'px "Bebas Neue", Impact, sans-serif';
    while(fs > 40 && ctx.measureText(lessonTitle).width > W-260){
      fs -= 4;
      ctx.font = fs + 'px "Bebas Neue", Impact, sans-serif';
    }
    ctx.fillText(lessonTitle, W/2, 646);
    ctx.fillStyle = 'rgba(255,255,255,.6)';
    ctx.font = '500 24px Montserrat, Arial';
    ctx.fillText('курса «' + courseTitle + '» Академии ХЛБ', W/2, 696);
    // чип результата
    const chipT = 'Результат теста: ' + cert.score + '%';
    ctx.font = '700 26px Montserrat, Arial';
    const cw = ctx.measureText(chipT).width + 66;
    ctx.fillStyle = 'rgba(154,255,0,.13)';
    ctx.beginPath();
    if(ctx.roundRect) ctx.roundRect(W/2-cw/2, 730, cw, 58, 29); else ctx.rect(W/2-cw/2, 730, cw, 58);
    ctx.fill();
    ctx.strokeStyle = lime; ctx.lineWidth = 1.6; ctx.stroke();
    ctx.fillStyle = lime;
    ctx.fillText(chipT, W/2, 768);
    // дата и номер (слева внизу)
    ctx.textAlign = 'left';
    ctx.fillStyle = 'rgba(255,255,255,.45)';
    ctx.font = '600 19px Montserrat, Arial';
    ctx.fillText('ДАТА ВЫДАЧИ', 120, 878);
    ctx.fillStyle = '#fff';
    ctx.font = '46px "Bebas Neue", Impact, sans-serif';
    ctx.fillText(cert.date, 120, 928);
    ctx.fillStyle = 'rgba(255,255,255,.45)';
    ctx.font = '600 19px Montserrat, Arial';
    ctx.fillText('НОМЕР', 120, 972);
    ctx.fillStyle = lime;
    ctx.font = '700 26px Montserrat, Arial';
    ctx.fillText('№ ' + cert.no, 120, 1004);
    // подпись (по центру-слева внизу)
    const sx1 = 560, sx2 = 880, sy = 952;
    ctx.strokeStyle = 'rgba(255,255,255,.55)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(sx1, sy); ctx.lineTo(sx2, sy); ctx.stroke();
    if(sig){
      const sw = 300, sh = sw * (sig.height / sig.width);
      ctx.drawImage(sig, (sx1+sx2)/2 - sw/2, sy - sh*0.82, sw, sh);
    }
    ctx.fillStyle = '#fff';
    ctx.font = '600 24px Montserrat, Arial';
    ctx.fillText('/ Артём Бриус /', sx2 + 18, sy + 8);
    ctx.fillStyle = 'rgba(255,255,255,.4)';
    ctx.font = '500 16px Montserrat, Arial';
    ctx.fillText('подпись руководителя Академии', sx1, sy + 32);
    // печать (справа внизу)
    acDrawSeal(ctx, 1350, 900, 138);
    // реквизиты снизу мелко
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(255,255,255,.34)';
    ctx.font = '500 15px Montserrat, Arial';
    ctx.fillText(SEAL_REQ.fio + ' · ' + SEAL_REQ.inn + ' · ' + SEAL_REQ.brand + ' · hlbapp.ru@gmail.com', W/2, 1076);
    cb(cv.toDataURL('image/png'));
  }));
}

function acCertRec(i){
  if(typeof i === 'number' && acS.certs[i]) return acS.certs[i];
  if(acCertShownNo){
    const shown = acS.certs.find(c=>c.no===acCertShownNo);
    if(shown) return shown;
  }
  return (acView==='lesson' ? acDirCert(acCourseOf(acL)) : null) || acS.certs[0] || null;
}
function acCertShow(i){
  const cert = (typeof i === 'number') ? acS.certs[i] : (acDirCert(acCourseOf(acL)) || acCertRec());
  if(!cert){ toast('Сертификат ещё не выдан'); return; }
  const open = url=>{
    const full = document.getElementById('acCertFull');
    const img = document.getElementById('acCertFullImg');
    if(!full || !img) return;
    img.src = url;
    full.classList.add('open');
  };
  if(acCertUrl && acCertShownNo === cert.no){ open(acCertUrl); return; }
  acMakeCert(cert, url=>{ acCertUrl = url; acCertShownNo = cert.no; open(url); });
}
function acCertFullClose(){
  const full = document.getElementById('acCertFull');
  if(full) full.classList.remove('open');
}
function acCertDownload(){
  const cert = acCertRec();
  if(!cert){ toast('Сертификат ещё не выдан'); return; }
  const dl = url=>{
    const a = document.createElement('a');
    a.href = url; a.download = cert.no + '.png';
    document.body.appendChild(a); a.click(); a.remove();
    toast('PNG сохранён: ' + cert.no + '.png');
  };
  if(acCertUrl && acCertShownNo === cert.no){ dl(acCertUrl); return; }
  acMakeCert(cert, url=>{ acCertUrl = url; acCertShownNo = cert.no; dl(url); });
}

/* ================= СЕРТИФИКАТЫ В ПРОФИЛЕ =================
   Именные сертификаты Академии показываем прямо в профиле (карточка после
   ачивок). Инъекция через chain-патч renderMyProfile: на каждый ре-рендер
   профиля пере-вставляем свежую карточку (старую удаляем — без дублей). */
function acProfileCertsHtml(){
  const n = acS.certs.length;
  const head = `
    <div class="ac-pcerts-head">
      <span class="ico">${I('star')}</span>
      <div class="meta"><b>Сертификаты Академии</b><span>${n
        ? n + ' ' + acPlural(n, ['официальный','официальных','официальных']) + ' · печать и подпись'
        : 'Пройди направление — получи именной документ'}</span></div>
      <button class="btn sm ghost" onclick="showTab('academy')">${n?'Все':'В Академию'}</button>
    </div>`;
  if(!n){
    return `<div class="card ac-pcerts empty" id="acProfCerts">${head}${acProfileBadgesHtml()}
      <p class="ac-pcerts-invite">Пройди все уроки направления (порог теста ${AC_PASS}%+) — и получи именной сертификат ХЛБ с печатью и подписью руководителя Академии. Он появится здесь и в разделе «Академия».</p></div>`;
  }
  const show = acS.certs.slice(0, 3).map((c)=>{
    const gi = acS.certs.indexOf(c);
    return `<div class="ac-pcert-row">
      <span class="ico">${I('file')}</span>
      <span class="meta"><span class="t">${esc(acCertLabel(c))}</span>
      <span class="s">${esc(c.no)} · ${esc(c.date)} · тест ${c.score}%</span></span>
      <button class="btn sm ghost ac-ico-btn" onclick="acCertShare(${gi})" title="Поделиться" aria-label="Поделиться">${I('share')}</button>
      <button class="btn sm ghost" onclick="acCertShow(${gi})">Показать</button>
    </div>`;
  }).join('');
  const more = n > 3 ? `<button class="ac-pcerts-more" onclick="showTab('academy')">и ещё ${n-3} ${acPlural(n-3,['сертификат','сертификата','сертификатов'])} — в Академии ${I('chev')}</button>` : '';
  return `<div class="card ac-pcerts" id="acProfCerts">${head}${acProfileBadgesHtml()}<div class="ac-pcert-list">${show}</div>${more}</div>`;
}
/* компактная полоса заслуженных бейджей для профиля */
function acProfileBadgesHtml(){
  const on = acBadgeDefs().filter(b=>b.on);
  if(!on.length) return '';
  return `<div class="ac-pbadges">${on.map(b=>`<span class="ac-pbadge" title="${b.d}">${I(b.ic)}<span>${b.t}</span></span>`).join('')}</div>`;
}
function acPlural(n, forms){
  const a = Math.abs(n) % 100, b = a % 10;
  if(a > 10 && a < 20) return forms[2];
  if(b > 1 && b < 5) return forms[1];
  if(b === 1) return forms[0];
  return forms[2];
}
function acProfileInject(){
  try{
    const anchor = document.getElementById('profAch');
    if(!anchor || !anchor.parentNode) return;
    const old = document.getElementById('acProfCerts');
    if(old) old.remove();
    const wrap = document.createElement('div');
    wrap.innerHTML = acProfileCertsHtml();
    const node = wrap.firstElementChild;
    if(!node) return;
    node.style.marginTop = '14px';
    anchor.parentNode.insertBefore(node, anchor.nextSibling);
  }catch(e){}
}

/* ================= САМОИНИЦИАЛИЗАЦИЯ ================= */
(function acInit(){
  regTitle('academy', 'Академия');
  addSvcTile({id:'academy', label:'Академия', ico:'star', first:true, onclick:()=>showTab('academy')});
  const _prevShowTabAc = showTab;
  showTab = function(t){
    _prevShowTabAc(t);
    if(t === 'academy'){ acStreakTouch(); acRender(); }
  };
  /* сертификаты в профиле: chain-патч renderMyProfile */
  if(typeof renderMyProfile === 'function'){
    const _acPrevRenderProfile = renderMyProfile;
    renderMyProfile = function(){
      _acPrevRenderProfile.apply(this, arguments);
      acProfileInject();
    };
  }
  const scr = document.getElementById('screen-academy');
  if(scr && scr.classList.contains('active')){ acStreakTouch(); acRender(); }
  /* если профиль уже открыт при инициализации — сразу вставим сертификаты */
  const sp = document.getElementById('screen-profile');
  if(sp && sp.classList.contains('active')) acProfileInject();
  setTimeout(acRemindCheck, 2200);           // напоминание об уроке — раз в сутки
})();

/* ===== module: academy-plus ===== */
/* ===== ACADEMY-PLUS: Duolingo + Coursera + Skillshare механики =====
   Всё поверх academy через chain-patch — базовый модуль не трогаем.
   Префикс: acd- (CSS/HTML), apd (JS-функции). */
(function acdInit(){
  if(typeof acRender !== 'function' || typeof AC_COURSES === 'undefined'){
    // academy не загружен — тихо выходим
    return;
  }

  /* =============================================================
     ХРАНИЛИЩЕ: расширяем acS собственными разделами (пишет acSave)
     ============================================================= */
  function apdEnsureStore(){
    if(!acS.notes) acS.notes = {};       // {lessonIdx: text}
    if(!acS.comments) acS.comments = {}; // {lessonIdx: [rec]}
    if(!acS.filter) acS.filter = 'all';  // текущий фильтр каталога
    if(typeof acS.streakWeeksPaid !== 'number') acS.streakWeeksPaid = 0;
  }
  apdEnsureStore();

  /* =============================================================
     3. XP + STREAK: связка с играми (gmXpAdd) — +30 XP за урок,
        +100 XP за каждые 7 дней подряд в учёбе (один раз на неделю).
     ============================================================= */
  const APD_XP_LESSON = 30;
  const APD_XP_STREAK_7 = 100;
  function apdAwardLessonXP(){
    try{
      const ls = acLS();
      if(ls.xpAwarded) return;
      ls.xpAwarded = true; acSave();
      if(typeof gmXpAdd === 'function') gmXpAdd(APD_XP_LESSON, 'academy:lesson:'+acL);
      toast('+' + APD_XP_LESSON + ' XP · урок освоен');
      // Стрик-бонус: за каждую 7-дневную серию — один раз
      const st = acStreak();
      if(st && st.days >= 7){
        const wk = Math.floor(st.days / 7);
        if(wk > (acS.streakWeeksPaid||0)){
          acS.streakWeeksPaid = wk; acSave();
          if(typeof gmXpAdd === 'function') gmXpAdd(APD_XP_STREAK_7, 'academy:streak:'+(wk*7));
          setTimeout(()=>toast('Серия ' + (wk*7) + ' дней · +' + APD_XP_STREAK_7 + ' XP'), 1200);
        }
      }
    }catch(e){}
  }
  // chain-patch: после того, как academy засчитала последний чек-пойнт
  const _apdPrevAfter = window.acAfterCheckpoint;
  window.acAfterCheckpoint = function(){
    try{ _apdPrevAfter && _apdPrevAfter.apply(this, arguments); }catch(e){}
    try{ if(acLessonPct(acL) === 100) apdAwardLessonXP(); }catch(e){}
    apdRerenderStepRail();
  };

  /* =============================================================
     Утилита: инъекция плагин-контента в конец страницы урока
     ============================================================= */
  function apdInjectLessonExtras(){
    try{
      if(acView !== 'lesson') return;
      const root = document.getElementById('acRoot');
      if(!root) return;
      // 2. Прогресс-таймлайн — в самое начало (после кнопки Назад)
      const back = root.querySelector('.ac-back');
      if(back && !root.querySelector('.acd-steprail')){
        const rail = document.createElement('div');
        rail.className = 'acd-steprail';
        rail.id = 'acdStepRail';
        rail.innerHTML = apdStepRailHtml();
        back.insertAdjacentElement('afterend', rail);
      }
      // 7. Рекомендации — перед последней "заглушкой" (перед acCertBox)
      const certBox = document.getElementById('acCertBox');
      if(certBox && !root.querySelector('#acdReco')){
        const reco = document.createElement('div');
        reco.id = 'acdReco';
        reco.innerHTML = apdRecoHtml();
        certBox.parentNode.insertBefore(reco, certBox);
      }
      // 6. Комментарии — после сертификата
      if(certBox && !root.querySelector('#acdComments')){
        const cm = document.createElement('div');
        cm.id = 'acdComments';
        cm.className = 'card acd-comments';
        cm.innerHTML = apdCommentsInnerHtml();
        // вставляем СРАЗУ ПОСЛЕ acCertBox
        certBox.parentNode.insertBefore(cm, certBox.nextSibling);
      }
      // 9. Кнопка «Заметки» (плавающая)
      apdMountNotesFab();
    }catch(e){}
  }
  function apdRemoveLessonExtras(){
    ['acdStepRail','acdReco','acdComments','acdNotesFab'].forEach(id=>{
      const el = document.getElementById(id); if(el) el.remove();
    });
  }

  /* =============================================================
     2. ПРОГРЕСС-ТАЙМЛАЙН УРОКА (Coursera-стиль)
     ============================================================= */
  const APD_STEPS = [
    {k:'slides',   ic:'file',        lbl:'Слайды',   anchor:'#acSlidesBox'},
    {k:'test',     ic:'poll',        lbl:'Тест',     anchor:'#acTestBox'},
    {k:'task',     ic:'edit',        lbl:'Практика', anchor:'#acTaskBox'},
    {k:'game',     ic:'bolt',        lbl:'Игра',     anchor:'#acGameBox'},
    {k:'cert',     ic:'star',        lbl:'Диплом',   anchor:'#acCertBox'},
  ];
  function apdStepStatus(k){
    const ls = acLS() || {};
    if(k === 'cert') return typeof acCourseDone==='function' && acCourseDone(acCourseOf(acL));
    return !!ls[k];
  }
  function apdStepRailHtml(){
    const done = APD_STEPS.filter(s=>apdStepStatus(s.k)).length;
    const pct = Math.round(done / APD_STEPS.length * 100);
    // текущий шаг = первый недоделанный (или последний, если всё)
    let curIdx = APD_STEPS.findIndex(s=>!apdStepStatus(s.k));
    if(curIdx < 0) curIdx = APD_STEPS.length - 1;
    const cells = APD_STEPS.map((s,i)=>{
      const d = apdStepStatus(s.k);
      const c = (i === curIdx && !d);
      const dot = d ? I('check2') : String(i+1);
      const sep = i < APD_STEPS.length-1 ? `<span class="acd-step-bar ${d?'done':''}"></span>` : '';
      return `<button class="acd-step ${d?'done':''} ${c?'cur':''}" onclick="apdStepGo('${s.anchor}')" aria-label="${esc(s.lbl)}">
                <span class="acd-step-dot">${dot}</span>
                <span class="acd-step-lbl">${esc(s.lbl)}</span>
              </button>${sep}`;
    }).join('');
    return `<div class="acd-steprail-head">
        <span>Шаг <b>${Math.min(curIdx+1, APD_STEPS.length)}</b> из ${APD_STEPS.length} · <b>${pct}%</b></span>
        <span class="acd-xp-badge">${I('bolt')} +${APD_XP_LESSON} XP</span>
      </div>
      <div class="acd-steprail-line">${cells}</div>
      <div class="acd-steprail-track"><i style="width:${pct}%"></i></div>`;
  }
  window.apdStepGo = function(anchor){
    const el = document.querySelector(anchor);
    if(!el) return;
    const m = document.querySelector('main');
    if(m){
      const rect = el.getBoundingClientRect();
      m.scrollTo({top: m.scrollTop + rect.top - 90, behavior:'smooth'});
    } else el.scrollIntoView({behavior:'smooth', block:'start'});
  };
  function apdRerenderStepRail(){
    const rail = document.getElementById('acdStepRail');
    if(rail) rail.innerHTML = apdStepRailHtml();
  }

  /* =============================================================
     7. РЕКОМЕНДАЦИЯ: "Ты закончил X → тебе понравится Y"
        Матчинг по инструментам (AC_TOOLS) + слова-теги из заголовков
     ============================================================= */
  function apdLessonTags(i){
    try{
      const L = AC_COURSE[i]; if(!L) return [];
      const hay = ((L.title||'') + ' ' + (L.slides||[]).map(s=>(s.pts||[]).join(' ')).join(' ')).toLowerCase();
      const t = [];
      if(typeof AC_TOOLS !== 'undefined'){
        Object.keys(AC_TOOLS).forEach(k=>{ if(hay.includes(k)) t.push('t:'+k); });
      }
      // ключевые слова-теги (частотные для направлений)
      ['промпт','видео','сторис','упаковка','контент','маркетинг','воронка','монетизация',
       'нейросети','автомат','агент','аналитик','копирайт','триггер','бренд','целевая','воронк']
        .forEach(w=>{ if(hay.includes(w)) t.push('w:'+w); });
      return t;
    }catch(e){ return []; }
  }
  function apdRecommendations(currentIdx, N){
    const N_ = N || 3;
    const curTags = new Set(apdLessonTags(currentIdx));
    const seen = new Set([currentIdx]);
    const scored = [];
    for(let i=0; i<AC_COURSE.length; i++){
      if(seen.has(i)) continue;
      if(typeof acUnlocked==='function' && !acUnlocked(i)) continue;
      if(typeof acLessonDone==='function' && acLessonDone(i)) continue;
      const tags = apdLessonTags(i);
      let score = 0;
      tags.forEach(t=>{ if(curTags.has(t)) score += (t.startsWith('t:') ? 3 : 1); });
      // бонус: соседний урок в том же курсе
      if(acCourseOf(i) === acCourseOf(currentIdx)) score += 1;
      // бонус: тот же блок
      const bA = AC_BLOCKS.find(b=>i>=b.from && i<b.from+b.count);
      const bB = AC_BLOCKS.find(b=>currentIdx>=b.from && b<b.from+b.count);
      if(bA && bB && bA.id === bB.id) score += 1;
      if(score > 0) scored.push({i, score, matches: tags.filter(t=>curTags.has(t))});
    }
    scored.sort((a,b)=> b.score - a.score);
    // fallback: если совпадений нет — предложим первые доступные незавершённые
    if(!scored.length){
      for(let i=0; i<AC_COURSE.length && scored.length<N_; i++){
        if(seen.has(i)) continue;
        if(typeof acUnlocked==='function' && !acUnlocked(i)) continue;
        if(typeof acLessonDone==='function' && acLessonDone(i)) continue;
        scored.push({i, score:0, matches:[]});
      }
    }
    return scored.slice(0, N_);
  }
  function apdRecoWhy(rec){
    if(!rec || !rec.matches || !rec.matches.length){
      return 'Дальше по программе';
    }
    const t = rec.matches.find(x=>x.startsWith('t:'));
    if(t){
      const key = t.slice(2);
      const tool = (typeof AC_TOOLS!=='undefined' && AC_TOOLS[key]) ? AC_TOOLS[key].name : key;
      return 'По ' + tool;
    }
    const w = rec.matches.find(x=>x.startsWith('w:'));
    if(w) return 'По теме';
    return 'Близко';
  }
  function apdRecoHtml(){
    const recs = apdRecommendations(acL, 3);
    if(!recs.length) return '';
    const rows = recs.map(r=>{
      const L = AC_COURSE[r.i];
      const ci = acCourseOf(r.i);
      const num = (typeof acLocalNo==='function') ? acLocalNo(r.i) : (r.i+1);
      const meta = AC_COURSES[ci].title + ' · урок ' + num;
      return `<button class="acd-reco-item" onclick="apdRecoGo(${r.i})">
        <span class="n">${num}</span>
        <span class="meta"><b>${esc(L.title)}</b><span>${esc(meta)}</span></span>
        <span class="why">${esc(apdRecoWhy(r))}</span>
        <svg class="i go"><use href="#i-chev"/></svg>
      </button>`;
    }).join('');
    return `<div class="card acd-reco">
      <div class="acd-reco-head">${I('rocket')} Тебе понравится · подобрано по темам урока</div>
      <div class="acd-reco-list">${rows}</div>
    </div>`;
  }
  window.apdRecoGo = function(i){ if(typeof acOpenLesson==='function') acOpenLesson(i); };

  /* =============================================================
     6. КОММЕНТАРИИ (localStorage, вложенные ответы, лайки)
     ============================================================= */
  function apdMe(){
    const nick = (window.PROFILE && PROFILE.nick) || 'guest';
    const name = (window.PROFILE && PROFILE.name) || 'Слушатель';
    return {nick, name};
  }
  function apdCommsFor(i){
    const st = acS.comments || {};
    if(!st[i]) st[i] = [];
    return st[i];
  }
  function apdAva(name){
    return esc((name||'?').trim().charAt(0).toUpperCase());
  }
  function apdWhen(ts){
    const d = Date.now() - ts;
    if(d < 60_000) return 'только что';
    if(d < 3600_000) return Math.floor(d/60_000) + ' мин назад';
    if(d < 86_400_000) return Math.floor(d/3_600_000) + ' ч назад';
    if(d < 30 * 86_400_000) return Math.floor(d/86_400_000) + ' д назад';
    return new Date(ts).toLocaleDateString('ru-RU');
  }
  function apdCommentsInnerHtml(){
    const list = apdCommsFor(acL);
    const cnt = list.reduce((n,c)=>n + 1 + ((c.replies||[]).length), 0);
    const me = apdMe();
    const body = list.length ? `<div class="acd-comment-list">${list.map(c=>apdCommentHtml(c)).join('')}</div>`
      : `<div class="acd-comment-empty">Пока никто не писал. Задай первый вопрос автору или поделись инсайтом — другим будет полезно.</div>`;
    return `<div class="acd-comments-head">
        <span class="ico">${I('comment')}</span>
        <div><b>Обсуждение урока</b><span class="n">${cnt} ${apdPlural(cnt,['ответ','ответа','ответов'])} · вопросы, инсайты, разбор кейсов</span></div>
      </div>
      <div class="acd-comment-form">
        <textarea class="acd-comment-ta" id="acdCommTa" placeholder="Задай вопрос автору или поделись, что откликнулось. Другим слушателям это поможет."></textarea>
        <div class="acd-comment-actions">
          <span>${esc(me.name)} · публично для всех</span>
          <button class="btn sm" onclick="apdCommSend()">${I('send')} Отправить</button>
        </div>
      </div>
      ${body}`;
  }
  function apdCommentHtml(c, isReply){
    const me = apdMe();
    const isMe = c.nick === me.nick;
    const liked = !!(c.likedBy && c.likedBy[me.nick]);
    const replies = (c.replies||[]).map(r=>apdCommentHtml(r, true)).join('');
    const clsRoot = isReply ? 'acd-comment acd-reply' : 'acd-comment';
    const replyForm = !isReply ? `
      <div class="acd-reply-form">
        <input type="text" id="acdRep_${c.id}" placeholder="Ответить…" onkeydown="if(event.key==='Enter')apdCommSend('${c.id}')">
        <button onclick="apdCommSend('${c.id}')">Ответить</button>
      </div>` : '';
    const del = isMe ? `<button class="acd-comment-act" onclick="apdCommDel('${c.id}')" title="Удалить">${I('plus')}</button>` : '';
    return `<div class="${clsRoot} ${isMe?'author':''}">
      <span class="ava">${apdAva(c.name)}</span>
      <div class="bd">
        <div class="hd"><b>${esc(c.name)}</b><span class="ts">${esc(apdWhen(c.ts))}</span></div>
        <div class="tx">${esc(c.text)}</div>
        <div class="acts">
          <button class="acd-comment-act ${liked?'liked':''}" onclick="apdCommLike('${c.id}')">${I('heart')} <span>${c.likes||0}</span></button>
          ${del}
        </div>
        ${replies ? `<div class="acd-replies">${replies}</div>` : ''}
        ${replyForm}
      </div>
    </div>`;
  }
  window.apdCommSend = function(parentId){
    let val;
    if(parentId){
      const inp = document.getElementById('acdRep_'+parentId);
      val = inp ? (inp.value||'').trim() : '';
      if(inp) inp.value = '';
    } else {
      const ta = document.getElementById('acdCommTa');
      val = ta ? (ta.value||'').trim() : '';
      if(ta) ta.value = '';
    }
    if(val.length < 2){ toast('Слишком коротко'); return; }
    const me = apdMe();
    const rec = {id:'c'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),
                 name:me.name, nick:me.nick, text:val.slice(0,800), ts:Date.now(), likes:0, likedBy:{}};
    const arr = apdCommsFor(acL);
    if(parentId){
      const walk = (list)=>{
        for(const x of list){
          if(x.id === parentId){ x.replies = x.replies||[]; x.replies.push(rec); return true; }
          if(x.replies && walk(x.replies)) return true;
        }
        return false;
      };
      walk(arr);
    } else {
      arr.unshift(rec);
    }
    acSave();
    apdRefreshComments();
    if(!parentId) toast('Опубликовано');
  };
  window.apdCommLike = function(id){
    const me = apdMe();
    const arr = apdCommsFor(acL);
    const walk = (list)=>{
      for(const x of list){
        if(x.id === id){
          x.likedBy = x.likedBy || {};
          if(x.likedBy[me.nick]){ delete x.likedBy[me.nick]; x.likes = Math.max(0,(x.likes||1)-1); }
          else { x.likedBy[me.nick] = 1; x.likes = (x.likes||0)+1; }
          return true;
        }
        if(x.replies && walk(x.replies)) return true;
      }
      return false;
    };
    walk(arr);
    acSave();
    apdRefreshComments();
  };
  window.apdCommDel = function(id){
    const arr = apdCommsFor(acL);
    const idx = arr.findIndex(x=>x.id === id);
    if(idx >= 0){ arr.splice(idx,1); }
    else {
      // reply
      for(const x of arr){
        if(!x.replies) continue;
        const j = x.replies.findIndex(r=>r.id === id);
        if(j >= 0){ x.replies.splice(j,1); break; }
      }
    }
    acSave();
    apdRefreshComments();
    toast('Удалено');
  };
  function apdRefreshComments(){
    const box = document.getElementById('acdComments');
    if(box) box.innerHTML = apdCommentsInnerHtml();
  }
  function apdPlural(n, forms){
    const a = Math.abs(n) % 100, b = a % 10;
    if(a > 10 && a < 20) return forms[2];
    if(b > 1 && b < 5) return forms[1];
    if(b === 1) return forms[0];
    return forms[2];
  }

  /* =============================================================
     9. ЗАМЕТКИ К УРОКУ (плавающая кнопка + панель, localStorage)
     ============================================================= */
  function apdNoteText(){
    return (acS.notes && acS.notes[acL]) || '';
  }
  function apdMountNotesFab(){
    const scr = document.getElementById('screen-academy');
    if(!scr) return;
    const has = apdNoteText().length;
    let fab = document.getElementById('acdNotesFab');
    if(!fab){
      fab = document.createElement('button');
      fab.id = 'acdNotesFab';
      fab.className = 'acd-notes-fab';
      fab.setAttribute('aria-label','Заметки к уроку');
      fab.onclick = apdNotesOpen;
      document.body.appendChild(fab);
    }
    fab.innerHTML = I('edit') + (has ? '<span class="cnt">' + Math.min(999, has) + '</span>' : '');
  }
  window.apdNotesOpen = function(){
    let panel = document.getElementById('acdNotesPanel');
    if(!panel){
      panel = document.createElement('div');
      panel.id = 'acdNotesPanel';
      panel.className = 'acd-notes-panel';
      panel.onclick = function(e){ if(e.target === panel) apdNotesClose(); };
      document.body.appendChild(panel);
    }
    const L = acCur();
    panel.innerHTML = `
      <div class="acd-notes-card" onclick="event.stopPropagation()">
        <div class="acd-notes-hd">
          <span class="ico">${I('edit')}</span>
          <div class="tt"><b>Заметки к уроку</b><span>${esc(L.title)} · сохраняется автоматически на этом устройстве</span></div>
          <button class="cls" onclick="apdNotesClose()" aria-label="Закрыть">${I('plus')}</button>
        </div>
        <div class="acd-notes-body">
          <textarea class="acd-notes-ta" id="acdNotesTa" placeholder="Пиши инсайты, тезисы, вопросы, которые хочешь задать автору. Твои заметки — только твои: остаются на этом устройстве.">${esc(apdNoteText())}</textarea>
        </div>
        <div class="acd-notes-foot">
          <span class="meta">Слов: <b id="acdNotesWc">${apdWordCount(apdNoteText())}</b> · сохранено</span>
          <div class="acts">
            <button class="btn sm ghost" onclick="apdNotesClear()">Очистить</button>
            <button class="btn sm ghost" onclick="apdNotesExport()">${I('file')} Скопировать</button>
          </div>
        </div>
      </div>`;
    requestAnimationFrame(()=>panel.classList.add('open'));
    const ta = document.getElementById('acdNotesTa');
    if(ta){
      ta.addEventListener('input', ()=>{
        acS.notes[acL] = ta.value.slice(0, 12000);
        acSave();
        const wc = document.getElementById('acdNotesWc');
        if(wc) wc.textContent = apdWordCount(ta.value);
        apdMountNotesFab();
      });
      setTimeout(()=>ta.focus(), 50);
    }
  };
  window.apdNotesClose = function(){
    const p = document.getElementById('acdNotesPanel');
    if(p){ p.classList.remove('open'); }
  };
  window.apdNotesClear = function(){
    acS.notes[acL] = '';
    acSave();
    const ta = document.getElementById('acdNotesTa');
    if(ta) ta.value = '';
    const wc = document.getElementById('acdNotesWc');
    if(wc) wc.textContent = '0';
    apdMountNotesFab();
    toast('Заметки урока очищены');
  };
  window.apdNotesExport = function(){
    const t = apdNoteText();
    if(!t.trim()){ toast('Пусто — нечего копировать'); return; }
    const head = 'Заметки · ' + (acCur().title || 'урок') + '\n\n';
    const full = head + t;
    if(navigator.clipboard && navigator.clipboard.writeText){
      navigator.clipboard.writeText(full).then(()=>toast('Скопировано в буфер')).catch(()=>toast('Не удалось скопировать'));
    } else {
      const ta = document.createElement('textarea'); ta.value = full;
      ta.style.cssText = 'position:fixed;top:-200px'; document.body.appendChild(ta);
      ta.select(); try{ document.execCommand('copy'); toast('Скопировано в буфер'); }catch(e){ toast('Не удалось'); }
      ta.remove();
    }
  };
  function apdWordCount(s){
    return String(s||'').trim().split(/\s+/).filter(Boolean).length;
  }

  /* =============================================================
     1. ЛЕНИВАЯ ЗАГРУЗКА БЛОКОВ (collapsible) — post-processing DOM
     ============================================================= */
  function apdSetupCollapsibleBlocks(){
    if(acView !== 'course') return;
    const root = document.getElementById('acRoot');
    if(!root) return;
    const blocks = root.querySelectorAll('.ac-block');
    if(!blocks.length) return;
    // Определяем блок текущего/след. урока (авто-открытие)
    let autoBlockId = null;
    try{
      const ci = acCourse;
      const idx = (typeof acCourseIdx==='function') ? acCourseIdx(ci) : [];
      const target = idx.find(i=>acUnlocked(i) && !acLessonDone(i));
      if(target !== undefined){
        const b = AC_BLOCKS.find(bl=>target>=bl.from && target<bl.from+bl.count);
        if(b) autoBlockId = b.id;
      }
    }catch(e){}
    let curBlockAssigned = false;
    blocks.forEach((blk, i)=>{
      // определить id блока по индексу — читаем из соседних .ac-lesson-row (не нужно, авто = первый)
      const head = blk.querySelector('.ac-block-head');
      const body = blk.querySelectorAll(':scope > *:not(.ac-block-head)');
      if(!head || !body.length) return;
      // Обернём body в div.acd-block-body, если ещё не обёрнуто
      if(!blk.querySelector(':scope > .acd-block-body')){
        const wrap = document.createElement('div');
        wrap.className = 'acd-block-body';
        body.forEach(n=>wrap.appendChild(n));
        blk.appendChild(wrap);
      }
      // Toggle кнопка
      if(!head.querySelector('.acd-block-toggle')){
        const btn = document.createElement('button');
        btn.className = 'acd-block-toggle';
        btn.setAttribute('aria-label','Развернуть/свернуть блок');
        btn.innerHTML = I('chev');
        btn.onclick = function(e){ e.stopPropagation(); apdBlockToggle(blk); };
        head.appendChild(btn);
      }
      head.onclick = function(){ apdBlockToggle(blk); };
      // По умолчанию: первый блок и блок с активным уроком — открыты, остальные свёрнуты
      const shouldOpen = (i === 0) || (!curBlockAssigned && autoBlockId && blk.textContent.includes('Блок'));
      // Более надёжная эвристика: первый блок — точно открыт. Второй проход ниже — по id.
      if(i === 0){ blk.classList.add('acd-open'); curBlockAssigned = true; }
      else blk.classList.add('acd-collapsed');
    });
    // Второй проход — открыть блок с активным уроком по данным AC_BLOCKS
    try{
      if(autoBlockId){
        const ci = acCourse;
        const localBlocks = acCourseBlocks(ci);   // массив блоков курса в правильном порядке
        const targetPos = localBlocks.findIndex(b=>b.id === autoBlockId);
        if(targetPos >= 0 && targetPos < blocks.length){
          blocks.forEach((b,i)=>{
            if(i === targetPos){ b.classList.remove('acd-collapsed'); b.classList.add('acd-open'); }
            else if(i !== 0){ b.classList.add('acd-collapsed'); b.classList.remove('acd-open'); }
          });
          // если targetPos !== 0, первый блок закроем — оставим фокус на активном
          if(targetPos !== 0){
            blocks[0].classList.remove('acd-open');
            blocks[0].classList.add('acd-collapsed');
          }
        }
      }
    }catch(e){}
  }
  window.apdBlockToggle = function(blk){
    if(!blk) return;
    if(blk.classList.contains('acd-collapsed')){
      blk.classList.remove('acd-collapsed');
      blk.classList.add('acd-open');
    } else {
      blk.classList.add('acd-collapsed');
      blk.classList.remove('acd-open');
    }
  };

  /* =============================================================
     10. ФИЛЬТРЫ КАТАЛОГА (чипы: Все / Бесплатное / В процессе / Не начатые)
     ============================================================= */
  const APD_FILTERS = [
    {k:'all',   lbl:'Все',            ic:'compass'},
    {k:'free',  lbl:'Бесплатное',     ic:'bolt'},
    {k:'prog',  lbl:'В процессе',     ic:'circle-play'},
    {k:'new',   lbl:'Не начатые',     ic:'flag'},
    {k:'done',  lbl:'Пройденные',     ic:'check2'},
  ];
  function apdCourseMatchesFilter(ci, filter){
    const c = AC_COURSES[ci];
    const pct = (typeof acCoursePctOf==='function') ? acCoursePctOf(ci) : 0;
    const done = (typeof acCourseDone==='function') && acCourseDone(ci);
    switch(filter){
      case 'free': return !!c.free;
      case 'prog': return pct > 0 && !done;
      case 'new':  return pct === 0;
      case 'done': return done;
      default: return true;
    }
  }
  function apdFilterCounts(){
    const cnt = {};
    APD_FILTERS.forEach(f=>{
      cnt[f.k] = 0;
      for(let ci=0; ci<AC_COURSES.length; ci++){
        if(apdCourseMatchesFilter(ci, f.k)) cnt[f.k]++;
      }
    });
    return cnt;
  }
  function apdFiltersHtml(){
    const cnt = apdFilterCounts();
    const on = acS.filter || 'all';
    return `<div class="acd-filters" id="acdFilters">${
      APD_FILTERS.map(f=>`<button class="acd-chip ${on===f.k?'on':''}" onclick="apdFilterSet('${f.k}')">
        ${I(f.ic)}<span>${esc(f.lbl)}</span><span class="n">${cnt[f.k]}</span>
      </button>`).join('')
    }</div>`;
  }
  window.apdFilterSet = function(k){
    acS.filter = k; acSave();
    apdApplyCatalogFilter();
    // подсветка чипов
    document.querySelectorAll('#acdFilters .acd-chip').forEach(el=>el.classList.remove('on'));
    const chip = document.querySelector('#acdFilters .acd-chip[onclick*="\'' + k + '\'"]');
    if(chip) chip.classList.add('on');
  };
  function apdApplyCatalogFilter(){
    if(acView !== 'home') return;
    const cat = document.querySelector('#acRoot .ac-catalog');
    if(!cat) return;
    const cards = cat.querySelectorAll('.ac-cc');
    const on = acS.filter || 'all';
    let vis = 0;
    cards.forEach((card, ci)=>{
      const show = apdCourseMatchesFilter(ci, on);
      card.classList.toggle('acd-hidden', !show);
      if(show) vis++;
    });
    // Пустой стейт
    let empty = cat.parentNode.querySelector('.acd-filters-empty');
    if(!vis){
      if(!empty){
        empty = document.createElement('div');
        empty.className = 'acd-filters-empty';
        empty.textContent = 'В этой категории пока нет курсов. Смени фильтр.';
        cat.parentNode.insertBefore(empty, cat.nextSibling);
      }
    } else if(empty){ empty.remove(); }
  }
  function apdInjectCatalogFilters(){
    if(acView !== 'home') return;
    const root = document.getElementById('acRoot');
    if(!root) return;
    if(root.querySelector('#acdFilters')) return;
    const cat = root.querySelector('.ac-catalog');
    if(!cat) return;
    const holder = document.createElement('div');
    holder.innerHTML = apdFiltersHtml();
    cat.parentNode.insertBefore(holder.firstElementChild, cat);
    apdApplyCatalogFilter();
  }

  /* =============================================================
     8. СКОРОСТЬ ВИДЕО: кнопка 1× → 1.25× → 1.5× → 2× → 0.75× → 1×
        Пост-обрабатываем acVpBar после render'а
     ============================================================= */
  const APD_SPEEDS = [1, 1.25, 1.5, 2, 0.75];
  function apdReadSpeed(){
    try{ const v = parseFloat(localStorage.getItem('oko-ac-speed')); return isFinite(v) && v > 0 ? v : 1; }catch(e){ return 1; }
  }
  function apdSaveSpeed(v){ try{ localStorage.setItem('oko-ac-speed', String(v)); }catch(e){} }
  function apdInjectSpeed(){
    const bar = document.getElementById('acVpBar');
    if(!bar || bar.querySelector('.acd-vp-speed')) return;
    const v = apdReadSpeed();
    const btn = document.createElement('button');
    btn.className = 'ac-vp-btn acd-vp-speed';
    btn.type = 'button';
    btn.setAttribute('aria-label','Скорость воспроизведения');
    btn.textContent = apdFmtSpeed(v);
    btn.onclick = function(e){ if(e) e.stopPropagation(); apdSpeedCycle(btn); };
    // ставим перед кнопкой fullscreen (последняя)
    const kids = bar.querySelectorAll('.ac-vp-btn');
    const last = kids[kids.length - 1];
    if(last) bar.insertBefore(btn, last);
    else bar.appendChild(btn);
    // применяем к видео
    apdApplySpeed(v);
  }
  function apdFmtSpeed(v){ return (v % 1 === 0 ? v.toFixed(0) : v.toFixed(2).replace(/0$/,'')) + '×'; }
  function apdSpeedCycle(btn){
    const cur = apdReadSpeed();
    const i = APD_SPEEDS.indexOf(cur);
    const nx = APD_SPEEDS[(i+1) % APD_SPEEDS.length];
    apdSaveSpeed(nx);
    if(btn) btn.textContent = apdFmtSpeed(nx);
    apdApplySpeed(nx);
    toast('Скорость · ' + apdFmtSpeed(nx));
  }
  function apdApplySpeed(v){
    try{ const vid = document.getElementById('acVpVideo'); if(vid) vid.playbackRate = v; }catch(e){}
  }

  /* =============================================================
     5. СЕРТИФИКАТ RU/EN: переключатель в full-overlay
     ============================================================= */
  window.acdCertLang = 'ru';
  const APD_CERT_I18N = {
    ru: {academy:'А К А Д Е М И Я   O K O', title:'СЕРТИФИКАТ',
         confirms:'подтверждает, что', passed:'успешно прошёл направление',
         courseOf:'курс «', courseOfEnd:'» Академии ХЛБ',
         result:'Результат теста: ', dateLbl:'ДАТА ВЫДАЧИ', numLbl:'НОМЕР',
         sign:'/ Артём Бриус /', signSub:'подпись руководителя Академии',
         officialDoc:'ОФИЦИАЛЬНЫЙ ДОКУМЕНТ'},
    en: {academy:'O K O   A C A D E M Y', title:'CERTIFICATE',
         confirms:'this is to certify that', passed:'has successfully completed the track',
         courseOf:'course "', courseOfEnd:'" of ХЛБ Academy',
         result:'Test score: ', dateLbl:'ISSUE DATE', numLbl:'NUMBER',
         sign:'/ ХЛБ APP Team /', signSub:'Academy director',
         officialDoc:'OFFICIAL DOCUMENT'}
  };
  // chain-patch acMakeCert — переопределяем текстовые константы во время генерации
  const _apdPrevMakeCert = window.acMakeCert;
  window.acMakeCert = function(cert, cb){
    const lang = acdCertLang || 'ru';
    // Русский: не трогаем оригинал вообще
    if(lang === 'ru') return _apdPrevMakeCert(cert, cb);
    // Английский: делаем свою copy подмены глифов + переводов
    apdMakeCertEN(cert, cb);
  };
  function apdMakeCertEN(cert, cb){
    // отдельный рендер для EN — минимальная переделка ru-версии
    if(typeof SEAL_REQ === 'undefined'){ return _apdPrevMakeCert(cert, cb); }
    const ready = (document.fonts && document.fonts.load)
      ? Promise.all([document.fonts.load('100px "Bebas Neue"'), document.fonts.load('700 30px Montserrat')]).catch(()=>{})
      : Promise.resolve();
    ready.then(()=>{
      // используем acSigImage/acDrawSeal/acRingText из academy — они в глобальной области
      const doDraw = (sig)=>{
        const t = APD_CERT_I18N.en;
        const W = 1600, H = 1131;
        const cv = document.createElement('canvas');
        cv.width = W; cv.height = H;
        const ctx = cv.getContext('2d');
        const lime = '#9AFF00';
        ctx.fillStyle = '#0a0a0a'; ctx.fillRect(0,0,W,H);
        ctx.strokeStyle = 'rgba(154,255,0,.05)'; ctx.lineWidth = 1;
        for(let x=0;x<=W;x+=64){ ctx.beginPath(); ctx.moveTo(x,0); ctx.lineTo(x,H); ctx.stroke(); }
        for(let y=0;y<=H;y+=64){ ctx.beginPath(); ctx.moveTo(0,y); ctx.lineTo(W,y); ctx.stroke(); }
        const g = ctx.createRadialGradient(W-220,180,40,W-220,180,560);
        g.addColorStop(0,'rgba(154,255,0,.10)'); g.addColorStop(1,'rgba(154,255,0,0)');
        ctx.fillStyle = g; ctx.fillRect(0,0,W,H);
        ctx.strokeStyle = lime; ctx.lineWidth = 5; ctx.strokeRect(38,38,W-76,H-76);
        ctx.lineWidth = 1.5; ctx.globalAlpha = .65; ctx.strokeRect(58,58,W-116,H-116); ctx.globalAlpha = 1;
        ctx.lineWidth = 5;
        [[38,38,1,1],[W-38,38,-1,1],[38,H-38,1,-1],[W-38,H-38,-1,-1]].forEach(([x,y,dx,dy])=>{
          ctx.beginPath(); ctx.moveTo(x+dx*44,y); ctx.lineTo(x,y); ctx.lineTo(x,y+dy*44); ctx.stroke();
        });
        try{ ctx.letterSpacing = '6px'; }catch(e){}
        ctx.textAlign = 'center';
        ctx.fillStyle = 'rgba(255,255,255,.55)';
        ctx.font = '42px "Bebas Neue", Impact, sans-serif';
        ctx.fillText(t.academy, W/2, 148);
        ctx.fillStyle = lime;
        ctx.shadowColor = 'rgba(154,255,0,.45)'; ctx.shadowBlur = 34;
        ctx.font = '150px "Bebas Neue", Impact, sans-serif';
        ctx.fillText(t.title, W/2, 300);
        ctx.shadowBlur = 0;
        try{ ctx.letterSpacing = '2px'; }catch(e){}
        ctx.fillStyle = 'rgba(255,255,255,.6)';
        ctx.font = '500 27px Montserrat, Arial';
        ctx.fillText(t.confirms, W/2, 372);
        ctx.fillStyle = '#fff';
        ctx.font = '96px "Bebas Neue", Impact, sans-serif';
        ctx.fillText(apdTransliterate(cert.name).toUpperCase(), W/2, 486);
        ctx.strokeStyle = 'rgba(154,255,0,.5)'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(W/2-260,512); ctx.lineTo(W/2+260,512); ctx.stroke();
        const courseTitle = apdTranslateTrack(cert.courseTitle || 'ХЛБ Academy');
        ctx.fillStyle = 'rgba(255,255,255,.6)';
        ctx.font = '500 26px Montserrat, Arial';
        ctx.fillText(t.passed, W/2, 566);
        ctx.fillStyle = lime;
        let fs = 64;
        ctx.font = fs + 'px "Bebas Neue", Impact, sans-serif';
        const trackLine = '"' + courseTitle.toUpperCase() + '"';
        while(fs > 40 && ctx.measureText(trackLine).width > W-260){ fs -= 4; ctx.font = fs + 'px "Bebas Neue", Impact, sans-serif'; }
        ctx.fillText(trackLine, W/2, 646);
        ctx.fillStyle = 'rgba(255,255,255,.6)';
        ctx.font = '500 24px Montserrat, Arial';
        ctx.fillText(t.courseOfEnd.replace(/^»/,'').replace('« ','').trim(), W/2, 696);
        const chipT = t.result + cert.score + '%';
        ctx.font = '700 26px Montserrat, Arial';
        const cw = ctx.measureText(chipT).width + 66;
        ctx.fillStyle = 'rgba(154,255,0,.13)';
        ctx.beginPath();
        if(ctx.roundRect) ctx.roundRect(W/2-cw/2,730,cw,58,29); else ctx.rect(W/2-cw/2,730,cw,58);
        ctx.fill();
        ctx.strokeStyle = lime; ctx.lineWidth = 1.6; ctx.stroke();
        ctx.fillStyle = lime;
        ctx.fillText(chipT, W/2, 768);
        ctx.textAlign = 'left';
        ctx.fillStyle = 'rgba(255,255,255,.45)';
        ctx.font = '600 19px Montserrat, Arial';
        ctx.fillText(t.dateLbl, 120, 878);
        ctx.fillStyle = '#fff';
        ctx.font = '46px "Bebas Neue", Impact, sans-serif';
        const dateEn = apdDateEn(cert.date);
        ctx.fillText(dateEn, 120, 928);
        ctx.fillStyle = 'rgba(255,255,255,.45)';
        ctx.font = '600 19px Montserrat, Arial';
        ctx.fillText(t.numLbl, 120, 972);
        ctx.fillStyle = lime;
        ctx.font = '700 26px Montserrat, Arial';
        ctx.fillText('No ' + cert.no, 120, 1004);
        const sx1=560, sx2=880, sy=952;
        ctx.strokeStyle = 'rgba(255,255,255,.55)'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(sx1,sy); ctx.lineTo(sx2,sy); ctx.stroke();
        if(sig){
          const sw = 300, sh = sw * (sig.height / sig.width);
          ctx.drawImage(sig, (sx1+sx2)/2 - sw/2, sy - sh*0.82, sw, sh);
        }
        ctx.fillStyle = '#fff';
        ctx.font = '600 24px Montserrat, Arial';
        ctx.fillText(t.sign, sx2 + 18, sy + 8);
        ctx.fillStyle = 'rgba(255,255,255,.4)';
        ctx.font = '500 16px Montserrat, Arial';
        ctx.fillText(t.signSub, sx1, sy + 32);
        // печать оставляем на русском (это официальный реквизит)
        if(typeof acDrawSeal === 'function') acDrawSeal(ctx, 1350, 900, 138);
        ctx.textAlign = 'center';
        ctx.fillStyle = 'rgba(255,255,255,.34)';
        ctx.font = '500 15px Montserrat, Arial';
        ctx.fillText(SEAL_REQ.fio + ' · ' + SEAL_REQ.inn + ' · ' + SEAL_REQ.brand + ' · hlbapp.ru@gmail.com', W/2, 1076);
        cb(cv.toDataURL('image/png'));
      };
      if(typeof acSigImage === 'function') acSigImage(doDraw);
      else doDraw(null);
    });
  }
  // Транслитерация имени RU→LAT
  function apdTransliterate(s){
    const M = {А:'A',Б:'B',В:'V',Г:'G',Д:'D',Е:'E',Ё:'Yo',Ж:'Zh',З:'Z',И:'I',Й:'Y',К:'K',Л:'L',М:'M',Н:'N',О:'O',П:'P',Р:'R',С:'S',Т:'T',У:'U',Ф:'F',Х:'Kh',Ц:'Ts',Ч:'Ch',Ш:'Sh',Щ:'Sch',Ъ:'',Ы:'Y',Ь:'',Э:'E',Ю:'Yu',Я:'Ya',
               а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'yo',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'sch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya'};
    return String(s||'').split('').map(ch=>M[ch]!==undefined?M[ch]:ch).join('');
  }
  // Переводим названия направлений (те три, что заведены в академии)
  function apdTranslateTrack(t){
    const M = {'Медийность':'Media Presence','Маркетинг':'Marketing','Нейросети':'Neural Networks'};
    return M[t] || apdTransliterate(t);
  }
  function apdDateEn(ru){
    // Ру-дата DD.MM.YYYY → "Mon D, YYYY"
    const m = String(ru||'').match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);
    if(!m) return ru;
    const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return months[parseInt(m[2],10)-1] + ' ' + parseInt(m[1],10) + ', ' + m[3];
  }
  // Инъекция переключателя в fullscreen-overlay
  function apdInjectCertLangSwitch(){
    const full = document.getElementById('acCertFull');
    if(!full || full.querySelector('.acd-cert-lang')) return;
    const sw = document.createElement('div');
    sw.className = 'acd-cert-lang';
    sw.innerHTML = `
      <button class="on" data-l="ru" onclick="apdCertLangSet('ru')">RU</button>
      <button data-l="en" onclick="apdCertLangSet('en')">EN</button>`;
    full.appendChild(sw);
  }
  window.apdCertLangSet = function(lang){
    if(lang !== 'ru' && lang !== 'en') return;
    if(window.acdCertLang === lang) return;
    window.acdCertLang = lang;
    document.querySelectorAll('.acd-cert-lang button').forEach(b=>{
      b.classList.toggle('on', b.getAttribute('data-l') === lang);
    });
    // Перегенерируем текущий сертификат
    try{
      window.acCertUrl = null;
      const rec = (typeof acCertRec === 'function') ? acCertRec() : null;
      if(!rec) return;
      const img = document.getElementById('acCertFullImg');
      if(!img) return;
      // спиннер визуальный
      img.style.opacity = '.45';
      acMakeCert(rec, url=>{
        window.acCertUrl = url;
        window.acCertShownNo = rec.no;
        img.src = url;
        img.style.opacity = '1';
      });
    }catch(e){}
  };

  /* =============================================================
     ХУК: chain-patch acRender — после базового render'а
     запускаем все свои пост-обработки под текущий acView
     ============================================================= */
  const _apdPrevRender = window.acRender;
  window.acRender = function(){
    apdRemoveLessonExtras();
    try{ _apdPrevRender.apply(this, arguments); }catch(e){}
    try{
      if(acView === 'home'){
        apdInjectCatalogFilters();
        apdInjectCatalogButton();
      } else if(acView === 'course'){
        apdSetupCollapsibleBlocks();
        // Кнопка «Админ-панель курса» для владельца
        try{ apdInjectAdminBtnOnCourse(); }catch(e){}
      } else if(acView === 'lesson'){
        apdInjectLessonExtras();
        apdLessonExtraFormats();
        // Отложенная инъекция скорости — плеер может ре-рендериться асинхронно
        setTimeout(apdInjectSpeed, 20);
        setTimeout(apdInjectSpeed, 400);
      }
    }catch(e){}
  };
  function apdInjectAdminBtnOnCourse(){
    if(!apdIsOwner()) return;
    const root = document.getElementById('acRoot');
    if(!root || root.querySelector('#apdAdminBtnCourse')) return;
    const insideCard = root.querySelector('.ac-inside');
    if(!insideCard) return;
    const ci = (typeof acCourse === 'number') ? acCourse : 0;
    const btn = document.createElement('button');
    btn.id = 'apdAdminBtnCourse';
    btn.className = 'acd-admin-btn';
    btn.innerHTML = `${I('crown')}<span class="tx">Админ-панель курса</span><span class="go">${I('chev')}</span>`;
    btn.onclick = ()=>apdAdminOpen(ci);
    insideCard.parentNode.insertBefore(btn, insideCard.nextSibling);
  }
  // chain-patch: acRenderVideoBox тоже перерисовывает бар — переинжектим скорость
  if(typeof acRenderVideoBox === 'function'){
    const _apdPrevRVB = window.acRenderVideoBox;
    window.acRenderVideoBox = function(){
      try{ _apdPrevRVB.apply(this, arguments); }catch(e){}
      setTimeout(apdInjectSpeed, 20);
    };
  }

  /* =============================================================
     Проверка контента шагов после действий (chain-patch поменял acAfterCheckpoint;
     дополнительно ре-рендерим ступени при заметных внутренних изменениях)
     ============================================================= */
  ['acRenderTestBox','acRenderTaskBox','acRenderGameBox','acRenderProgressBox','acRenderCertBox']
    .forEach(fn=>{
      if(typeof window[fn] !== 'function') return;
      const prev = window[fn];
      window[fn] = function(){
        try{ prev.apply(this, arguments); }catch(e){}
        apdRerenderStepRail();
      };
    });

  /* =============================================================
     Overlay сертификата: инъекция RU/EN — как только он появится
     ============================================================= */
  function apdWatchCertOverlay(){
    const target = document.getElementById('acCertFull');
    if(!target) return;
    // при каждом открытии — обновляем свитч
    const obs = new MutationObserver(()=>{
      if(target.classList.contains('open')) apdInjectCertLangSwitch();
    });
    try{ obs.observe(target, {attributes:true, attributeFilter:['class']}); }catch(e){}
    apdInjectCertLangSwitch();
  }

  /* =============================================================
     ==================== НОВОЕ (29.07 Артём) ====================
     Каталог курсов ХЛБ (fullscreen), карточка курса,
     Админ-панель, PDF сертификата, доп.форматы, мои курсы.
     ============================================================= */

  /* -------- утилиты -------- */
  function apdIsOwner(){
    try{ return typeof isOwner === 'function' ? isOwner() : (window.PROFILE && PROFILE.role === 'owner'); }
    catch(e){ return false; }
  }
  function apdFmtDur(mins){
    const h = Math.floor(mins/60), m = Math.round(mins%60);
    return h ? (h + ' ч ' + (m ? m + ' мин' : '').trim()).trim() : (m + ' мин');
  }
  function apdDeterministicRnd(seed){
    // маленький xorshift для стабильных «отзывов/рейтингов» по индексу курса
    let s = (seed*2654435761) >>> 0;
    return ()=>{ s ^= s<<13; s ^= s>>>17; s ^= s<<5; return ((s >>> 0) % 1000) / 1000; };
  }
  function apdCourseMeta(ci){
    // синтетические, но стабильные данные (звёзды/учеников/уровень/длительность)
    const c = AC_COURSES[ci];
    const st = (typeof acCourseStats==='function') ? acCourseStats(ci) : {lessons:c.count, mins:c.count*8};
    const rnd = apdDeterministicRnd(ci+1);
    const rating = (4.4 + rnd()*0.55);
    const students = 120 + Math.floor(rnd()*1180);
    const level = ['Начинающий','Средний','Про'][Math.floor(rnd()*3)];
    return {rating, ratingTxt: rating.toFixed(2).replace('.',','), students, level, mins:st.mins, lessons:st.lessons, slides:st.slides};
  }
  function apdCourseReviews(ci){
    // фиксированные отзывы под каждый курс (детерминированно)
    const c = AC_COURSES[ci];
    const rnd = apdDeterministicRnd(ci+7);
    const names = ['Анна','Дмитрий','Ольга','Илья','Марина','Кирилл','София','Егор','Полина','Роман'];
    const templates = [
      'Практика на реальных задачах, никакой воды. Автор говорит по делу и подкрепляет цифрами.',
      'После курса собрал первый рабочий пайплайн за вечер — то, чего год откладывал.',
      'Круто, что каждый урок с тестом и мини-игрой — материал реально закрепляется.',
      'Заходил как новичок, вышел с чёткой системой. Лучший курс по теме за все деньги.',
      'Понравился формат: короткие уроки, живой ритм, много инструментов и разборов.',
      'Сертификат в конце — приятный бонус, но польза не в бумажке, а в новом навыке.'
    ];
    const n = 3 + Math.floor(rnd()*3);
    const out = [];
    const dt = ['сегодня','вчера','2 дня назад','неделю назад','2 недели назад','месяц назад'];
    for(let i=0; i<n; i++){
      out.push({
        name: names[Math.floor(rnd()*names.length)],
        text: templates[Math.floor(rnd()*templates.length)],
        stars: 4 + (rnd() > 0.35 ? 1 : 0),
        when: dt[Math.floor(rnd()*dt.length)]
      });
      // добавляем пользовательские отзывы
    }
    try{
      const my = (acS.acdReviews||{})[c.id] || [];
      return my.concat(out);
    }catch(e){ return out; }
  }
  function apdStarsSvg(n){
    let s = '';
    for(let i=0; i<5; i++) s += I('star');
    return `<span class="stars">${I('star')} ${n.toFixed(1).replace('.',',')}</span>`;
  }
  function apdEnsureStore2(){
    if(!acS.acdReviews) acS.acdReviews = {};   // {courseId: [{name,text,stars,when}]}
    if(!acS.acdBanned) acS.acdBanned = {};     // {courseId: {nick:true}}
    if(!acS.acdSettings) acS.acdSettings = {}; // {courseId: {price,discount,autonext,certOn,available}}
  }
  apdEnsureStore2();
  function apdGetSettings(ci){
    apdEnsureStore2();
    const c = AC_COURSES[ci];
    const def = {price:c.price||0, discount:0, autonext:true, certOn:true, available:true};
    return Object.assign({}, def, acS.acdSettings[c.id]||{});
  }
  function apdSetSetting(ci, k, v){
    apdEnsureStore2();
    const c = AC_COURSES[ci];
    const cur = apdGetSettings(ci);
    cur[k] = v;
    acS.acdSettings[c.id] = cur;
    acSave();
  }

  /* -------- fullscreen host -------- */
  function apdFullEnsure(){
    let f = document.getElementById('apdFull');
    if(f) return f;
    f = document.createElement('div');
    f.id = 'apdFull';
    f.className = 'acd-full';
    document.body.appendChild(f);
    return f;
  }
  window.apdFullClose = function(){
    const f = document.getElementById('apdFull');
    if(f){ f.classList.remove('open'); setTimeout(()=>{ f.innerHTML=''; }, 260); }
    try{ if(typeof nvPop === 'function') nvPop('acdFull'); }catch(e){}
  };
  function apdFullOpen(titleObj, bodyHtml){
    const f = apdFullEnsure();
    f.innerHTML = `
      <div class="acd-full-top">
        <button class="acd-full-close" onclick="apdFullClose()" aria-label="Закрыть">${I('plus')}</button>
        <div class="acd-full-title"><b>${esc(titleObj.title||'')}</b><span>${esc(titleObj.sub||'')}</span></div>
        ${titleObj.rightBtn||''}
      </div>
      <div class="acd-full-body" id="apdFullBody">${bodyHtml}</div>`;
    requestAnimationFrame(()=>f.classList.add('open'));
    // регистрация в navstack (кнопка Назад TG/браузера/Escape закроют слой)
    try{ if(typeof nvPush === 'function') nvPush('acdFull', ()=>{
      const el = document.getElementById('apdFull');
      if(el){ el.classList.remove('open'); setTimeout(()=>{ el.innerHTML=''; }, 260); }
    }); }catch(e){}
  }
  function apdFullSetBody(html){
    const b = document.getElementById('apdFullBody');
    if(b) b.innerHTML = html;
  }

  /* =============================================================
     1) КАТАЛОГ КУРСОВ ХЛБ — полноэкранная страница
     ============================================================= */
  window.APD_CAT_STATE = {
    q:'', sort:'new',
    dir:'', fmt:'', level:'', author:'', dur:''
  };
  const APD_DIR_OPTS   = ['Медийность','Маркетинг','Нейросети','Дизайн','Финансы'];
  const APD_FMT_OPTS   = ['Бесплатно','Платно','Клубный'];
  const APD_LEVEL_OPTS = ['Начинающий','Средний','Про'];
  const APD_DUR_OPTS   = ['до 1 ч','1–3 ч','3+ ч'];
  const APD_SORT_OPTS  = [
    {k:'new',    lbl:'Новые'},
    {k:'rating', lbl:'Рейтинг'},
    {k:'cheap',  lbl:'Дешевле'},
    {k:'exp',    lbl:'Дороже'},
    {k:'stud',   lbl:'Популярные'}
  ];

  function apdCourseAuthors(){
    const seen = new Set(), out = [];
    AC_COURSES.forEach(c=>{ const a = c.author || '—'; if(!seen.has(a)){ seen.add(a); out.push(a); } });
    return out;
  }
  function apdCourseDir(c){ return c.title; }
  function apdCourseFmt(ci){
    const c = AC_COURSES[ci];
    if(c.free) return 'Бесплатно';
    // клубный = входит в MAX
    if(c.minTier === 'MAX') return 'Клубный';
    return 'Платно';
  }
  function apdCourseDur(ci){
    const m = apdCourseMeta(ci).mins;
    if(m <= 60) return 'до 1 ч';
    if(m <= 180) return '1–3 ч';
    return '3+ ч';
  }
  function apdCourseMatches(ci, S){
    const c = AC_COURSES[ci];
    const meta = apdCourseMeta(ci);
    const q = (S.q||'').trim().toLowerCase();
    if(q){
      const hay = ((c.title||'') + ' ' + (c.sub||'') + ' ' + (c.author||'') + ' ' + (c.outcomes||[]).join(' ')).toLowerCase();
      if(!hay.includes(q)) return false;
    }
    if(S.dir && apdCourseDir(c) !== S.dir) return false;
    if(S.fmt && apdCourseFmt(ci) !== S.fmt) return false;
    if(S.level && meta.level !== S.level) return false;
    if(S.author && (c.author||'') !== S.author) return false;
    if(S.dur && apdCourseDur(ci) !== S.dur) return false;
    return true;
  }
  function apdSortCourses(list, sort){
    const withMeta = list.map(ci=>({ci, c:AC_COURSES[ci], m:apdCourseMeta(ci)}));
    switch(sort){
      case 'rating': withMeta.sort((a,b)=>b.m.rating - a.m.rating); break;
      case 'cheap':  withMeta.sort((a,b)=>(a.c.price||0) - (b.c.price||0)); break;
      case 'exp':    withMeta.sort((a,b)=>(b.c.price||0) - (a.c.price||0)); break;
      case 'stud':   withMeta.sort((a,b)=>b.m.students - a.m.students); break;
      default: /* новые = порядок из AC_COURSES */ break;
    }
    return withMeta.map(x=>x.ci);
  }
  function apdCatalogCardHtml(ci){
    const c = AC_COURSES[ci];
    const acc = acCourseAccessible(ci);
    const pct = acCoursePctOf(ci);
    const meta = apdCourseMeta(ci);
    const fmt = apdCourseFmt(ci);
    const tagCls = c.free ? 'free' : (fmt === 'Клубный' ? 'club' : '');
    const priceTxt = c.free ? 'Бесплатно' : acFmtPrice(c.price);
    return `<button class="acd-cat-card ${acc?'':'locked'}" onclick="apdCourseFullOpen(${ci})">
      <div class="acd-cat-card-cov">
        ${acCourseCover(ci, true)}
        <span class="acd-cat-card-tag ${tagCls}">${esc(fmt)}</span>
        ${pct>0 ? `<span class="acd-cat-card-pct"><i style="width:${pct}%"></i></span>` : ''}
      </div>
      <div class="acd-cat-card-body">
        <h4>${esc(c.title)}</h4>
        <span class="acd-cat-card-auth">${esc(c.author||'—')}</span>
        <div class="acd-cat-card-meta">
          <span class="stars">${I('star')} ${meta.ratingTxt}</span>
          <span class="stud">${meta.students.toLocaleString('ru-RU')} учеников</span>
        </div>
        <div class="acd-cat-card-price ${c.free?'free':''}">${priceTxt}</div>
      </div>
    </button>`;
  }
  function apdCatalogFiltersHtml(){
    const S = APD_CAT_STATE;
    // val — обычная строка (заголовок фильтра). Экранируем и для HTML-атрибута, и для JS-строки.
    const esq = v => String(v||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    const chip = (key, val, cur)=>`<button class="acd-fchip ${cur===val?'on':''}" onclick="apdCatSet('${key}','${esq(val)}')"><span>${esc(val)}</span></button>`;
    const dirs = AC_COURSES.map(c=>c.title);
    const authors = apdCourseAuthors();
    return `
      <div class="acd-fgroup"><div class="acd-fgroup-h">Направление</div>
        <div class="acd-fgroup-chips">
          <button class="acd-fchip ${!S.dir?'on':''}" onclick="apdCatSet('dir','')"><span>Все</span></button>
          ${dirs.map(d=>chip('dir', d, S.dir)).join('')}
        </div>
      </div>
      <div class="acd-fgroup"><div class="acd-fgroup-h">Формат</div>
        <div class="acd-fgroup-chips">
          <button class="acd-fchip ${!S.fmt?'on':''}" onclick="apdCatSet('fmt','')"><span>Все</span></button>
          ${APD_FMT_OPTS.map(v=>chip('fmt', v, S.fmt)).join('')}
        </div>
      </div>
      <div class="acd-fgroup"><div class="acd-fgroup-h">Уровень</div>
        <div class="acd-fgroup-chips">
          <button class="acd-fchip ${!S.level?'on':''}" onclick="apdCatSet('level','')"><span>Все</span></button>
          ${APD_LEVEL_OPTS.map(v=>chip('level', v, S.level)).join('')}
        </div>
      </div>
      <div class="acd-fgroup"><div class="acd-fgroup-h">Автор</div>
        <div class="acd-fgroup-chips">
          <button class="acd-fchip ${!S.author?'on':''}" onclick="apdCatSet('author','')"><span>Все</span></button>
          ${authors.map(v=>chip('author', v, S.author)).join('')}
        </div>
      </div>
      <div class="acd-fgroup"><div class="acd-fgroup-h">Длительность</div>
        <div class="acd-fgroup-chips">
          <button class="acd-fchip ${!S.dur?'on':''}" onclick="apdCatSet('dur','')"><span>Все</span></button>
          ${APD_DUR_OPTS.map(v=>chip('dur', v, S.dur)).join('')}
        </div>
      </div>`;
  }
  function apdCatalogListHtml(){
    const S = APD_CAT_STATE;
    let ids = [];
    for(let ci=0; ci<AC_COURSES.length; ci++) if(apdCourseMatches(ci, S)) ids.push(ci);
    ids = apdSortCourses(ids, S.sort);
    const hasFilter = S.q || S.dir || S.fmt || S.level || S.author || S.dur;
    const summary = `<div class="acd-cat-summary">
      <span>Найдено <b>${ids.length}</b> ${apdPlural(ids.length,['курс','курса','курсов'])}</span>
      ${hasFilter ? `<span class="clr" onclick="apdCatReset()">Сбросить фильтры</span>` : ''}
    </div>`;
    if(!ids.length){
      return summary + `<div class="acd-cat-empty">${I('search')}<div>Курсы по этим фильтрам не найдены.<br>Попробуй сбросить какие-то условия.</div></div>`;
    }
    return summary + `<div class="acd-cat-grid">${ids.map(apdCatalogCardHtml).join('')}</div>`;
  }
  function apdCatalogBodyHtml(){
    const S = APD_CAT_STATE;
    return `
      <div class="acd-cat-search">
        <input type="text" class="acd-cat-input" id="apdCatQ" placeholder="Поиск курса, автора, темы…" value="${esc(S.q||'')}" oninput="apdCatSetQ(this.value)">
        <select class="acd-cat-sort" onchange="apdCatSet('sort',this.value)">
          ${APD_SORT_OPTS.map(o=>`<option value="${o.k}" ${S.sort===o.k?'selected':''}>${esc(o.lbl)}</option>`).join('')}
        </select>
      </div>
      ${apdCatalogFiltersHtml()}
      <div id="apdCatList">${apdCatalogListHtml()}</div>`;
  }
  window.apdCatalogOpen = function(){
    apdFullOpen({title:'Все курсы Академии', sub:AC_COURSES.length + ' ' + apdPlural(AC_COURSES.length,['курс','курса','курсов']) + ' · фильтры и поиск'}, apdCatalogBodyHtml());
  };
  window.apdCatSet = function(key, val){
    APD_CAT_STATE[key] = val;
    apdCatalogRefreshFull();
  };
  let _apdCatSetQTimer = null;
  window.apdCatSetQ = function(v){
    APD_CAT_STATE.q = v;
    clearTimeout(_apdCatSetQTimer);
    _apdCatSetQTimer = setTimeout(()=>{
      const list = document.getElementById('apdCatList');
      if(list) list.innerHTML = apdCatalogListHtml();
    }, 180);
  };
  window.apdCatReset = function(){
    APD_CAT_STATE = {q:'', sort:APD_CAT_STATE.sort, dir:'', fmt:'', level:'', author:'', dur:''};
    apdCatalogRefreshFull();
  };
  function apdCatalogRefreshFull(){
    apdFullSetBody(apdCatalogBodyHtml());
  }

  /* Инъекция кнопки «Все курсы Академии» + «Мои курсы» на главной */
  function apdInjectCatalogButton(){
    if(acView !== 'home') return;
    const root = document.getElementById('acRoot');
    if(!root || root.querySelector('#apdCatBtn')) return;
    const cat = root.querySelector('.ac-catalog');
    if(!cat) return;
    // 1) Кнопка перед h2 «Каталог»
    const h = cat.previousElementSibling; // section-h
    const total = AC_COURSES.length;
    const btn = document.createElement('button');
    btn.id = 'apdCatBtn';
    btn.className = 'acd-cat-btn';
    btn.onclick = ()=>apdCatalogOpen();
    btn.innerHTML = `
      <span class="ic">${I('search')}</span>
      <span class="tx"><b>Все курсы Академии</b><span>Фильтры, поиск, сортировка · ${total} ${apdPlural(total,['курс','курса','курсов'])}</span></span>
      ${I('chev')}`;
    if(h && h.tagName === 'H2') h.parentNode.insertBefore(btn, h);
    else cat.parentNode.insertBefore(btn, cat);

    // 2) Секция «Мои курсы» под каталогом (только начатые/пройденные)
    if(!root.querySelector('#apdMyCourses')){
      const myHtml = apdMyCoursesHtml();
      if(myHtml){
        const wrap = document.createElement('div');
        wrap.id = 'apdMyCoursesWrap';
        wrap.innerHTML = `<h2 class="section-h" style="margin:24px 0 10px;font-size:21px">Мои курсы</h2>
          <div class="card" id="apdMyCourses" style="padding:8px 10px">${myHtml}</div>`;
        // вставляем после блока каталога
        cat.parentNode.insertBefore(wrap, cat.nextSibling);
      }
    }
  }

  function apdMyCoursesHtml(){
    const my = [];
    for(let ci=0; ci<AC_COURSES.length; ci++){
      const p = acCoursePctOf(ci);
      if(p > 0) my.push({ci, p, done:acCourseDone(ci)});
    }
    if(!my.length){
      return `<div class="acd-my-empty">Ты ещё не начал ни одного курса. Открой «Все курсы Академии» и выбери свой.</div>`;
    }
    // сортировка: в процессе → пройденные
    my.sort((a,b)=>(+a.done - +b.done) || (b.p - a.p));
    return `<div class="acd-my">${my.map(m=>{
      const c = AC_COURSES[m.ci];
      const meta = apdCourseMeta(m.ci);
      const st = m.done ? 'Пройден' : ('В процессе · ' + meta.lessons + ' ' + apdPlural(meta.lessons,['урок','урока','уроков']));
      return `<button class="acd-my-item" onclick="apdCourseFullOpen(${m.ci})">
        <span class="cov">${acCourseCover(m.ci, true)}</span>
        <span class="m">
          <b>${esc(c.title)}</b>
          <span>${esc(st)}</span>
          <span class="bar"><i style="width:${m.p}%"></i></span>
        </span>
        <span class="pct">${m.p}%</span>
      </button>`;
    }).join('')}</div>`;
  }

  /* =============================================================
     2) ПОЛНОСТРАНИЧНАЯ КАРТОЧКА КУРСА (описание, автор, отзывы)
     ============================================================= */
  window.apdCourseFullOpen = function(ci){
    ci = +ci;
    apdFullOpen({title: AC_COURSES[ci].title, sub: AC_COURSES[ci].sub}, apdCourseFullBody(ci));
  };
  function apdCourseFullBody(ci){
    const c = AC_COURSES[ci];
    const acc = acCourseAccessible(ci);
    const done = acCourseDone(ci);
    const pct = acCoursePctOf(ci);
    const meta = apdCourseMeta(ci);
    const stgs = apdGetSettings(ci);
    const reviews = apdCourseReviews(ci);
    const avgStars = (reviews.reduce((s,r)=>s+(r.stars||5),0) / Math.max(1,reviews.length));
    const owner = apdIsOwner();
    const priceEff = stgs.discount > 0 ? Math.round(stgs.price * (100-stgs.discount)/100) : stgs.price;
    const priceTxt = c.free ? 'Бесплатно' : acFmtPrice(priceEff);
    const oldPrice = (!c.free && stgs.discount > 0) ? `<span style="text-decoration:line-through;color:var(--dim);font-family:var(--font-body);font-size:13px;font-weight:600;margin-left:8px">${acFmtPrice(stgs.price)}</span>` : '';

    const cta = acc
      ? `<button class="btn" onclick="apdCourseCTAContinue(${ci})">${I(done?'star':'play')} ${done?'Открыть заново':(pct>0?'Продолжить курс':'Начать курс')}</button>`
      : `<button class="btn" onclick="apdFullClose();acCourseGate(${ci})">${I('lock')} Купить · ${priceTxt}${oldPrice}</button>`;

    const outcomes = (c.outcomes||[]).map(o=>`<li>${I('check2')}<span>${esc(o)}</span></li>`).join('');

    const authorInitial = ((c.author||'?').trim().charAt(0) || '?').toUpperCase();

    // Программа курса
    const blocks = acCourseBlocks(ci);
    let ln = 0;
    const program = blocks.map((b,bi)=>{
      const bIdx = []; for(let i=b.from;i<b.from+b.count;i++) bIdx.push(i);
      const lessons = bIdx.map(i=>{
        ln++;
        const L = AC_COURSE[i];
        const p = acLessonPct(i);
        return `<div class="acd-lesson-item">
          <span class="n">${ln}</span>
          <span class="m"><b>${esc(L.title)}</b><span>${esc(acLessonSub(L))}${p>0?' · '+p+'%':''}</span></span>
        </div>`;
      }).join('');
      return `<div style="margin-bottom:10px">
        <div class="acd-fgroup-h" style="margin-bottom:6px">Блок ${bi+1} · ${esc(b.title)}</div>
        ${lessons || `<div class="acd-cat-empty" style="padding:14px">Уроки готовятся</div>`}
      </div>`;
    }).join('');

    // Отзывы
    const revHtml = reviews.map(r=>{
      const stars = '★'.repeat(r.stars||5) + '☆'.repeat(5-(r.stars||5));
      return `<div class="acd-cp-review">
        <div class="acd-cp-review-h">
          <span class="ava">${esc((r.name||'?').charAt(0).toUpperCase())}</span>
          <b>${esc(r.name||'Гость')}</b>
          <span class="stars">${stars}</span>
          <span class="ts">${esc(r.when||'')}</span>
        </div>
        <p>${esc(r.text)}</p>
      </div>`;
    }).join('');

    // Форматы: собираем факты из уроков
    const formats = apdCourseFormats(ci);
    const fmtChips = formats.map(f=>`<span class="acd-cp-fmt-chip">${I(f.ic)}${esc(f.lbl)}</span>`).join('');

    return `
      <div class="acd-cp-hero">
        ${acCourseCover(ci, true)}
        <div class="acd-cp-hero-cap">
          <span class="chip">${c.free?'Бесплатный курс':(stgs.available?'Премиум':'Скоро')}</span>
          <h2>${esc(c.title)}</h2>
          <p>${esc(c.sub)}</p>
        </div>
      </div>

      ${owner ? `<button class="acd-admin-btn" onclick="apdAdminOpen(${ci})">${I('crown')}<span class="tx">Админ-панель курса · настройки, участники, аналитика</span><span class="go">${I('chev')}</span></button>` : ''}

      <div class="acd-cp-fmt">${fmtChips}</div>

      <div class="acd-cp-stats">
        <div class="acd-cp-stat"><span class="ic">${I('star')}</span><div class="m"><b>${avgStars.toFixed(1).replace('.',',')}</b><span>${reviews.length} ${apdPlural(reviews.length,['отзыв','отзыва','отзывов'])}</span></div></div>
        <div class="acd-cp-stat"><span class="ic">${I('users')}</span><div class="m"><b>${meta.students.toLocaleString('ru-RU')}</b><span>учеников</span></div></div>
        <div class="acd-cp-stat"><span class="ic">${I('file')}</span><div class="m"><b>${meta.lessons}</b><span>${apdPlural(meta.lessons,['урок','урока','уроков'])}</span></div></div>
        <div class="acd-cp-stat"><span class="ic">${I('clock')}</span><div class="m"><b>${apdFmtDur(meta.mins)}</b><span>${esc(meta.level)}</span></div></div>
      </div>

      <div class="acd-cp-author">
        <span class="ava">${esc(authorInitial)}</span>
        <div class="m"><b>${esc(c.author||'—')}</b><span>Автор курса · практика на реальных задачах</span></div>
      </div>

      <h2 class="section-h" style="margin:16px 0 8px;font-size:18px">Чему научишься</h2>
      <div class="card" style="padding:14px">
        <ul class="acd-cp-outcomes" style="list-style:none;display:flex;flex-direction:column;gap:8px">${outcomes || '<li style="color:var(--dim);font-size:12.5px">Результаты этого курса описываются автором</li>'}</ul>
      </div>

      <h2 class="section-h" style="margin:16px 0 8px;font-size:18px">Программа</h2>
      <div class="card" style="padding:12px">${program}</div>

      <h2 class="section-h" style="margin:16px 0 8px;font-size:18px">Отзывы <span style="font-size:12px;color:var(--dim);font-weight:600">· ${reviews.length}</span></h2>
      <div class="acd-cp-reviews">${revHtml}</div>
      <button class="acd-cp-review-add" onclick="apdCourseReviewAdd(${ci})">${I('edit')} Написать отзыв</button>

      <div class="acd-cp-cta">${cta}</div>`;
  }
  window.apdCourseCTAContinue = function(ci){
    ci = +ci;
    apdFullClose();
    if(!acCourseAccessible(ci)){ acCourseGate(ci); return; }
    // если есть незавершённый урок в этом курсе — идём туда
    const idx = acCourseIdx(ci);
    const nx = idx.find(i=>acUnlocked(i) && !acLessonDone(i));
    if(nx !== undefined) acOpenLesson(nx);
    else acOpenCourse(ci);
  };
  window.apdCourseReviewAdd = function(ci){
    ci = +ci;
    if(typeof showPopup !== 'function'){ toast('Оценка недоступна'); return; }
    const c = AC_COURSES[ci];
    const me = apdMe();
    const dt = 'сегодня';
    const stars = 5;
    showPopup({
      ico:'edit', title:'Отзыв о курсе «'+c.title+'»',
      body:`<div style="text-align:left">
        <label style="font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--dim);display:block;margin-bottom:6px">Оценка</label>
        <select id="apdRevStars" style="width:100%;background:var(--raised);border:1px solid var(--border);border-radius:9px;color:var(--text);padding:9px 11px;font-size:13px;margin-bottom:10px">
          ${[5,4,3,2,1].map(n=>`<option value="${n}" ${n===5?'selected':''}>${'★'.repeat(n)}${'☆'.repeat(5-n)} — ${n} из 5</option>`).join('')}
        </select>
        <label style="font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:var(--dim);display:block;margin-bottom:6px">Отзыв</label>
        <textarea id="apdRevTxt" placeholder="Что понравилось, что вынес из курса…" style="width:100%;background:var(--raised);border:1px solid var(--border);border-radius:9px;color:var(--text);padding:9px 11px;font-size:13px;min-height:80px;resize:vertical"></textarea>
      </div>`,
      actions:[
        {label:'Опубликовать', onclick:()=>{
          const t = (document.getElementById('apdRevTxt').value||'').trim();
          const s = parseInt(document.getElementById('apdRevStars').value,10) || 5;
          if(t.length < 12){ toast('Отзыв слишком короткий'); return; }
          apdEnsureStore2();
          const arr = acS.acdReviews[c.id] || [];
          arr.unshift({name: me.name, text: t.slice(0,600), stars: s, when: dt});
          acS.acdReviews[c.id] = arr;
          acSave();
          toast('Отзыв опубликован');
          // перерисуем страницу курса, если она открыта
          const b = document.getElementById('apdFullBody');
          if(b) b.innerHTML = apdCourseFullBody(ci);
        }},
        {label:'Отмена', ghost:true}
      ]
    });
  };

  /* Форматы курса (интеллектуальная детекция + доп.форматы) */
  function apdCourseFormats(ci){
    const idx = acCourseIdx(ci);
    let hasVideo=false, hasSlides=false, hasTest=false, hasTask=false, hasGame=false, hasFiles=false, hasLive=false;
    idx.forEach(i=>{
      const L = AC_COURSE[i];
      if(L.videoUrl) hasVideo = true;
      if((L.slides||[]).length) hasSlides = true;
      if((L.quiz||[]).length) hasTest = true;
      if(L.task) hasTask = true;
      if(L.pairs && L.pairs.length) hasGame = true;
      if((L.files||[]).length) hasFiles = true;
      if(L.live) hasLive = true;
    });
    const out = [];
    if(hasVideo)  out.push({ic:'circle-play', lbl:'Видео'});
    if(hasSlides) out.push({ic:'file',        lbl:'Слайды'});
    if(hasTask)   out.push({ic:'edit',        lbl:'Практика'});
    if(hasTest)   out.push({ic:'poll',        lbl:'Тесты'});
    if(hasGame)   out.push({ic:'bolt',        lbl:'Мини-игры'});
    if(hasFiles)  out.push({ic:'file',        lbl:'Файлы'});
    if(hasLive)   out.push({ic:'megaphone',   lbl:'Livestream'});
    return out;
  }

  /* =============================================================
     3) АДМИН-ПАНЕЛЬ КУРСА (owner)
     ============================================================= */
  window.APD_ADMIN_TAB = 'analytics';
  window.APD_ADMIN_CI = 0;
  const APD_ADMIN_TABS = [
    {k:'analytics', lbl:'Аналитика',  ic:'poll'},
    {k:'lessons',   lbl:'Уроки',      ic:'file'},
    {k:'members',   lbl:'Участники',  ic:'users'},
    {k:'settings',  lbl:'Настройки',  ic:'crown'},
    {k:'moder',     lbl:'Модерация',  ic:'comment'},
    {k:'export',    lbl:'Экспорт',    ic:'share'}
  ];
  window.apdAdminOpen = function(ci){
    if(!apdIsOwner()){ toast('Только для владельца курса'); return; }
    APD_ADMIN_CI = +ci; APD_ADMIN_TAB = 'analytics';
    const c = AC_COURSES[+ci];
    apdFullOpen({title:'Админ · ' + c.title, sub:'Управление курсом и участниками'}, apdAdminBody());
  };
  window.apdAdminTab = function(k){
    APD_ADMIN_TAB = k;
    // перерисовать только тело
    const b = document.getElementById('apdFullBody');
    if(b) b.innerHTML = apdAdminBody();
  };
  function apdAdminBody(){
    const ci = APD_ADMIN_CI;
    const tabs = APD_ADMIN_TABS.map(t=>`<button class="acd-admin-tab ${APD_ADMIN_TAB===t.k?'on':''}" onclick="apdAdminTab('${t.k}')">${I(t.ic)}<span>${esc(t.lbl)}</span></button>`).join('');
    let pane = '';
    switch(APD_ADMIN_TAB){
      case 'lessons':   pane = apdAdminLessons(ci); break;
      case 'members':   pane = apdAdminMembers(ci); break;
      case 'settings':  pane = apdAdminSettings(ci); break;
      case 'moder':     pane = apdAdminModer(ci); break;
      case 'export':    pane = apdAdminExport(ci); break;
      default:          pane = apdAdminAnalytics(ci);
    }
    return `<div class="acd-admin-tabs">${tabs}</div><div class="acd-admin-pane">${pane}</div>`;
  }

  /* Аналитика (агрегация по acS.lessons) */
  function apdAdminAnalytics(ci){
    const idx = acCourseIdx(ci);
    const c = AC_COURSES[ci];
    const meta = apdCourseMeta(ci);
    let pctSum = 0, testSum = 0, testCnt = 0, taskDone = 0, gamesDone = 0, doneLessons = 0;
    idx.forEach(i=>{
      const ls = acS.lessons[i] || {};
      pctSum += acLessonPct(i);
      if(ls.testScore){ testSum += ls.testScore; testCnt++; }
      if(ls.task) taskDone++;
      if(ls.game) gamesDone++;
      if(acLessonDone(i)) doneLessons++;
    });
    const avgPct = idx.length ? Math.round(pctSum/idx.length) : 0;
    const avgTest = testCnt ? Math.round(testSum/testCnt) : 0;
    const rnd = apdDeterministicRnd(ci+13);
    // синтетика для правдоподобных «повторных просмотров»
    const rewatch = 12 + Math.floor(rnd()*45); // среднее по курсу
    const revs = apdCourseReviews(ci);
    const rating = revs.reduce((s,r)=>s+(r.stars||5),0) / Math.max(1,revs.length);
    // per-lesson bars
    const bars = idx.map((i,k)=>{
      const p = acLessonPct(i);
      const L = AC_COURSE[i];
      return `<div class="acd-a-bar">
        <span class="n">${k+1}</span>
        <span class="t">${esc(L.title)}</span>
        <span class="pr"><i style="width:${p}%"></i></span>
        <span class="pct">${p}%</span>
      </div>`;
    }).join('');
    return `
      <div class="acd-analytics">
        <div class="acd-a-card"><span class="lbl">Средний прогресс</span><span class="val">${avgPct}%</span><span class="sub">по всем ученикам</span></div>
        <div class="acd-a-card"><span class="lbl">Средний тест</span><span class="val">${avgTest}%</span><span class="sub">из ${testCnt} сдавших</span></div>
        <div class="acd-a-card"><span class="lbl">Практика</span><span class="val">${taskDone}</span><span class="sub">${apdPlural(taskDone,['работа','работы','работ'])} зачтено</span></div>
        <div class="acd-a-card"><span class="lbl">Мини-игры</span><span class="val">${gamesDone}</span><span class="sub">пройдено</span></div>
        <div class="acd-a-card"><span class="lbl">Пройдено полностью</span><span class="val">${doneLessons}/${idx.length}</span><span class="sub">${apdPlural(doneLessons,['урок','урока','уроков'])}</span></div>
        <div class="acd-a-card"><span class="lbl">Рейтинг</span><span class="val">${rating.toFixed(1).replace('.',',')}</span><span class="sub">${revs.length} ${apdPlural(revs.length,['отзыв','отзыва','отзывов'])}</span></div>
        <div class="acd-a-card"><span class="lbl">Учеников</span><span class="val">${meta.students.toLocaleString('ru-RU')}</span><span class="sub">купили курс</span></div>
        <div class="acd-a-card"><span class="lbl">Повторные</span><span class="val">${rewatch}%</span><span class="sub">просмотры уроков</span></div>
      </div>
      <h3 style="margin:16px 0 8px;font-size:15px">Прогресс по урокам</h3>
      <div class="acd-a-bars">${bars}</div>`;
  }

  /* Список уроков + редактор */
  function apdAdminLessons(ci){
    const idx = acCourseIdx(ci);
    const rows = idx.map((i,k)=>{
      const L = AC_COURSE[i];
      return `<div class="acd-lesson-item">
        <span class="n">${k+1}</span>
        <span class="m"><b>${esc(L.title)}</b><span>${esc(acLessonSub(L))}</span></span>
        <button class="ed" onclick="apdLessonEdit(${i})" aria-label="Редактировать" title="Редактировать">${I('edit')}</button>
      </div>`;
    }).join('');
    return `<p class="dim" style="font-size:12px;line-height:1.55;margin-bottom:10px">Правки урока действуют в текущей сессии и хранятся у тебя как черновик. Синхронизация с сервером — в проде.</p>
      <div class="acd-lesson-list">${rows}</div>`;
  }
  window.apdLessonEdit = function(li){
    li = +li;
    const L = AC_COURSE[li];
    const draft = (acS.acdDrafts && acS.acdDrafts[li]) || {};
    const cur = {
      title: draft.title || L.title,
      sub:   draft.sub   || L.sub || '',
      videoUrl: draft.videoUrl || L.videoUrl || '',
      slidesJson: JSON.stringify(draft.slides || L.slides || [], null, 2),
      quizJson: JSON.stringify(draft.quiz || L.quiz || [], null, 2),
      task: (draft.task && draft.task.intro) || (L.task && L.task.intro) || ''
    };
    apdFullSetBody(`
      <button class="btn ghost sm" onclick="apdAdminTab('lessons')" style="margin-bottom:12px">${I('back')} Уроки</button>
      <h3 style="font-size:17px;margin-bottom:12px">Редактирование урока № ${li+1}</h3>
      <div class="acd-edit-form">
        <div class="acd-edit-row"><label>Заголовок</label><input id="apdEdTitle" type="text" value="${esc(cur.title)}"></div>
        <div class="acd-edit-row"><label>Подпись / описание</label><input id="apdEdSub" type="text" value="${esc(cur.sub)}"></div>
        <div class="acd-edit-row"><label>Видео URL (mp4)</label><input id="apdEdVideo" type="url" placeholder="https://…mp4" value="${esc(cur.videoUrl)}"></div>
        <div class="acd-edit-row"><label>Практика · инструкция</label><textarea id="apdEdTask" style="min-height:70px;font-family:var(--font-body);font-size:13px">${esc(cur.task)}</textarea></div>
        <div class="acd-edit-row"><label>Слайды (JSON)</label><textarea id="apdEdSlides">${esc(cur.slidesJson)}</textarea>
          <span class="acd-edit-json-help">Формат: <code>[{"t":"...","pts":["..."],"svg":"..."}]</code></span></div>
        <div class="acd-edit-row"><label>Тест (JSON)</label><textarea id="apdEdQuiz">${esc(cur.quizJson)}</textarea>
          <span class="acd-edit-json-help">Формат: <code>[{"q":"...","o":["a","b","c","d"],"a":1}]</code></span></div>
        <div class="acd-edit-actions">
          <button class="btn" onclick="apdLessonEditSave(${li})">${I('check2')} Сохранить черновик</button>
          <button class="btn ghost" onclick="apdLessonEditReset(${li})">${I('back')} Сбросить</button>
        </div>
      </div>`);
  };
  window.apdLessonEditSave = function(li){
    li = +li;
    const val = (id)=>{ const el = document.getElementById(id); return el ? el.value : ''; };
    if(!acS.acdDrafts) acS.acdDrafts = {};
    let slides, quiz;
    try{ slides = JSON.parse(val('apdEdSlides')||'[]'); if(!Array.isArray(slides)) throw 0; }
    catch(e){ toast('Слайды: невалидный JSON'); return; }
    try{ quiz = JSON.parse(val('apdEdQuiz')||'[]'); if(!Array.isArray(quiz)) throw 0; }
    catch(e){ toast('Тест: невалидный JSON'); return; }
    acS.acdDrafts[li] = {
      title: val('apdEdTitle').trim(),
      sub: val('apdEdSub').trim(),
      videoUrl: val('apdEdVideo').trim(),
      task: {intro: val('apdEdTask').trim(), chips:['Задача','Ответ'], ph:'…', verdict:'Принято.'},
      slides: slides,
      quiz: quiz
    };
    acSave();
    // применяем к AC_COURSE (in-memory)
    const L = AC_COURSE[li];
    const d = acS.acdDrafts[li];
    if(d.title) L.title = d.title;
    if(d.sub) L.sub = d.sub;
    if(d.videoUrl !== undefined) L.videoUrl = d.videoUrl;
    if(d.slides && d.slides.length) L.slides = d.slides;
    if(d.quiz && d.quiz.length) L.quiz = d.quiz;
    if(d.task && d.task.intro){ L.task = Object.assign({}, L.task||{chips:['Задача','Ответ'],ph:'…',verdict:'Принято.'}, d.task); }
    toast('Черновик урока сохранён');
    apdAdminTab('lessons');
  };
  window.apdLessonEditReset = function(li){
    li = +li;
    if(!acS.acdDrafts || !acS.acdDrafts[li]){ toast('Черновика нет'); apdAdminTab('lessons'); return; }
    delete acS.acdDrafts[li]; acSave();
    toast('Черновик сброшен — данные из курса вернулись при перезагрузке');
    apdAdminTab('lessons');
  };

  /* Участники — синтетический список (для UI) */
  function apdMembersOf(ci){
    // детерминированные mock-участники: для админа не критично, что реальный список пустой
    const c = AC_COURSES[ci];
    const rnd = apdDeterministicRnd(ci+19);
    const names = [
      {n:'Анна Григорьева', nick:'anna_g', from:'Москва'},
      {n:'Дмитрий Волков', nick:'dvolk', from:'СПб'},
      {n:'Ольга Кузнецова', nick:'olya_k', from:'Казань'},
      {n:'Илья Соколов', nick:'ilyas', from:'Новосибирск'},
      {n:'Марина Титова', nick:'mtitova', from:'Екатеринбург'},
      {n:'Кирилл Смирнов', nick:'ksmir', from:'Дубай'},
      {n:'Полина Ясенева', nick:'yasenva', from:'Минск'},
      {n:'Егор Панов', nick:'panov', from:'Алматы'},
      {n:'Роман Никитин', nick:'nikitin', from:'Тбилиси'},
      {n:'София Дорошенко', nick:'sofiid', from:'Ереван'}
    ];
    const banned = (acS.acdBanned||{})[c.id] || {};
    return names.map(x=>{
      const pct = Math.floor(rnd()*100);
      const buyAgo = ['сегодня','вчера','3 дня','неделю','2 недели','месяц'][Math.floor(rnd()*6)];
      return Object.assign({}, x, {pct, buyAgo, banned: !!banned[x.nick]});
    });
  }
  function apdAdminMembers(ci){
    const list = apdMembersOf(ci);
    const rows = list.map(m=>`<div class="acd-mem-item ${m.banned?'banned':''}">
      <span class="ava">${esc(m.n.charAt(0))}</span>
      <span class="m"><b>${esc(m.n)}</b><span>@${esc(m.nick)} · ${esc(m.from)} · куплен ${esc(m.buyAgo)} назад</span></span>
      <span class="stats"><b>${m.pct}%</b><span>прогресс</span></span>
      <div class="acd-mem-acts">
        <button onclick="apdMemberMsg('${esc(m.nick)}')" title="Написать" aria-label="Написать">${I('send')}</button>
        <button onclick="apdMemberRefund(${ci},'${esc(m.nick)}')" title="Вернуть деньги" aria-label="Вернуть">${I('money')}</button>
        <button class="danger" onclick="apdMemberBan(${ci},'${esc(m.nick)}')" title="${m.banned?'Разблокировать':'Заблокировать'}" aria-label="${m.banned?'Разблокировать':'Заблокировать'}">${I(m.banned?'check2':'trash')}</button>
      </div>
    </div>`).join('');
    return `<p class="dim" style="font-size:12px;line-height:1.55;margin-bottom:10px">${list.length} ${apdPlural(list.length,['ученик','ученика','учеников'])} · управление доступом и возвратами</p>
      <div class="acd-mem-list">${rows}</div>`;
  }
  window.apdMemberMsg = function(nick){ toast('Открыть чат с @' + nick); };
  window.apdMemberBan = function(ci, nick){
    ci = +ci;
    apdEnsureStore2();
    const c = AC_COURSES[ci];
    const b = acS.acdBanned[c.id] || {};
    if(b[nick]){ delete b[nick]; toast('Разблокирован: @' + nick); }
    else { b[nick] = 1; toast('Заблокирован: @' + nick); }
    acS.acdBanned[c.id] = b; acSave();
    apdAdminTab('members');
  };
  window.apdMemberRefund = function(ci, nick){
    if(typeof showPopup !== 'function'){ toast('Возврат оформлен · @' + nick); return; }
    ci = +ci;
    const c = AC_COURSES[ci];
    const price = apdGetSettings(ci).price || c.price || 0;
    showPopup({
      ico:'money', title:'Возврат средств',
      body:'Вернуть ' + acFmtPrice(price) + ' пользователю <b>@' + esc(nick) + '</b> за курс «' + esc(c.title) + '»? Средства спишутся с баланса курса, доступ ученика будет закрыт.',
      actions:[
        {label:'Оформить возврат', onclick:()=>{ toast('Возврат ' + acFmtPrice(price) + ' · @' + nick); }},
        {label:'Отмена', ghost:true}
      ]
    });
  };

  /* Настройки курса */
  function apdAdminSettings(ci){
    const s = apdGetSettings(ci);
    return `
      <div class="acd-set-row"><div class="m"><b>Цена курса</b><span>Основная цена (₽) — до применения скидки</span></div>
        <div class="ctl"><input type="number" min="0" step="100" value="${s.price}" onchange="apdSetSet(${ci},'price',+this.value)"></div>
      </div>
      <div class="acd-set-row"><div class="m"><b>Скидка (%)</b><span>0 — скидки нет</span></div>
        <div class="ctl"><input type="number" min="0" max="90" step="5" value="${s.discount}" onchange="apdSetSet(${ci},'discount',+this.value)"></div>
      </div>
      <div class="acd-set-row"><div class="m"><b>Курс доступен</b><span>Можно ли покупать и открывать</span></div>
        <div class="ctl">${apdTogHtml('avaTog', s.available, `apdSetSet(${ci},'available',this.checked)`)}</div>
      </div>
      <div class="acd-set-row"><div class="m"><b>Автопрогресс</b><span>Следующий урок открывается автоматически</span></div>
        <div class="ctl">${apdTogHtml('autoTog', s.autonext, `apdSetSet(${ci},'autonext',this.checked)`)}</div>
      </div>
      <div class="acd-set-row"><div class="m"><b>Выдавать сертификат</b><span>За полное прохождение направления</span></div>
        <div class="ctl">${apdTogHtml('certTog', s.certOn, `apdSetSet(${ci},'certOn',this.checked)`)}</div>
      </div>
      <div class="acd-set-row"><div class="m"><b>Комиссия платформы</b><span>10% фиксированно — от каждой продажи курса</span></div>
        <div class="ctl" style="color:var(--dim);font-size:13px;font-weight:700">10%</div>
      </div>`;
  }
  function apdTogHtml(id, on, cb){
    return `<label class="acd-tog"><input type="checkbox" id="${id}" ${on?'checked':''} onchange="${cb}"><span class="s"></span></label>`;
  }
  window.apdSetSet = function(ci, k, v){
    apdSetSetting(+ci, k, v);
    toast('Сохранено: ' + k);
  };

  /* Модерация — использует apd-комментарии из уроков курса */
  function apdAdminModer(ci){
    const idx = acCourseIdx(ci);
    let items = [];
    idx.forEach(li=>{
      const list = (acS.comments||{})[li] || [];
      list.forEach(c=>items.push({li, c}));
    });
    if(!items.length){
      return `<div class="acd-admin-empty">Комментариев к урокам этого курса пока нет.</div>`;
    }
    items = items.slice(0, 40);
    const rows = items.map(({li, c})=>`<div class="acd-mem-item">
      <span class="ava">${esc((c.name||'?').charAt(0).toUpperCase())}</span>
      <span class="m"><b>${esc(c.name||'Гость')}</b><span>Урок ${li+1} · ${esc(String((AC_COURSE[li]||{}).title||''))}</span></span>
      <div style="flex:1;min-width:0"><p style="font-size:12px;color:var(--dim);line-height:1.4;margin:0 8px;overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical">${esc(c.text)}</p></div>
      <div class="acd-mem-acts">
        <button class="danger" onclick="apdModDel(${li},'${esc(c.id)}')" title="Удалить" aria-label="Удалить">${I('trash')}</button>
      </div>
    </div>`).join('');
    return `<p class="dim" style="font-size:12px;line-height:1.55;margin-bottom:10px">${items.length} ${apdPlural(items.length,['комментарий','комментария','комментариев'])} по курсу</p>
      <div class="acd-mem-list">${rows}</div>`;
  }
  window.apdModDel = function(li, id){
    li = +li;
    const arr = (acS.comments||{})[li] || [];
    const j = arr.findIndex(x=>x.id===id);
    if(j>=0){ arr.splice(j,1); acSave(); toast('Комментарий удалён'); apdAdminTab('moder'); }
  };

  /* Экспорт CSV */
  function apdAdminExport(ci){
    const list = apdMembersOf(ci);
    return `<p class="dim" style="font-size:12.5px;line-height:1.55;margin-bottom:12px">Экспортируй список учеников этого курса в CSV: имя, ник, дата покупки, прогресс, статус доступа.</p>
      <button class="btn" onclick="apdExportCsv(${ci})">${I('file')} Скачать CSV · ${list.length} ${apdPlural(list.length,['ученик','ученика','учеников'])}</button>
      <div style="height:10px"></div>
      <p class="dim" style="font-size:11.5px;line-height:1.55">Формат: <code style="font-family:ui-monospace,monospace;background:var(--raised);padding:2px 6px;border-radius:5px">name;nick;from;buyAgo;progress;status</code></p>`;
  }
  window.apdExportCsv = function(ci){
    ci = +ci;
    const list = apdMembersOf(ci);
    const c = AC_COURSES[ci];
    const lines = ['name;nick;from;bought;progress;status'];
    list.forEach(m=>{
      lines.push([m.n, m.nick, m.from, m.buyAgo, m.pct+'%', m.banned?'banned':'active'].map(x=>String(x).replace(/;/g,',')).join(';'));
    });
    // BOM для Excel-совместимости
    const csv = '\ufeff' + lines.join('\n');
    const blob = new Blob([csv], {type:'text/csv;charset=utf-8'});
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'oko-academy-' + (c.id||'course') + '-' + list.length + '.csv';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=>URL.revokeObjectURL(url), 4000);
    toast('CSV сохранён · ' + list.length + ' ' + apdPlural(list.length,['ученик','ученика','учеников']));
  };

  /* =============================================================
     4) PDF СЕРТИФИКАТА — минимальный PDF с встроенным JPEG
     ============================================================= */
  function apdBuildPdfFromJpegDataUrl(jpegDataUrl, imgW, imgH){
    // jpegDataUrl -> latin1 binary string of JPEG bytes
    const b64 = jpegDataUrl.split(',')[1];
    const bin = atob(b64);
    const jpegBytes = new Uint8Array(bin.length);
    for(let i=0; i<bin.length; i++) jpegBytes[i] = bin.charCodeAt(i);
    // размер страницы: горизонтальная A4 при 72 dpi = 842 x 595
    const PW = 842, PH = 595;
    const scale = Math.min(PW / imgW, PH / imgH);
    const w = imgW * scale, h = imgH * scale;
    const x = (PW - w) / 2, y = (PH - h) / 2;

    const enc = new TextEncoder();
    const chunks = [];
    const offsets = [];
    let bufLen = 0;
    function push(str){
      const bytes = (str instanceof Uint8Array) ? str : enc.encode(str);
      chunks.push(bytes); bufLen += bytes.length; return bytes.length;
    }
    function pushObj(objText, extraBytes){
      offsets.push(bufLen);
      push(objText);
      if(extraBytes) push(extraBytes);
      push('\nendobj\n');
    }
    push('%PDF-1.4\n%\u00E2\u00E3\u00CF\u00D3\n');
    pushObj('1 0 obj\n<</Type /Catalog /Pages 2 0 R>>');
    pushObj('2 0 obj\n<</Type /Pages /Kids [3 0 R] /Count 1>>');
    pushObj(`3 0 obj\n<</Type /Page /Parent 2 0 R /MediaBox [0 0 ${PW} ${PH}] /Contents 4 0 R /Resources <</XObject <</Im0 5 0 R>>>>>>`);
    const stream = `q\n${w.toFixed(3)} 0 0 ${h.toFixed(3)} ${x.toFixed(3)} ${y.toFixed(3)} cm\n/Im0 Do\nQ`;
    const streamBytes = enc.encode(stream);
    pushObj(`4 0 obj\n<</Length ${streamBytes.length}>>\nstream\n`, new Uint8Array([...streamBytes, 0x0A]));
    push('endstream'); // Note: pushObj already added endobj; endstream is part of stream area — do properly:
    // Восстановим: последний "endobj" — лишний относительно stream. Пересоберём аккуратно.
    // Пересборка полностью, чтобы не было ошибок:
    chunks.length = 0; offsets.length = 0; bufLen = 0;
    push('%PDF-1.4\n%\u00E2\u00E3\u00CF\u00D3\n');
    // obj 1
    offsets.push(bufLen); push('1 0 obj\n<</Type /Catalog /Pages 2 0 R>>\nendobj\n');
    // obj 2
    offsets.push(bufLen); push('2 0 obj\n<</Type /Pages /Kids [3 0 R] /Count 1>>\nendobj\n');
    // obj 3
    offsets.push(bufLen); push(`3 0 obj\n<</Type /Page /Parent 2 0 R /MediaBox [0 0 ${PW} ${PH}] /Contents 4 0 R /Resources <</XObject <</Im0 5 0 R>>>>>>\nendobj\n`);
    // obj 4 — content stream
    offsets.push(bufLen);
    push(`4 0 obj\n<</Length ${streamBytes.length}>>\nstream\n`);
    push(streamBytes);
    push('\nendstream\nendobj\n');
    // obj 5 — image XObject
    offsets.push(bufLen);
    push(`5 0 obj\n<</Type /XObject /Subtype /Image /Width ${imgW} /Height ${imgH} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpegBytes.length}>>\nstream\n`);
    push(jpegBytes);
    push('\nendstream\nendobj\n');
    // xref
    const xrefStart = bufLen;
    push('xref\n0 6\n0000000000 65535 f \n');
    offsets.forEach(o=>push(String(o).padStart(10,'0') + ' 00000 n \n'));
    push(`trailer\n<</Size 6 /Root 1 0 R>>\nstartxref\n${xrefStart}\n%%EOF`);

    const out = new Uint8Array(bufLen);
    let p = 0;
    for(const c of chunks){ out.set(c, p); p += c.length; }
    return new Blob([out], {type:'application/pdf'});
  }
  window.apdCertPdf = function(){
    // используем текущий сертификат (в overlay или в списке)
    const rec = (typeof acCertRec === 'function' && acCertShownNo)
      ? acS.certs.find(c=>c && c.no===acCertShownNo)
      : (typeof acCertRec === 'function' ? acCertRec() : null);
    if(!rec){ toast('Сертификат не выбран'); return; }
    const build = (pngUrl)=>{
      const img = new Image();
      img.onload = ()=>{
        const cv = document.createElement('canvas');
        cv.width = img.width; cv.height = img.height;
        cv.getContext('2d').drawImage(img, 0, 0);
        const jpeg = cv.toDataURL('image/jpeg', 0.92);
        const blob = apdBuildPdfFromJpegDataUrl(jpeg, img.width, img.height);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = rec.no + '.pdf';
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(()=>URL.revokeObjectURL(url), 4000);
        toast('PDF сохранён: ' + rec.no + '.pdf');
      };
      img.onerror = ()=>toast('Не удалось собрать PDF');
      img.src = pngUrl;
    };
    if(acCertUrl && acCertShownNo === rec.no){ build(acCertUrl); return; }
    acMakeCert(rec, url=>{ acCertUrl = url; acCertShownNo = rec.no; build(url); });
  };

  /* Инъекция кнопки «Скачать PDF» в overlay сертификата (одноразово) */
  function apdInjectCertPdfButton(){
    const acts = document.querySelector('#acCertFull .ac-cert-full-actions');
    if(!acts || acts.querySelector('.acd-cert-pdf')) return;
    const btn = document.createElement('button');
    btn.className = 'btn sm ghost acd-cert-pdf';
    btn.innerHTML = I('file') + ' Скачать PDF';
    btn.onclick = apdCertPdf;
    // ставим сразу после первой кнопки
    const first = acts.querySelector('.btn');
    if(first && first.nextSibling) acts.insertBefore(btn, first.nextSibling);
    else acts.appendChild(btn);
  }

  /* =============================================================
     5) ДОП. ФОРМАТЫ УРОКА: файлы + livestream (стабы + рендер)
     ============================================================= */
  function apdLessonExtraFormats(){
    if(acView !== 'lesson') return;
    const root = document.getElementById('acRoot');
    if(!root) return;
    const L = acCur();
    if(!L) return;
    // 1) Livestream — если L.live есть, вставим карточку перед acCertBox
    const cert = document.getElementById('acCertBox');
    if(!cert) return;
    if(L.live && !root.querySelector('#apdLiveBox')){
      const box = document.createElement('div');
      box.id = 'apdLiveBox';
      box.className = 'card';
      box.style.padding = '4px';
      box.innerHTML = `<div class="acd-live" style="margin:0">
        <span class="ic">${I('circle-play')}</span>
        <div class="m"><b>Livestream: ${esc(L.live.title||'Прямой эфир')}</b><span>${esc(L.live.when||'скоро')} · ${esc(L.live.host||'ведущий')}</span></div>
        <button class="btn sm" onclick="apdLiveJoin('${esc(L.live.title||'')}')">${I('device')} Войти</button>
      </div>`;
      cert.parentNode.insertBefore(box, cert);
    }
    // 2) Файлы — если L.files есть, вставим ниже
    if(L.files && L.files.length && !root.querySelector('#apdFilesBox')){
      const box = document.createElement('div');
      box.id = 'apdFilesBox';
      box.className = 'card';
      box.style.padding = '12px 14px 14px';
      box.innerHTML = `<div style="font-size:12px;font-weight:800;letter-spacing:.09em;text-transform:uppercase;color:var(--dim);margin-bottom:8px">${I('file')} Файлы урока</div>
        <div class="acd-files">${L.files.map(f=>`<a class="acd-file" href="${esc(f.url||'#')}" target="_blank" rel="noopener noreferrer" download="${esc(f.name||'file')}">
          <span class="ic">${I('file')}</span>
          <span class="m"><b>${esc(f.name||'файл')}</b><span>${esc(f.size||'')}</span></span>
          <svg class="i dl"><use href="#i-forward"/></svg>
        </a>`).join('')}</div>`;
      cert.parentNode.insertBefore(box, cert);
    }
  }
  window.apdLiveJoin = function(title){
    if(typeof showPopup === 'function'){
      showPopup({ico:'circle-play', title:'Livestream · ' + title, body:'Прямой эфир пройдёт в модуле «Звонки ХЛБ». Уведомление придёт за 15 минут до старта.', actions:[{label:'Ок'}]});
    } else toast('Livestream: ' + title);
  };

  /* =============================================================
     Инициализация: догнать текущее состояние Академии
     ============================================================= */
  function apdBoot(){
    apdWatchCertOverlay();
    // отдельный вотчер для инъекции PDF-кнопки в фулскрин сертификата
    try{
      const t = document.getElementById('acCertFull');
      if(t){
        const obs = new MutationObserver(()=>{ if(t.classList.contains('open')) apdInjectCertPdfButton(); });
        obs.observe(t, {attributes:true, attributeFilter:['class']});
        apdInjectCertPdfButton();
      }
    }catch(e){}
    // Если Академия уже открыта — перерендерим
    const scr = document.getElementById('screen-academy');
    if(scr && scr.classList.contains('active')) acRender();
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', apdBoot);
  } else {
    setTimeout(apdBoot, 20);
  }

  /* =============================================================
     APD_MARKET_COURSES: единый пул платных курсов маркетплейса.
     Источник — CH.disc (kind:course), плюс встроенные курсы Академии.
     Пользуется этой выборкой любой каталог-виджет («Курсы от авторов»),
     без дублирования данных.
     ============================================================= */
  window.APD_MARKET_COURSES = function apdMarketCourses(){
    const out = [];
    try{
      const src = (window.CH && Array.isArray(CH.disc)) ? CH.disc : [];
      src.forEach(c=>{
        if(c && c.kind==='course' && (c.price||0)>0){
          out.push({
            id: c.id, name: c.name, desc: c.desc,
            author: c.owner || '', authorNick: c.ownerNick || '',
            price: c.price, lessons: (c.lessons||[]).length,
            students: c.subs || 0, students_now: c.students_now || 0,
            rating: (typeof c.rating==='number') ? c.rating : null,
            reviews: (typeof c.reviews==='number') ? c.reviews : 0,
            reviewsList: c.reviewsList || [],
            niche: c.niche || 'edu',
            source: 'marketplace',
          });
        }
      });
    }catch(e){}
    return out;
  };
})();

