let trIdx = 0, trOpen = false, trFirstPlace = true, trRzT = null;

/* --- persistent-state: единый ключ «тур пройден» + back-compat со старым --- */
function trSeen(){
  try{
    if(localStorage.getItem(TR_KEY)) return true;
    /* миграция старого ключа: если пользователь уже видел тур раньше — уважаем */
    if(localStorage.getItem(TR_KEY_LEGACY)){
      try{ localStorage.setItem(TR_KEY, '1'); }catch(e){}
      return true;
    }
    return false;
  }catch(e){ return true; }
}
function trMark(){ try{ localStorage.setItem(TR_KEY, '1'); }catch(e){} }
function trStoriesSeen(){ try{ return !!localStorage.getItem(TR_STORIES_KEY); }catch(e){ return true; } }
function trStoriesMark(){ try{ localStorage.setItem(TR_STORIES_KEY, '1'); }catch(e){} }

/* ============================================================
   INSTAGRAM STORIES: сторис Даниэля (5 карточек, первый заход)
   ============================================================ */
let TS = { open:false, idx:0, timer:null, start:0, dur:5400, pausedAt:0, pausedFor:0, holdT:null,
           touchX:0, touchY:0, touchT:0 };

function trStoriesBuild(){
  if(document.getElementById('trStories')) return;
  const el = document.createElement('div');
  el.id = 'trStories';
  el.setAttribute('role','dialog');
  el.setAttribute('aria-label', trT('Сторис ХЛБ','ХЛБ stories'));
  el.innerHTML = `
    <div class="ts-bars" id="tsBars"></div>
    <div class="ts-head">
      <div class="ts-author">
        <span class="ts-ava"><svg class="i"><use href="#i-logo"/></svg></span>
        <div class="ts-author-b">
          <b>Артём</b>
          <small id="tsAuthorSub">${trT('основатель ХЛБ','founder of ХЛБ')}</small>
        </div>
      </div>
      <button class="ts-close" id="tsClose" aria-label="${trT('Закрыть','Close')}" onclick="trStoriesClose()">
        <svg class="i" style="transform:rotate(45deg)"><use href="#i-plus"/></svg>
      </button>
    </div>
    <div class="ts-stage" id="tsStage"></div>
    <div class="ts-nav">
      <button class="ts-hit ts-hit-l" aria-label="${trT('Назад','Previous')}" onclick="trStoriesPrev()"></button>
      <button class="ts-hit ts-hit-r" aria-label="${trT('Дальше','Next')}" onclick="trStoriesNext()"></button>
    </div>
    <div class="ts-cta" id="tsCta">
      <button class="btn" onclick="trStoriesFinish()"><span id="tsCtaLabel">${trT('Пропустить сторис','Skip stories')}</span></button>
    </div>`;
  document.body.appendChild(el);

  /* удержание — пауза (mouse + touch) */
  el.addEventListener('mousedown', trStoriesHoldStart);
  el.addEventListener('mouseup',   trStoriesHoldEnd);
  el.addEventListener('mouseleave',trStoriesHoldEnd);
  el.addEventListener('touchstart', function(e){
    const t = e.touches[0]; if(t){ TS.touchX = t.clientX; TS.touchY = t.clientY; TS.touchT = Date.now(); }
    trStoriesHoldStart();
  }, {passive:true});
  el.addEventListener('touchend', function(e){
    trStoriesHoldEnd();
    const t = e.changedTouches[0]; if(!t) return;
    const dx = t.clientX - TS.touchX, dy = t.clientY - TS.touchY, dt = Date.now() - TS.touchT;
    /* свайп вниз > 90px за 500 мс — закрыть сторис */
    if(dy > 90 && Math.abs(dy) > Math.abs(dx) * 1.2 && dt < 500) trStoriesClose();
  }, {passive:true});
}

function trStoriesStart(cb){
  if(TS.open) return;
  trStoriesBuild();
  TS.open = true; TS.idx = 0; TS.pausedFor = 0; TS.pausedAt = 0;
  TS._onDone = cb || null;
  const ov = document.getElementById('trStories');
  requestAnimationFrame(function(){ ov.classList.add('ts-on'); });
  if(typeof nvPush === 'function')
    nvPush('view:stories', function(){ trStoriesClose(); },
      function(){ if(TS.idx > 0){ trStoriesGo(TS.idx - 1); return true; } return false; });
  trStoriesRenderBars();
  trStoriesGo(0);
}
function trStoriesRenderBars(){
  const bars = document.getElementById('tsBars');
  if(!bars) return;
  bars.innerHTML = TR_STORIES.map((_, i)=>{
    const cls = i < TS.idx ? 'done' : (i === TS.idx ? 'live' : '');
    return `<span class="ts-bar ${cls}"><i></i></span>`;
  }).join('');
}
function trStoriesGo(i){
  if(!TS.open) return;
  if(i < 0){ i = 0; }
  if(i > TR_STORIES.length - 1){ trStoriesFinish(); return; }
  TS.idx = i;
  const s = TR_STORIES[i];
  const stage = document.getElementById('tsStage');
  const authorSub = document.getElementById('tsAuthorSub');
  const ctaLabel = document.getElementById('tsCtaLabel');
  if(!stage) return;
  const isLast = i === TR_STORIES.length - 1;
  const tone = s.tone === 'lime' ? 'lime' : 'dark';
  stage.className = 'ts-stage ts-tone-' + tone;
  stage.innerHTML = `
    <div class="ts-slide" data-i="${i}">
      <div class="ts-grid"></div>
      <div class="ts-halo"></div>
      <div class="ts-ico-big">${typeof I === 'function' ? I(s.ico) : ''}</div>
      <div class="ts-content">
        <span class="ts-tag">${trStepStr(s.tag)}</span>
        <h2 class="ts-title">${trStepStr(s.title)}</h2>
        <p class="ts-text">${trStepStr(s.body)}</p>
      </div>
      <div class="ts-foot"><span class="ts-dot"></span><span class="ts-meta">${trStepStr(s.meta)}</span></div>
    </div>`;
  if(authorSub) authorSub.textContent = trStepStr(s.meta);
  if(ctaLabel) ctaLabel.textContent = isLast
    ? trT('Начать тур по ХЛБ','Start ХЛБ tour')
    : trT('Пропустить сторис','Skip stories');
  trStoriesRenderBars();
  trStoriesTimerStart();
}
function trStoriesTimerStart(){
  trStoriesTimerStop();
  TS.start = Date.now(); TS.pausedFor = 0;
  const bar = document.querySelector('#tsBars .ts-bar.live > i');
  if(bar){ bar.style.transition = 'none'; bar.style.width = '0%';
    /* force reflow, затем плавная заливка по длительности */
    void bar.offsetWidth;
    bar.style.transition = 'width ' + TS.dur + 'ms linear';
    bar.style.width = '100%';
  }
  TS.timer = setTimeout(trStoriesNext, TS.dur);
}
function trStoriesTimerStop(){
  if(TS.timer){ clearTimeout(TS.timer); TS.timer = null; }
}
function trStoriesNext(){ if(TS.idx < TR_STORIES.length - 1) trStoriesGo(TS.idx + 1); else trStoriesFinish(); }
function trStoriesPrev(){ if(TS.idx > 0) trStoriesGo(TS.idx - 1); else trStoriesGo(0); }
function trStoriesHoldStart(){
  if(!TS.open) return;
  /* удержание > 180 мс = пауза (короткий тап = переключение) */
  TS.holdT = setTimeout(function(){
    if(!TS.timer) return;
    TS.pausedAt = Date.now();
    clearTimeout(TS.timer); TS.timer = null;
    const bar = document.querySelector('#tsBars .ts-bar.live > i');
    if(bar){
      const cs = getComputedStyle(bar);
      const w = cs.width;
      bar.style.transition = 'none'; bar.style.width = w;
    }
    const ov = document.getElementById('trStories'); if(ov) ov.classList.add('ts-paused');
  }, 180);
}
function trStoriesHoldEnd(){
  if(TS.holdT){ clearTimeout(TS.holdT); TS.holdT = null; }
  if(!TS.open || TS.timer) return;
  if(!TS.pausedAt) return;
  const ov = document.getElementById('trStories'); if(ov) ov.classList.remove('ts-paused');
  /* продолжить с того же места */
  const elapsed = TS.pausedAt - TS.start;
  const left = Math.max(400, TS.dur - elapsed);
  TS.start = Date.now() - (TS.dur - left);
  TS.pausedAt = 0;
  const bar = document.querySelector('#tsBars .ts-bar.live > i');
  if(bar){
    const cs = getComputedStyle(bar);
    const cur = parseFloat(cs.width) || 0;
    const total = parseFloat(cs.getPropertyValue('width'));
    /* дозаливка bar до 100% за оставшееся время */
    void bar.offsetWidth;
    bar.style.transition = 'width ' + left + 'ms linear';
    bar.style.width = '100%';
  }
  TS.timer = setTimeout(trStoriesNext, left);
}
function trStoriesClose(){
  if(!TS.open) return;
  TS.open = false;
  trStoriesTimerStop();
  const ov = document.getElementById('trStories');
  if(ov){ ov.classList.remove('ts-on'); setTimeout(function(){ ov.remove(); }, 320); }
  if(typeof nvPop === 'function') nvPop('view:stories');
  /* закрыли крестиком / свайпом — сторис считаем показанными, но тур НЕ запускаем */
  trStoriesMark();
  const cb = TS._onDone; TS._onDone = null;
}
function trStoriesFinish(){
  if(!TS.open) return;
  TS.open = false;
  trStoriesTimerStop();
  const ov = document.getElementById('trStories');
  if(ov){ ov.classList.remove('ts-on'); setTimeout(function(){ ov.remove(); }, 320); }
  if(typeof nvPop === 'function') nvPop('view:stories');
  trStoriesMark();
  const cb = TS._onDone; TS._onDone = null;
  /* Дошли до конца — сразу запускаем интерактивный тур */
  if(typeof cb === 'function') setTimeout(cb, 240);
  else setTimeout(function(){ trStart(false); }, 240);
}

/* ---------- DOM оверлея тура ---------- */
function trBuild(){
  if(document.getElementById('trOverlay')) return;
  const el = document.createElement('div');
  el.id = 'trOverlay';
  el.innerHTML = `
    <div class="tr-hole tr-jump" id="trHole"></div>
    <div class="tr-card tr-jump" id="trCard">
      <div class="tr-arr up hide" id="trArr"></div>
      <div class="tr-body" id="trBody"></div>
      <div class="tr-foot">
        <div class="tr-dots" id="trDots"></div>
        <div class="tr-btns">
          <button class="tr-skip" id="trSkip" onclick="trSkip()">${trT('Пропустить','Skip')}</button>
          <button class="btn tr-next" id="trNext" onclick="trNext()">${trT('Далее','Next')}</button>
        </div>
      </div>
    </div>`;
  /* тап по тёмному фону — мягкий намёк на карточку (ничего не закрываем) */
  el.addEventListener('click', e => {
    if(e.target !== el) return;
    const c = document.getElementById('trCard');
    if(c){ c.style.transform = 'translateX(-50%) scale(1.02)'; setTimeout(()=>{ c.style.transform = 'translateX(-50%)'; }, 140); }
  });
  document.body.appendChild(el);
}

/* ---------- запуск / завершение тура ---------- */
function trStart(manual){
  if(trOpen) return;
  if(!manual && trSeen()) return;
  if(!manual && trBusy()){ setTimeout(trMaybeAuto, 2600); return; }  /* попап успел открыться — позже */
  if(manual && typeof closePopup === 'function') closePopup();       /* ручной запуск — дорогу туру */
  trMark();                       /* «показан один раз» — даже если пропустили */
  trBuild();
  trOpen = true; trFirstPlace = true; trIdx = 0;
  const ov = document.getElementById('trOverlay');
  requestAnimationFrame(()=>ov.classList.add('tr-on'));
  if(typeof nvPush === 'function')
    nvPush('view:tour', function(){ trClose(); },
      function(){ if(trIdx > 0){ trGo(trIdx - 1); return true; } return false; });
  trGo(0);
}
function trClose(){
  if(!trOpen) return;
  trOpen = false;
  const ov = document.getElementById('trOverlay');
  if(ov){ ov.classList.remove('tr-on'); setTimeout(()=>ov.remove(), 340); }
  if(typeof nvPop === 'function') nvPop('view:tour');
  setTimeout(trFlushQ, 600);      /* показать отложенные на время тура попапы */
}

/* ---------- попапы других модулей НЕ перебивают тур/сторис: очередь на потом ---------- */
const trPopupQ = [];
function trFlushQ(){
  if(!trPopupQ.length || trOpen || TS.open) return;
  if(document.getElementById('okoPopup')){ setTimeout(trFlushQ, 4000); return; }
  const o = trPopupQ.shift();
  if(typeof showPopup === 'function') showPopup(o);
  if(trPopupQ.length) setTimeout(trFlushQ, 6000);
}
function trSkip(){ trClose(); if(typeof toast === 'function') toast(trT('Тур можно вернуть: Профиль → «Тур по ХЛБ»','You can reopen the tour: Profile → “ХЛБ tour”')); }
function trNext(){ if(trIdx < TR_STEPS.length - 1) trGo(trIdx + 1); else trFinish(); }
function trFinish(){
  trClose();
  setTimeout(trDonePopup, 380);
}
function trDonePopup(){
  const bal = (typeof WALLET !== 'undefined' && WALLET && typeof fmtMoney === 'function')
    ? trT(` Сейчас на балансе — ${fmtMoney(WALLET.balance)}.`, ` Your balance is now ${fmtMoney(WALLET.balance)}.`) : '';
  if(typeof showPopup !== 'function'){ if(typeof toast === 'function') toast(trT('Тур завершён','Tour complete')); return; }
  showPopup({ico:'rocket', title:trT('Готово!','All set!'),
    body:trT('2 500 ₽ уже на счёте — попробуй продвижение: запусти первую кампанию в рекламном кабинете или продвинь пост из ленты.',
             '2,500 ₽ is already in your account — try promotion: launch your first campaign in Ads Manager or boost a post from the feed.') + bal,
    actions:[
      {label:trT('Попробовать продвижение','Try promotion'), onclick:()=>{
        if(typeof showTab !== 'function') return;
        if(document.getElementById('screen-ads')) showTab('ads'); else showTab('wallet');
      }},
      {label:trT('Позже','Later'), ghost:true},
    ]});
}

/* ---------- шаг тура: вкладка -> ожидание рендера -> спотлайт ---------- */
function trGo(i, dir){
  if(!trOpen) return;
  if(i < 0){ i = 0; }
  if(i > TR_STEPS.length - 1){ trFinish(); return; }
  trIdx = i; dir = dir || 1;
  const st = TR_STEPS[i];
  try{
    if(st.tab && typeof showTab === 'function'){
      const scr = document.getElementById('screen-' + st.tab);
      if(scr && !scr.classList.contains('active')) showTab(st.tab);
    }
  }catch(e){}
  trSettle(function(){
    if(!trOpen || trIdx !== i) return;
    const el = document.querySelector(st.sel);
    if(!el){ trGo(i + dir, dir); return; }           /* элемента нет — шаг пропускаем */
    /* показать элемент в вьюпорте (если он в скролле экрана) и дождаться докрутки */
    try{ if(el.closest('.screen')) el.scrollIntoView({block:'nearest'}); }catch(e){}
    requestAnimationFrame(function(){ if(trOpen && trIdx === i) trPlace(el, st); });
  });
}
/* двойной rAF + пауза: вкладка успевает отрисоваться и разложиться */
function trSettle(cb){
  requestAnimationFrame(function(){ requestAnimationFrame(function(){ setTimeout(cb, 170); }); });
}

/* ---------- геометрия: дыра + карточка + стрелка ---------- */
function trPlace(el, st){
  const hole = document.getElementById('trHole');
  const card = document.getElementById('trCard');
  const arr  = document.getElementById('trArr');
  if(!hole || !card) return;
  const vw = window.innerWidth, vh = window.innerHeight;
  const r = el.getBoundingClientRect();
  const pad = st.pad != null ? st.pad : 6;
  let x = Math.max(4, r.left - pad), y = Math.max(4, r.top - pad);
  let w = Math.min(r.width + pad * 2, vw - x - 4);
  let h = r.height + pad * 2;
  if(st.clamp && h > vh * 0.5) h = Math.round(vh * 0.5);   /* высокие блоки — режем дыру */
  if(y + h > vh - 4) h = vh - 4 - y;

  hole.style.left = x + 'px';  hole.style.top = y + 'px';
  hole.style.width = w + 'px'; hole.style.height = h + 'px';
  hole.style.borderRadius = st.round || '16px';

  /* контент карточки (анимация появления перезапускается пересозданием .tr-body) */
  const body = document.getElementById('trBody');
  body.style.animation = 'none'; void body.offsetWidth; body.style.animation = '';
  body.innerHTML = `
    <div class="tr-step-chip">${typeof I === 'function' ? I(st.ico) : ''} ${trT('шаг','step')} ${trIdx + 1} ${trT('из','of')} ${TR_STEPS.length}</div>
    <h3>${trStepStr(st.title)}</h3>
    <p>${trStepStr(st.text)}</p>`;
  document.getElementById('trDots').innerHTML = TR_STEPS.map((_, k) =>
    `<span class="${k === trIdx ? 'on' : ''}" onclick="trGo(${k})"></span>`).join('');
  const next = document.getElementById('trNext');
  next.innerHTML = trIdx === TR_STEPS.length - 1
    ? `${trT('Готово','Done')} ${typeof I === 'function' ? I('check2') : ''}`
    : `${trT('Далее','Next')} ${typeof I === 'function' ? I('chev') : ''}`;

  /* вертикаль: под дырой, если не влезает — над, иначе по центру свободной зоны */
  const ch = card.offsetHeight, gap = 16;
  let top, below = y + h + gap + ch < vh - 12;
  const above = y - gap - ch > 12;
  if(below) top = y + h + gap;
  else if(above) top = y - gap - ch;
  else { top = Math.max(12, Math.min(vh - ch - 12, y + h + gap)); below = true; }
  card.style.top = top + 'px';

  /* стрелка — к центру подсвеченного элемента */
  const cw = card.offsetWidth, cardLeft = (vw - cw) / 2;
  const ax = Math.max(18, Math.min(cw - 32, x + w / 2 - cardLeft - 7));
  arr.className = 'tr-arr ' + (below ? 'up' : 'down');
  arr.style.left = ax + 'px';

  if(trFirstPlace){
    /* первый показ — без анимации подлёта из угла */
    requestAnimationFrame(function(){
      hole.classList.remove('tr-jump'); card.classList.remove('tr-jump');
    });
    trFirstPlace = false;
  }
}

/* resize / поворот — пересчёт текущего шага */
window.addEventListener('resize', function(){
  if(!trOpen) return;
  clearTimeout(trRzT);
  trRzT = setTimeout(function(){ if(trOpen) trGo(trIdx); }, 140);
});

/* клавиатура (десктоп): Esc — пропустить, ←/→ — навигация, Enter — далее */
document.addEventListener('keydown', function(e){
  if(TS.open){
    if(e.key === 'Escape'){ e.preventDefault(); trStoriesClose(); }
    else if(e.key === 'ArrowRight'){ e.preventDefault(); trStoriesNext(); }
    else if(e.key === 'ArrowLeft'){ e.preventDefault(); trStoriesPrev(); }
    else if(e.key === 'Enter'){ e.preventDefault(); trStoriesFinish(); }
    return;
  }
  if(!trOpen) return;
  if(e.key === 'Escape'){ e.preventDefault(); trSkip(); }
  else if(e.key === 'ArrowRight'){ e.preventDefault(); trNext(); }
  else if(e.key === 'Enter'){ e.preventDefault(); trNext(); }
  else if(e.key === 'ArrowLeft'){ e.preventDefault(); if(trIdx > 0) trGo(trIdx - 1, -1); }
});

/* ---------- авто-старт: сторис + тур, один раз после первого входа ---------- */
function trBusy(){
  const auth = document.getElementById('authScreen');
  const ob = document.getElementById('onboard');
  const reg = document.getElementById('regView');
  return !!(
    (auth && !auth.classList.contains('hidden')) ||
    (ob && !ob.classList.contains('hidden')) ||
    (reg && reg.classList.contains('open')) ||
    document.getElementById('okoPopup') ||
    document.querySelector('.sheet.open') ||
    TS.open);
}
function trMaybeAuto(){
  if(trOpen || TS.open) return;
  if(typeof authed === 'function' && !authed()) return;  /* ждём логина — патчи ниже */
  if(trBusy()){ setTimeout(trMaybeAuto, 2600); return; } /* занято — попробуем позже */
  /* Первым — сторис Даниэля, если ещё не видели */
  if(!trStoriesSeen()){
    setTimeout(function(){
      if(trBusy()) { setTimeout(trMaybeAuto, 2600); return; }
      trStoriesStart(function(){ setTimeout(function(){ trStart(false); }, 220); });
    }, 650);
    return;
  }
  if(trSeen()) return;
  setTimeout(function(){ if(!trSeen() && !trOpen) trStart(false); }, 650);
}

/* ---------- строки в профиле: «Сторис Даниэля» и «Тур по ХЛБ» ---------- */
function trAddRow(){
  try{
    const rows = document.querySelectorAll('#screen-profile .prow');
    let logoutRow = null;
    rows.forEach(r => { if((r.getAttribute('onclick') || '').indexOf('doLogout') > -1) logoutRow = r; });
    if(!logoutRow) return;

    /* «Сторис Даниэля» — повторный запуск */
    if(!document.getElementById('trProwStories')){
      const bs = document.createElement('button');
      bs.className = 'prow'; bs.id = 'trProwStories';
      bs.innerHTML = `${I('play')} <span id="trRowStoriesLabel">${trT('Сторис Даниэля','Daniel’s stories')}</span> <span class="chev">${I('chev')}</span>`;
      bs.onclick = ()=>{ trStoriesStart(null); };
      logoutRow.parentNode.insertBefore(bs, logoutRow);
    }
    /* «Тур по ХЛБ» — повторный запуск */
    if(!document.getElementById('trProwTour')){
      const b = document.createElement('button');
      b.className = 'prow'; b.id = 'trProwTour';
      b.innerHTML = `${I('compass')} <span id="trRowLabel">${trT('Тур по ХЛБ','ХЛБ tour')}</span> <span class="chev">${I('chev')}</span>`;
      b.onclick = ()=>trStart(true);
      logoutRow.parentNode.insertBefore(b, logoutRow);
    }
  }catch(e){}
}

/* ---------- самоинициализация ---------- */
(function trInit(){
  trAddRow();

  /* chain-патч showPopup: во время тура/сторис попапы откладываются (см. trFlushQ) */
  if(typeof showPopup === 'function'){
    const _trPrevShowPopup = showPopup;
    showPopup = function(o){
      if(trOpen || TS.open){ trPopupQ.push(o); return; }
      _trPrevShowPopup(o);
    };
  }

  /* перевод строк профиля (i18n ядра, если доступно) */
  if(typeof regT === 'function' && typeof onLangChange === 'function' && typeof t === 'function'){
    regT({'tr.row': {ru:'Тур по ХЛБ', en:'ХЛБ tour'},
          'tr.stories': {ru:'Сторис Даниэля', en:'Daniel’s stories'}});
    onLangChange(function(){
      const l = document.getElementById('trRowLabel');
      if(l) l.textContent = t('tr.row');
      const ls = document.getElementById('trRowStoriesLabel');
      if(ls) ls.textContent = t('tr.stories');
    });
  }

  /* хук на конец онбординга и на вход — сторис/тур стартуют сразу после них */
  if(typeof obFinish === 'function'){
    const _trPrevObFinish = obFinish;
    obFinish = function(){ _trPrevObFinish(); setTimeout(trMaybeAuto, 900); };
  }
  if(typeof doLogin === 'function'){
    const _trPrevDoLogin = doLogin;
    doLogin = function(m){ _trPrevDoLogin(m); setTimeout(trMaybeAuto, 1400); };
  }

  /* уже залогинен (повторный запуск приложения, сторис/тур ещё не показаны) */
  setTimeout(trMaybeAuto, 1600);
})();

/* ===== module: navstack ===== */
/* ===== NAVSTACK: единый стек навигации — «назад» работает ВЕЗДЕ =====
   Боль: в Telegram Mini App нет браузерных кнопок назад — приходится закрывать
   всё приложение. Модуль ведёт ЕДИНСТВЕННЫЙ источник правды о том, что открыто
   поверх корневых вкладок (стек NV, LIFO), и подключает к нему три «входа»:
     1) системный back браузера/Android (history API + popstate),
     2) Telegram BackButton (window.Telegram.WebApp.BackButton),
     3) клавишу Escape на десктопе.
   Патчи open- и close-функций сохраняют прежнее поведение (chain), синхронизация с
   закрытием крестиком/оверлеем — через nvPop и observers классов .open.

   API (глобальное, префикс nv):
     nvPush(label, closeFn[, stepFn]) — слой открыт (stepFn: внутренний шаг назад,
                                        вернуть true = слой обработал back и остался)
     nvBack()  — закрыть верхний слой (или не-feed вкладка -> feed)
     nvClear() — принудительно закрыть все слои
     nvStackLabels() — отладка: метки стека снизу вверх */

/* ---------- 1. Центральный стек ---------- */
let NV = [];              /* [{label, close, step, tab}] */
let nvClosing = false;    /* close выполняется самим стеком — патчи не трогают NV */
let nvSwallow = 0;        /* сколько ближайших popstate — наши программные history.back() */
let nvTab = 'feed';       /* текущая корневая вкладка */
let nvPrevTab = 'feed';
let nvTg = null;          /* Telegram.WebApp, когда появится */

function nvFind(prefix){
  for(let i = NV.length - 1; i >= 0; i--)
    if(NV[i].label.indexOf(prefix) === 0) return NV[i];
  return null;
}
function nvPush(label, close, step){
  if(nvClosing) return;
  const top = NV[NV.length - 1];
  if(top && top.label === label){ top.close = close; return; } /* повторное открытие того же слоя */
  NV.push({label: label, close: close, step: step || null, tab: nvTab});
  try{ history.pushState({nv: NV.length}, ''); }catch(e){}
  nvUi();
}
/* прямое закрытие (крестик/оверлей/свайп/код) — убрать запись БЕЗ повторного close */
function nvPop(label){
  if(nvClosing) return;
  for(let i = NV.length - 1; i >= 0; i--){
    if(NV[i].label.indexOf(label) === 0){
      NV.splice(i, 1);
      nvDropHistory();
      break;
    }
  }
  nvUi();
}
/* съесть одну history-запись; её popstate — программный, глушим флагом-счётчиком */
function nvDropHistory(){
  nvSwallow++;
  setTimeout(function(){ if(nvSwallow > 0) nvSwallow--; }, 900); /* страховка, если popstate не пришёл */
  try{ history.back(); }catch(e){}
}
function nvArm(){ try{ history.pushState({nv: NV.length}, ''); }catch(e){} }

/* закрыть верхний слой. Возврат: 'step' — слой шагнул внутрь себя и остался,
   'closed' — слой закрыт, false — стек пуст */
function nvBackTop(){
  const rec = NV[NV.length - 1];
  if(!rec) return false;
  if(rec.step){
    let stepped = false;
    nvClosing = true;
    try{ stepped = !!rec.step(); }catch(e){}
    nvClosing = false;
    if(stepped){ nvUi(); return 'step'; }
  }
  NV.pop();
  nvClosing = true;
  try{ rec.close(); }catch(e){}
  nvClosing = false;
  nvUi();
  return 'closed';
}
/* публичный «назад»: TG BackButton, Escape, вызовы из кода */
function nvBack(){
  if(NV.length){
    if(nvBackTop() === 'closed') nvDropHistory();
  } else if(nvTab !== 'feed' && typeof showTab === 'function'){
    showTab('feed');
  }
  nvUi();
}
function nvClear(){
  while(NV.length){
    const rec = NV.pop();
    nvClosing = true;
    try{ rec.close(); }catch(e){}
    nvClosing = false;
    nvDropHistory();
  }
  nvUi();
}
function nvStackLabels(){ return NV.map(function(r){ return r.label; }); }

/* ---------- 2. BROWSER/ANDROID BACK через history API ----------
   История: [корень nvRoot] -> [взведённая nv:0] -> по записи на каждый слой.
   Пользовательский back = popstate: стек непуст -> закрыть верхний слой;
   пуст и вкладка не feed -> feed + перевзвод; пуст на feed -> перевзвод
   (приложение не «выпадает»). Логика ведётся ТОЛЬКО по стеку — глубина в
   state не является источником правды, поэтому рассинхрон самоизлечивается. */
(function nvHistoryInit(){
  try{
    if('scrollRestoration' in history) history.scrollRestoration = 'manual';
    history.replaceState({nvRoot: true}, '');
    history.pushState({nv: 0}, '');
  }catch(e){}
})();

window.addEventListener('popstate', function(ev){
  const atRoot = !!(ev.state && ev.state.nvRoot);
  let armed = false;
  if(nvSwallow > 0){
    nvSwallow--;                       /* наш программный history.back() */
  } else if(NV.length){
    if(nvBackTop() === 'step'){ nvArm(); armed = true; } /* слой остался — вернуть запись */
  } else {
    if(nvTab !== 'feed' && typeof showTab === 'function') showTab('feed');
  }
  if(atRoot && !armed) nvArm();        /* никогда не остаёмся на корне без взведённой записи */
  nvUi();
});

/* Escape на десктопе = «назад» */
document.addEventListener('keydown', function(e){
  if(e.key === 'Escape') nvBack();
});

/* ---------- 3. TELEGRAM BackButton ----------
   tg-webapp подгружает telegram-web-app.js асинхронно ПОСЛЕ navstack —
   поллим появление window.Telegram каждые 500 мс до ~12 c. */
function nvUi(){
  if(!nvTg || !nvTg.BackButton) return;
  try{
    if(NV.length || nvTab !== 'feed') nvTg.BackButton.show();
    else nvTg.BackButton.hide();
  }catch(e){}
}
(function nvTgInit(n){
  const tg = window.Telegram && window.Telegram.WebApp;
  if(tg && tg.BackButton){
    nvTg = tg;
    try{
      if(typeof tg.BackButton.onClick === 'function') tg.BackButton.onClick(function(){ nvBack(); });
      else if(typeof tg.onEvent === 'function') tg.onEvent('backButtonClicked', function(){ nvBack(); });
    }catch(e){}
    nvUi();
    return;
  }
  if(n < 24) setTimeout(function(){ nvTgInit(n + 1); }, 500);
})(0);

/* ---------- 4. ПАТЧИ ЯДРА (chain, прежнее поведение сохраняется) ---------- */

/* вкладки — НЕ стек (корневые разделы), но помним текущую/предыдущую */
if(typeof showTab === 'function'){
  const _nvShowTab = showTab;
  showTab = function(t){
    if(t !== nvTab){ nvPrevTab = nvTab; nvTab = t; }
    _nvShowTab(t);
    nvUi();
  };
}

/* sheets: не стекуются между собой (closeSheet закрывает все) — одна запись, replace */
if(typeof openSheet === 'function' && typeof closeSheet === 'function'){
  const _nvOpenSheet = openSheet, _nvCloseSheet = closeSheet;
  openSheet = function(id){
    _nvOpenSheet(id);
    const r = nvFind('sheet:');
    if(r) r.label = 'sheet:' + id;
    else nvPush('sheet:' + id, function(){ closeSheet(); });
  };
  closeSheet = function(){
    _nvCloseSheet();
    nvPop('sheet:');
  };
}

/* чат-конверсация (только mobile-layout, где появляется .conv-open) */
if(typeof openConv === 'function' && typeof closeConv === 'function'){
  const _nvOpenConv = openConv, _nvCloseConv = closeConv;
  openConv = function(id){
    _nvOpenConv(id);
    const app = document.getElementById('app');
    if(app && app.classList.contains('conv-open') && !nvFind('conv'))
      nvPush('conv', function(){ closeConv(); });
  };
  closeConv = function(){
    _nvCloseConv();
    nvPop('conv');
  };
}

/* мини-аппы (#maGrid -> .ma-view): одна запись, replace при смене вьюхи */
if(typeof openMa === 'function' && typeof closeMa === 'function'){
  const _nvOpenMa = openMa, _nvCloseMa = closeMa;
  openMa = function(id){
    _nvOpenMa(id);
    const r = nvFind('ma:');
    if(r) r.label = 'ma:' + id;
    else nvPush('ma:' + id, function(){ closeMa(); });
  };
  closeMa = function(){
    _nvCloseMa();
    nvPop('ma:');
  };
}

/* попапы core-ext: showPopup сам вызывает closePopup (replace) — глушим
   внутренний вызов флагом, чтобы не гонять history.back()+pushState впритык */
if(typeof showPopup === 'function' && typeof closePopup === 'function'){
  const _nvShowPopup = showPopup, _nvClosePopup = closePopup;
  showPopup = function(o){
    const had = !!nvFind('popup');
    const was = nvClosing;
    nvClosing = true;
    try{ _nvShowPopup(o); } finally { nvClosing = was; }
    if(!had) nvPush('popup', function(){ closePopup(); });
  };
  closePopup = function(){
    _nvClosePopup();
    nvPop('popup');
  };
}

/* HQ-embed (admin-hq уже зовёт nvPush('hq-embed') при открытии) — прямое закрытие */
if(typeof hqCloseEmbed === 'function'){
  const _nvHqCloseEmbed = hqCloseEmbed;
  hqCloseEmbed = function(){
    _nvHqCloseEmbed();
    nvPop('hq-embed');
  };
}

/* ---------- 5. FULLSCREEN-ВЬЮХИ через observers класса .open ----------
   Надёжнее патчей: ловит ЛЮБОЙ путь открытия/закрытия (крестик, оверлей,
   обходные вызовы вроде гейта админки), включая асинхронные (сертификат). */
const NV_VIEWS = [
  /* [id элемента, метка, close, step|null] */
  ['searchView',  'view:search',      function(){ closeSearch(); },      null],
  ['notifsView',  'view:notifs',      function(){ closeNotifs(); },      null],
  ['adminView',   'view:admin',       function(){ closeAdmin(); },       null],
  ['systemView',  'view:system',      function(){ closeSystemView(); },  null],
  ['editProfile', 'view:editProfile', function(){ closeEditProfile(); }, null],
  ['storyViewer', 'story',            function(){ closeStory(); },       null],
  ['msgMenu',     'menu:msg',         function(){ closeMsgMenu(); },     null],
  ['legalView',   'view:legal',       function(){ if(typeof closeLegalDoc==='function') closeLegalDoc(); }, null],
  ['acCertFull',  'view:accert',      function(){ if(typeof acCertFullClose==='function') acCertFullClose(); }, null],
  ['regView',     'view:reg',         function(){ if(typeof regClose==='function') regClose(); },
    /* назад внутри регистрации = шаг назад, с шага 1 — закрыть */
    function(){
      if(typeof REG !== 'undefined' && REG && REG.step > 1 && typeof regBack === 'function'){
        regBack(); return true;
      }
      return false;
    }],
];
function nvSyncView(id, label, close, step){
  const el = document.getElementById(id);
  const open = !!(el && el.classList.contains('open'));
  if(open){ if(!nvFind(label)) nvPush(label, close, step); }
  else nvPop(label); /* записи нет — no-op; после nvBackTop запись уже снята */
}
(function nvViewObservers(){
  NV_VIEWS.forEach(function(v){
    const el = document.getElementById(v[0]);
    if(!el) return;
    try{
      new MutationObserver(function(){ nvSyncView(v[0], v[1], v[2], v[3]); })
        .observe(el, {attributes: true, attributeFilter: ['class']});
    }catch(e){}
  });
})();

/* ---------- 6. ВНУТРЕННЯЯ НАВИГАЦИЯ РАЗДЕЛОВ ---------- */

/* Академия: список курса <-> страница урока (единая точка рендера acRender).
   Кнопка «Академия» в уроке уже есть (.ac-back) — синк идёт через рендер. */
if(typeof acRender === 'function'){
  const _nvAcRender = acRender;
  acRender = function(){
    _nvAcRender();
    if(typeof acView !== 'undefined'){
      if(acView === 'lesson'){
        if(!nvFind('ac:lesson')) nvPush('ac:lesson', function(){ acBackHome(); });
      } else {
        nvPop('ac:lesson');
      }
    }
  };
}

/* Биржа: cats <-> list/fav/пакеты — один внутренний слой 'mk:*' (replace,
   без лишних записей истории). Кнопки «Категории»/«Биржа» (.mk-back) уже есть —
   синк идёт через единую точку рендера renderMarket. */
function nvMkToCats(){ mkView = 'cats'; mkCat = null; renderMarket(); }
function nvMkSlot(label){
  const r = nvFind('mk:');
  if(r){ r.label = label; r.close = nvMkToCats; }
  else nvPush(label, nvMkToCats);
}
if(typeof renderMarket === 'function'){
  const _nvRenderMarket = renderMarket;
  renderMarket = function(){
    _nvRenderMarket();
    if(typeof mkView !== 'undefined'){
      if(mkView === 'list' || mkView === 'fav') nvMkSlot('mk:list');
      else nvPop('mk:'); /* cats = корень биржи, внутренний слой снят */
    }
  };
}

/* Пакеты ХЛБ Production (market-pro): страница поверх биржи, back -> категории */
if(typeof mpOpenPackages === 'function'){
  const _nvMpOpenPackages = mpOpenPackages;
  mpOpenPackages = function(){
    _nvMpOpenPackages();
    nvMkSlot('mk:pack');
  };
}

/* ---------- 7. САМОИНИЦИАЛИЗАЦИЯ: аудит уже открытого ---------- */
(function nvInit(){
  /* если что-то уже открыто к моменту загрузки модуля (авто-restore) — учесть */
  NV_VIEWS.forEach(function(v){ nvSyncView(v[0], v[1], v[2], v[3]); });
  const app = document.getElementById('app');
  if(app && app.classList.contains('conv-open') && !nvFind('conv') && typeof closeConv === 'function')
    nvPush('conv', function(){ closeConv(); });
  const activeScr = document.querySelector('.screen.active');
  if(activeScr && activeScr.id && activeScr.id.indexOf('screen-') === 0)
    nvTab = activeScr.id.slice(7);
  nvUi();
})();

/* ===== module: tg-webapp ===== */
/* ===== TG-WEBAPP: интеграция с Telegram Mini App (@okoappbot) =====
   Скрипт telegram-web-app.js подгружается динамически и опционально:
   вне Telegram (или офлайн) приложение работает как обычно.
   Режим: FULLSCREEN (Bot API 8.0) + учёт safe-area, чтобы шапка
   не уезжала под статус-бар телефона. */
(function tgWebAppInit(){
  /* СИНХРОНИЗАЦИЯ ВЫСОТЫ: убирает «пустоту» при скролле — высота приложения
     жёстко равна видимой области (visualViewport), а не 100dvh, который
     в Telegram-фуллскрине может считаться неверно. Работает и вне Telegram. */
  let _okoLastH = 0, _okoVhRaf = 0, _okoResizeOff = 0;
  function _okoApplyVh(){
    _okoVhRaf = 0;
    try{
      const h = Math.round((window.visualViewport && window.visualViewport.height) || window.innerHeight);
      if(!h || h === _okoLastH) return;   // не трогаем DOM, если высота не изменилась — убирает лишние reflow/моргание
      _okoLastH = h;
      document.documentElement.style.height = h + 'px';
      document.body.style.height = h + 'px';
      const app = document.getElementById('app');
      if(app) app.style.height = h + 'px';
    }catch(e){}
  }
  /* rAF-троттлинг: при открытии клавиатуры visualViewport шлёт десятки resize/сек —
     раньше каждый писал высоту в 3 элемента => лаг/дёрганье. Теперь один пересчёт за кадр.
     На время всплеска ресайза ставим декоративные анимации на паузу (класс перф-слоя). */
  function okoSyncVh(){
    try{
      const root = document.documentElement;
      if(root && !root.classList.contains('oko-scrolling')) root.classList.add('oko-scrolling');
      if(_okoResizeOff) clearTimeout(_okoResizeOff);
      _okoResizeOff = setTimeout(function(){ _okoResizeOff = 0; try{ document.documentElement.classList.remove('oko-scrolling'); }catch(e){} }, 180);
    }catch(e){}
    if(_okoVhRaf) return;
    _okoVhRaf = (window.requestAnimationFrame || window.setTimeout)(_okoApplyVh, 16);
  }
  window.addEventListener('resize', okoSyncVh);
  window.addEventListener('orientationchange', ()=>setTimeout(okoSyncVh, 120));
  if(window.visualViewport) window.visualViewport.addEventListener('resize', okoSyncVh);
  _okoApplyVh();
  setTimeout(_okoApplyVh, 400); setTimeout(_okoApplyVh, 1500);

  function applySafeArea(tg){
    try{
      const sa = tg.safeAreaInset || {top:0,bottom:0,left:0,right:0};
      const ca = tg.contentSafeAreaInset || {top:0,bottom:0,left:0,right:0};
      const top = (sa.top||0) + (ca.top||0);
      const bottom = Math.max(sa.bottom||0, 0);
      const app = document.getElementById('app');
      if(app){
        app.style.paddingTop = top + 'px';
        /* НИЖНИЙ safe-area НЕ пихаем в #app — иначе его паддинг показывает #000
           между composer/nav (--surface) и нижним баром Telegram => «тень снизу».
           Отдаём инсет в CSS-переменную, а её используют nav и composer (оба --surface),
           так низ становится сплошным --surface до самого бара Telegram. */
        app.style.paddingBottom = '0px';
      }
      try{ document.documentElement.style.setProperty('--hlb-safe-bottom', bottom + 'px'); }catch(_){}
      ['authScreen','onboard','splash'].forEach(id=>{
        const el = document.getElementById(id);
        if(el) el.style.paddingTop = top + 'px';
      });
    }catch(e){}
  }
  /* цвета Telegram-хрома (шапка, фон, нижний бар/home-indicator) — строго под тему приложения,
     чтобы в светлой теме снизу/сверху НЕ было чёрных полос («тёмная тень снизу»). */
  function okoTgColors(tg){
    try{
      const light = document.documentElement.getAttribute('data-theme') === 'light';
      /* ТОЧНОЕ соответствие CSS-токенам (иначе шов/«тень» сверху и снизу):
         dark  --bg:#000  --surface:#0d0d0d ; light --bg:#fff --surface:#f7f9f4.
         Хедер и общий фон = --bg (шапка приложения лежит на --bg);
         нижний бар = --surface (на вкладках это nav, в чате — композер, оба --surface). */
      const surf = light ? '#f7f9f4' : '#0d0d0d';
      const bg   = light ? '#ffffff' : '#000000';
      if(tg.setHeaderColor) tg.setHeaderColor(bg);
      if(tg.setBackgroundColor) tg.setBackgroundColor(bg);
      if(tg.setBottomBarColor){ try{ tg.setBottomBarColor(surf); }catch(e){} }
    }catch(e){}
  }
  /* перекрашивать хром Telegram при переключении темы в приложении */
  try{
    new MutationObserver(()=>{
      const tg = window.Telegram && window.Telegram.WebApp;
      if(tg && tg.initData) okoTgColors(tg);
    }).observe(document.documentElement, {attributes:true, attributeFilter:['data-theme']});
  }catch(e){}
  function apply(){
    const tg = window.Telegram && window.Telegram.WebApp;
    if(!tg || !tg.initData) return; // не в Telegram
    try{
      tg.ready();
      tg.expand();
      if(tg.requestFullscreen){ try{ tg.requestFullscreen(); }catch(e){} }
      okoTgColors(tg);  // цвета Telegram-хрома под тему приложения (иначе в светлой теме снизу чёрная полоса)
      if(tg.disableVerticalSwipes) tg.disableVerticalSwipes();
      if(tg.lockOrientation){ try{ tg.lockOrientation('portrait'); }catch(e){} }
      applySafeArea(tg);
      if(tg.onEvent){
        tg.onEvent('viewportChanged', okoSyncVh);
        tg.onEvent('safeAreaChanged', ()=>{applySafeArea(tg); okoSyncVh();});
        tg.onEvent('contentSafeAreaChanged', ()=>{applySafeArea(tg); okoSyncVh();});
        tg.onEvent('fullscreenChanged', ()=>{applySafeArea(tg); okoSyncVh();});
      }
      const u = tg.initDataUnsafe && tg.initDataUnsafe.user;
      if(u && u.first_name){
        PROFILE.name = u.first_name + (u.last_name ? ' ' + u.last_name : '');
        if(u.username) PROFILE.nick = u.username;
        try{ localStorage.setItem('oko-auth','tg'); }catch(e){}
        const auth = document.getElementById('authScreen');
        if(auth) auth.style.display = 'none';
        if(typeof renderMyProfile === 'function') renderMyProfile();
      }
    }catch(e){}
  }
  const s = document.createElement('script');
  s.src = 'https://telegram.org/js/telegram-web-app.js';
  s.onload = apply;
  s.onerror = function(){}; // офлайн/вне TG — молча
  document.head.appendChild(s);
})();

/* ===== module: pwa ===== */
/* ===== PWA module: service worker, установка, offline, sync, share =====
   Всё под префиксом pwa*, без эмодзи, обе темы, без внешних зависимостей.
   Экспорт наружу:
     window.okoPwaShare({title,text,url})   — Web Share API + fallback на clipboard
     window.okoPwaEnqueue(kind, payload)    — положить действие в офлайн-очередь IDB
     window.okoPwaSetSyncHandler(kind, fn)  — зарегистрировать хендлер отправки
     window.okoPwaFlushQueue()              — попытка синхронизации сейчас
*/
(function pwaModule(){
  'use strict';

  const IS_HTTPS       = location.protocol === 'https:';
  const IS_LOCAL       = location.hostname === 'localhost' || location.hostname === '127.0.0.1';
  const IS_STANDALONE  = window.matchMedia('(display-mode: standalone)').matches
                      || window.matchMedia('(display-mode: window-controls-overlay)').matches
                      || window.navigator.standalone === true;
  const UA             = navigator.userAgent || '';
  const IS_IOS         = /iPad|iPhone|iPod/.test(UA) && !window.MSStream;
  const IS_IOS_SAFARI  = IS_IOS && /Safari/i.test(UA) && !/CriOS|FxiOS|EdgiOS|OPiOS/i.test(UA);
  const LS_DECLINED    = 'oko-pwa-declined-at';
  const LS_FIRST_SEEN  = 'oko-pwa-first-seen-at';
  const LS_INSTALLED   = 'oko-pwa-installed';
  const LS_IOS_HINT    = 'oko-pwa-ios-hint-at';
  const DECLINE_COOLDOWN_MS = 30 * 24 * 60 * 60 * 1000; /* 30 дней */
  const PROMPT_DELAY_MS     = 30 * 1000;                /* 30 сек после первого захода */

  /* --------- state --------- */
  let deferredPrompt = null;
  let installTimer   = null;
  let iosTimer       = null;
  let reloadedOnce   = false;
  let waitingWorker  = null;

  /* --------- helpers --------- */
  function safeToast(msg){
    try { if (typeof window.toast === 'function') window.toast(msg); }
    catch(e){}
  }
  function nowTs(){ return Date.now(); }
  function readTs(key){ try { return +localStorage.getItem(key) || 0; } catch(e){ return 0; } }
  function writeTs(key, val){ try { localStorage.setItem(key, String(val)); } catch(e){} }
  function delTs(key){ try { localStorage.removeItem(key); } catch(e){} }

  function markProfileInstalled(){
    try {
      if (window.PROFILE) window.PROFILE.pwaInstalled = true;
      writeTs(LS_INSTALLED, 1);
    } catch(e){}
  }

  function pwaInstalledOrDeclinedRecently(){
    if (readTs(LS_INSTALLED)) return true;
    if (IS_STANDALONE) return true;
    const declined = readTs(LS_DECLINED);
    if (declined && (nowTs() - declined) < DECLINE_COOLDOWN_MS) return true;
    return false;
  }

  /* --------- INSTALL PROMPT (Android/desktop) --------- */
  function showInstallBanner(){
    const el = document.getElementById('pwa-install');
    if (!el) return;
    el.classList.add('pwa-show');
    el.setAttribute('aria-hidden', 'false');
  }
  function hideInstallBanner(){
    const el = document.getElementById('pwa-install');
    if (!el) return;
    el.classList.remove('pwa-show');
    el.setAttribute('aria-hidden', 'true');
  }

  window.pwaTriggerInstall = async function(){
    if (!deferredPrompt) { hideInstallBanner(); return; }
    try {
      deferredPrompt.prompt();
      const choice = await deferredPrompt.userChoice;
      if (choice && choice.outcome === 'accepted'){
        markProfileInstalled();
        safeToast('ХЛБ установлено');
      } else {
        writeTs(LS_DECLINED, nowTs());
      }
    } catch(e){}
    deferredPrompt = null;
    hideInstallBanner();
  };

  window.pwaDismissInstall = function(persist){
    if (persist) writeTs(LS_DECLINED, nowTs());
    hideInstallBanner();
  };

  window.addEventListener('beforeinstallprompt', ev => {
    ev.preventDefault();
    deferredPrompt = ev;
    if (pwaInstalledOrDeclinedRecently()) return;
    clearTimeout(installTimer);
    installTimer = setTimeout(() => {
      if (!deferredPrompt || pwaInstalledOrDeclinedRecently()) return;
      showInstallBanner();
    }, PROMPT_DELAY_MS);
  });

  window.addEventListener('appinstalled', () => {
    hideInstallBanner();
    hideIosHint();
    markProfileInstalled();
    delTs(LS_DECLINED);
    safeToast('ХЛБ установлено на главный экран');
  });

  /* --------- iOS: свой tooltip (у iOS Safari нет beforeinstallprompt) --------- */
  function showIosHint(){
    const el = document.getElementById('pwa-ios');
    if (!el) return;
    el.classList.add('pwa-show');
    el.setAttribute('aria-hidden', 'false');
  }
  function hideIosHint(){
    const el = document.getElementById('pwa-ios');
    if (!el) return;
    el.classList.remove('pwa-show');
    el.setAttribute('aria-hidden', 'true');
  }
  window.pwaDismissIos = function(persist){
    if (persist) writeTs(LS_IOS_HINT, nowTs());
    hideIosHint();
  };

  function maybeScheduleIosHint(){
    if (!IS_IOS_SAFARI) return;
    if (IS_STANDALONE) return;
    const shown = readTs(LS_IOS_HINT);
    if (shown && (nowTs() - shown) < DECLINE_COOLDOWN_MS) return;
    clearTimeout(iosTimer);
    iosTimer = setTimeout(showIosHint, PROMPT_DELAY_MS);
  }

  /* --------- OFFLINE indicator + sync trigger --------- */
  function paintOffline(){
    const el = document.getElementById('pwa-offline');
    const off = !navigator.onLine;
    if (el) el.classList.toggle('pwa-show', off);
    document.body.classList.toggle('pwa-offline-shift', off);
    if (!off) { setTimeout(flushSyncQueue, 300); }
  }
  window.addEventListener('online',  paintOffline);
  window.addEventListener('offline', paintOffline);

  /* --------- UPDATE toast (появление нового SW) --------- */
  function showUpdateToast(w){
    waitingWorker = w || waitingWorker;
    const el = document.getElementById('pwa-update');
    if (!el) return;
    el.classList.add('pwa-show');
  }
  function hideUpdateToast(){
    const el = document.getElementById('pwa-update');
    if (!el) return;
    el.classList.remove('pwa-show');
  }
  window.pwaApplyUpdate = function(){
    hideUpdateToast();
    try {
      if (waitingWorker) waitingWorker.postMessage({ type: 'SKIP_WAITING' });
    } catch(e){}
    setTimeout(() => { try { location.reload(); } catch(e){} }, 250);
  };

  /* --------- SERVICE WORKER --------- */
  async function registerSW(){
    if (!('serviceWorker' in navigator)) return;
    if (!IS_HTTPS && !IS_LOCAL) return;

    /* убираем устаревшие регистрации (был /sw.js в старой сборке) */
    try {
      const regs = await navigator.serviceWorker.getRegistrations();
      for (const r of regs){
        const url = (r.active && r.active.scriptURL) || (r.installing && r.installing.scriptURL) || '';
        if (/\/sw\.js(\?|$)/.test(url) && !/\/service-worker\.js/.test(url)) {
          try { await r.unregister(); } catch(e){}
        }
      }
    } catch(e){}

    try {
      const reg = await navigator.serviceWorker.register('/service-worker.js', { scope: '/' });

      /* если уже стоит waiting-воркер — сразу показать плашку обновления */
      if (reg.waiting && navigator.serviceWorker.controller){
        showUpdateToast(reg.waiting);
      }

      reg.addEventListener('updatefound', () => {
        const nw = reg.installing;
        if (!nw) return;
        nw.addEventListener('statechange', () => {
          if (nw.state === 'installed' && navigator.serviceWorker.controller){
            showUpdateToast(nw);
          }
        });
      });

      /* пассивная проверка апдейта раз в 30 мин */
      setInterval(() => { try { reg.update(); } catch(e){} }, 30 * 60 * 1000);

    } catch(e){ /* тихо */ }

    /* смена контроллера → перезагрузка ОДИН раз (свежая сборка сразу) */
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (reloadedOnce) return;
      reloadedOnce = true;
      try { location.reload(); } catch(e){}
    });

    /* сообщения от воркера (например, sync тэг) */
    navigator.serviceWorker.addEventListener('message', ev => {
      const d = ev.data || {};
      if (d.type === 'oko-sync-request') flushSyncQueue();
    });
  }

  /* --------- WEB SHARE API helper --------- */
  window.okoPwaShare = async function(o){
    o = o || {};
    const data = {};
    if (o.title) data.title = o.title;
    if (o.text)  data.text  = o.text;
    if (o.url)   data.url   = o.url;

    if (navigator.share) {
      try {
        if (!navigator.canShare || navigator.canShare(data)) {
          await navigator.share(data);
          return true;
        }
      } catch(e){
        if (e && e.name === 'AbortError') return false;
      }
    }
    /* fallback: clipboard */
    const composite = [o.title, o.text, o.url].filter(Boolean).join(' — ');
    try {
      await navigator.clipboard.writeText(composite);
      safeToast('Ссылка скопирована');
      return true;
    } catch(e){
      /* legacy fallback */
      try {
        const ta = document.createElement('textarea');
        ta.value = composite; ta.setAttribute('readonly','');
        ta.style.position='fixed'; ta.style.top='-9999px';
        document.body.appendChild(ta); ta.select();
        document.execCommand('copy'); ta.remove();
        safeToast('Ссылка скопирована');
        return true;
      } catch(err){
        safeToast('Не удалось поделиться');
        return false;
      }
    }
  };

  /* --------- OFFLINE SYNC QUEUE (IndexedDB) --------- */
  const DB_NAME = 'oko-pwa';
  const DB_VER  = 1;
  const STORE   = 'queue';
  const HANDLERS = {};
  let flushing = false;

  function openDb(){
    return new Promise((resolve, reject) => {
      try {
        const req = indexedDB.open(DB_NAME, DB_VER);
        req.onupgradeneeded = () => {
          const db = req.result;
          if (!db.objectStoreNames.contains(STORE)){
            const s = db.createObjectStore(STORE, { keyPath: 'id', autoIncrement: true });
            s.createIndex('kind', 'kind', { unique: false });
            s.createIndex('createdAt', 'createdAt', { unique: false });
          }
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror   = () => reject(req.error);
      } catch(e){ reject(e); }
    });
  }

  async function idbAdd(item){
    const db = await openDb();
    return new Promise((res, rej) => {
      const tx = db.transaction(STORE, 'readwrite');
      const s = tx.objectStore(STORE);
      const r = s.add(item);
      r.onsuccess = () => res(r.result);
      r.onerror   = () => rej(r.error);
    });
  }
  async function idbList(){
    const db = await openDb();
    return new Promise((res, rej) => {
      const tx = db.transaction(STORE, 'readonly');
      const s = tx.objectStore(STORE);
      const r = s.getAll();
      r.onsuccess = () => res(r.result || []);
      r.onerror   = () => rej(r.error);
    });
  }
  async function idbDelete(id){
    const db = await openDb();
    return new Promise((res) => {
      const tx = db.transaction(STORE, 'readwrite');
      tx.objectStore(STORE).delete(id);
      tx.oncomplete = () => res(true);
      tx.onerror    = () => res(false);
    });
  }

  window.okoPwaSetSyncHandler = function(kind, fn){
    if (!kind || typeof fn !== 'function') return;
    HANDLERS[kind] = fn;
  };

  window.okoPwaEnqueue = async function(kind, payload){
    if (!kind) return null;
    const item = { kind, payload: payload || null, createdAt: nowTs(), tries: 0 };
    try {
      const id = await idbAdd(item);
      /* если онлайн — тут же пробуем отправить */
      if (navigator.onLine) queueMicrotask(flushSyncQueue);
      else showSyncToast('Сохранено. Отправим, когда появится сеть.', 1900);
      /* пробуем зарегистрировать background sync */
      try {
        const reg = await navigator.serviceWorker.ready;
        if (reg && reg.sync) await reg.sync.register('oko-sync-queue');
      } catch(e){}
      return id;
    } catch(e){
      return null;
    }
  };

  window.okoPwaFlushQueue = function(){ return flushSyncQueue(); };

  async function flushSyncQueue(){
    if (flushing || !navigator.onLine) return;
    flushing = true;
    let list = [];
    try { list = await idbList(); } catch(e){ flushing = false; return; }
    if (!list.length){ flushing = false; return; }

    showSyncToast('Синхронизирую офлайн-действия…', 0);
    let ok = 0, fail = 0;
    for (const item of list){
      const fn = HANDLERS[item.kind];
      if (!fn){ /* нет обработчика — пропускаем, но не удаляем */ fail++; continue; }
      try {
        const done = await fn(item.payload, item);
        if (done !== false){ await idbDelete(item.id); ok++; }
        else fail++;
      } catch(e){ fail++; }
    }
    hideSyncToast();
    if (ok) safeToast(`Отправлено ${ok} офлайн-${plural(ok, 'действие','действия','действий')}`);
    flushing = false;
  }

  function plural(n, one, few, many){
    const n10 = n % 10, n100 = n % 100;
    if (n10 === 1 && n100 !== 11) return one;
    if (n10 >= 2 && n10 <= 4 && (n100 < 10 || n100 >= 20)) return few;
    return many;
  }

  let syncToastTimer = null;
  function showSyncToast(txt, autohide){
    const el = document.getElementById('pwa-sync-toast');
    const t  = document.getElementById('pwa-sync-text');
    if (!el || !t) return;
    t.textContent = txt;
    el.classList.add('pwa-show');
    clearTimeout(syncToastTimer);
    if (autohide) syncToastTimer = setTimeout(hideSyncToast, autohide);
  }
  function hideSyncToast(){
    const el = document.getElementById('pwa-sync-toast');
    if (el) el.classList.remove('pwa-show');
  }

  /* --------- SHORTCUTS: ?tab=feed|chats|wallet|academy из manifest --------- */
  function handleShortcut(){
    try {
      const url = new URL(location.href);
      const tab = url.searchParams.get('tab');
      if (!tab) return;
      const allowed = ['feed','chats','wallet','academy','mini','partner','profile'];
      if (allowed.indexOf(tab) === -1) return;
      const fire = () => { try { if (typeof window.showTab === 'function') window.showTab(tab); } catch(e){} };
      /* даём приложению отрисоваться */
      setTimeout(fire, 350);
      /* чистим URL, чтобы не залипал tab= при рестартах */
      try {
        url.searchParams.delete('tab');
        const clean = url.pathname + (url.search ? url.search : '') + url.hash;
        history.replaceState({}, '', clean);
      } catch(e){}
    } catch(e){}
  }

  /* --------- BOOT --------- */
  function boot(){
    /* first-visit stamp */
    if (!readTs(LS_FIRST_SEEN)) writeTs(LS_FIRST_SEEN, nowTs());
    /* если приложение уже установлено — фиксируем в профиле */
    if (IS_STANDALONE) markProfileInstalled();

    paintOffline();
    registerSW();
    maybeScheduleIosHint();
    handleShortcut();

    /* если onLine=true при загрузке — сразу пробуем добить очередь */
    if (navigator.onLine) setTimeout(flushSyncQueue, 1200);
  }

  if (document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', boot, { once: true });
  } else {
    boot();
  }
})();

